pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // A residual too small to hold even the smallest item (1) is dead; residuals below the
    // typical item size (>=10) are "soft dead" and grow quadratically worse.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // unusable tiny gap -> severe penalty
        if post_residual < 10 {
            score += 60.0 + (10.0 - pr) * 8.0;
        } else if post_residual < 30 {
            // soft dead space: quadratic penalty scaled by gap smallness
            score += (30.0 - pr) * (30.0 - pr) / 12.0;
        } else if post_residual < 50 {
            score += (50.0 - pr) * 0.8;
        }
    } else {
        // perfect fit: strong reward
        score -= 25.0;
    }

    // Reward tight fits relative to bin capacity (low relative wasted fraction).
    let waste_frac = pr / bin_capacity as f64;
    score += waste_frac * 40.0;

    // Open bins pressure: penalize placements that keep many bins open, encouraging
    // consolidation; but relax near the end of the stream (closing bins is fine then).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 - progress) * 1.5;
    score += pressure;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin and leaving a stranded gap.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward this
    // placement (chaining); if next item is large and post_residual is a poor gap, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (pr - nx) / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Mean residual context: placing into a bin whose residual is far below the mean
    // (i.e., consuming a nearly-full bin) is good; placing into an unusually empty
    // open bin is discouraged (prefer new-bin candidate to take fresh capacity).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.5;

    // New-bin candidate calibration: an empty bin gets a neutral-ish baseline so it is
    // chosen only when all open bins score poorly (heavy dead-space penalties).
    if bin_residual == bin_capacity {
        score += 15.0 - pressure * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = r / c;
    let placed = (bin_residual - post_residual) as f64;

    // Base: superlinear small-post-residual preference, progress-scaled.
    let mut score = p * p * (1.0 + 2.0 * x) + 0.35 * p;

    // Tightness bonus on what was just placed.
    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (8.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect fill: strong reward, escalating late when bins are scarce.
    if post_residual == 0 {
        score -= 55.0 + 10.0 * x;
    }

    // Early stream: keep bins flexible.
    score += (1.0 - x) * p * (1.0 - p) * 3.0;

    // Dead-space penalty (quadratic in usable-space loss).
    let dead = (p * (1.0 - p * 4.0)).max(0.0);
    score += dead * (2.0 + 3.0 * x) + 2.5 * dead * dead * (1.0 + x);
    if post_residual > 0 {
        let min_live = (next_item_size.max(1) as f64).min(20.0);
        if r > 0.0 && r < min_live {
            score += 3.0 * (1.0 - r / min_live) * (1.0 + x);
        }
    }

    // Tiny unrescuable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + 4.0 * x;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Fragmentation guard.
    if post_residual > 0 && post_residual < bin_capacity / 5 && x < 0.85 {
        score += 4.0;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if x > 0.5 {
            score -= 10.0 * x;
        }
    }

    // Lookahead with snugness, chaining, and two-step chain depth.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r == n {
            score -= 40.0 + 5.0 * x;
        } else if n <= r {
            let snug = 1.0 - (r - n) / c;
            score -= 10.0 * snug;
            if r >= 2.0 * n {
                score -= 4.0;
            }
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                score += 5.0;
            } else if after >= n {
                score -= 3.0;
            }
            let chain_count = (r / n).floor();
            if chain_count >= 2.0 {
                score -= 2.0 * chain_count.min(4.0);
            }
            if after > 0.0 && after < n * 0.5 && after < 25.0 {
                score += 4.0 + 3.0 * x;
            }
            if after > 0.0 && after < n * 0.1 {
                score += 3.0 + 3.0 * x;
            }
            // Exact divisibility chain — zero-waste fill guarantee.
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 2 {
                score -= 5.0 + 4.0 * x;
            }
            // Two-step chain viability.
            if after > 0.0 && (after * 2.0) >= n && after < n {
                score -= 2.0 + 2.0 * x;
            }
            // MUTATION (gen 8): harmonic chain — residual divisible by next
            // item with room for at least three copies is a compaction goldmine.
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 3 {
                score -= 3.0 + 3.0 * x;
            }
        } else {
            let waste = (n - r) / n;
            score += 15.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 8.0;
            }
            if r > 0.0 && r < 20.0 {
                score += 3.0 * (1.0 - r / 20.0);
            }
            if r > 0.0 {
                score += 5.0 * waste * (1.0 - x);
            }
            if r > 0.0 {
                let gap = n - r;
                if gap < 8.0 {
                    score += 4.0 * (1.0 - gap / 8.0) * (0.5 + x);
                }
            }
        }
    }

    // Mean-residual coupling.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.08 * dev;
    } else {
        score += 0.05 * (-dev) * (item_size as f64 / c);
    }

    // New-bin candidate handling with adaptive escape valves.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut penalty = 35.0;
        if next_item_size > 0 && r > next_item_size as f64 + 30.0 {
            penalty -= 12.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 10.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 15.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        penalty -= 8.0 * x;
        if fitting_bins_count > 0 && open_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n * 0.5 {
                penalty -= 6.0 + 6.0 * (1.0 - r / n);
            }
        }
        if item_size as f64 >= 0.7 * c && x < 0.4 {
            penalty -= 6.0;
        }
        if fitting_bins_count > 0 && post_residual > 0 && post_residual < 12 && open_bins_count > 1 {
            penalty -= 9.0;
        }
        if fitting_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < 0.15 * c && open_bins_count > 2 {
                penalty -= 5.0 + 3.0 * x;
            }
        }
        if open_bins_count > 4 && mean_residual > 0.5 * c {
            penalty -= 4.0;
        }
        if next_item_size > 0 && open_bins_count > 0 {
            let n = next_item_size as f64;
            if r < n && n > 0.6 * c {
                penalty -= 7.0 + 5.0 * x;
            }
        }
        if x > 0.8 && item_size as f64 > 0.5 * c {
            penalty -= 5.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 1 && r > 0.6 * c && mean_residual < 0.35 * c {
            penalty -= 8.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < mean_residual * 0.5 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        penalty += 10.0 * x * x;
        if x > 0.95 && open_bins_count > 1 {
            penalty -= 4.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 {
            let n = next_item_size as f64;
            if r < n && r < 0.2 * c {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        // Compare best achievable post-residual on an open bin against the
        // fresh-bin leftover; prefer the new bin when it strands less waste.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            let fresh_left = c - item_size as f64;
            if r > 0.0 && r < n && fresh_left >= n {
                penalty -= 6.0 + 6.0 * x;
            }
            if fresh_left > 0.6 * c && r < 0.1 * c && open_bins_count > 0 {
                penalty -= 5.0;
            }
            // Fresh-bin residual exactly fits the next item: zero-waste follow-up.
            if fresh_left >= n && fresh_left % n.max(1.0) < 1.0 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        // Large item early on — dedicated bin beats carving a partial one.
        if item_size as f64 > 0.55 * c && x < 0.25 && open_bins_count > 2 {
            penalty -= 5.0;
        }
        // Heavy fragmentation: opening fresh and consolidating is preferable.
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 3.0 + 3.0 * x;
        }
        // MUTATION: when the only fitting bins would leave residual smaller
        // than half the next item, opening fresh is cheap — avoids stranding.
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        // MUTATION: late stream with large mean residual — squeeze existing
        // bins harder by making fresh bins more expensive.
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        // MUTATION (gen 7): waste-budget lookahead — penalize opening a fresh
        // bin when the fresh leftover is itself an unfillable sliver, and
        // reward it when the leftover can absorb the next item snugly.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            let fresh_left = c - item_size as f64;
            if fresh_left > 0.0 && fresh_left < n {
                penalty += 8.0 + 6.0 * x; // fresh bin strands dead space too
            }
            if fresh_left >= n && fresh_left < n * 1.5 {
                penalty -= 4.0 + 4.0 * x; // snug two-item horizon
            }
        }
        // MUTATION (gen 7): mid-stream sprawl control — when many bins are
        // open and mean residual is already ample, fresh bins cost more.
        if x > 0.3 && x < 0.85 && open_bins_count > 6 && mean_residual > 0.3 * c {
            penalty += 3.0 + 3.0 * (open_bins_count as f64 - 6.0).min(6.0);
        }
        // MUTATION (gen 8): fresh-bin leftover divisibility — if the fresh
        // leftover is an exact multiple of the next item, a zero-waste chain
        // is guaranteed; make opening a bin cheap in that case.
        if fitting_bins_count > 0 && next_item_size > 1 {
            let n = next_item_size as f64;
            let fresh_left = c - item_size as f64;
            if fresh_left >= n && (fresh_left as u32) % next_item_size == 0 {
                penalty -= 3.0 + 3.0 * x;
            }
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — mildly reward filling the
    // fullest available bin, scaled by open-bin sprawl.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // MUTATION (gen 7): dead-space ratio shaping — scale the effective cost
    // of a placement by the fraction of the bin that becomes permanently
    // unusable (residual below the smallest plausible future item), pushing
    // the heuristic toward placements that keep residual live.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n {
            let dead_frac = (n - r) / n;
            score += dead_frac * dead_frac * (3.0 + 4.0 * x);
        }
    }

    // MUTATION (gen 8): live-residual yield — reward placements whose
    // post-residual can still hold the next item with room for a second
    // copy (a viable two-step horizon), scaled by stream progress so late
    // placements favor maximal compaction.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= 2.0 * n {
            score -= (1.5 + 2.5 * x) * (r / c);
        } else if r >= n {
            score -= 0.5 + 1.0 * x;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual >= 10 {
        // gap too small for typical next items but not zero waste
        score += 12.0 + 0.5 * post_residual as f64;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead space only matters if the next item cannot use it
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.8 * (next_item_size - post_residual) as f64;
    }
    // Reward residual that fits the lookahead item (usable gap)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before it closes
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 20.0);
    score += 0.6 * pressure * (0.5 + progress);

    // Prefer bins with residual close to item size (tight fit preference)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 || mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: superlinear tightness bonus on the space actually consumed.
    let placed = (bin_residual - post_residual) as f64;
    score -= 0.35 * placed;
    let tightness = placed / bin_residual.max(1) as f64;
    score -= 10.0 * tightness * tightness;

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals in (0, 10) are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Class-based reward: post_residual in the "half-class" can host large future items.
    if post_residual >= bin_capacity / 2 {
        score -= 20.0;
    }

    // Nice-chunk residuals are reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // ---- 2-step lookahead coupling ----
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let post2 = post_residual - next_item_size;
            let snug = 1.0 - post2 as f64 / bin_capacity as f64;
            score -= 15.0 + post2 as f64 * 0.3 + 10.0 * snug;
            if post2 % 10 == 0 {
                score -= 5.0;
            }
            // Bin keeps absorbing: post_residual can host the next item twice.
            if post_residual as f64 >= 2.0 * next_item_size as f64 {
                score -= 6.0;
            }
        } else {
            let waste = (next_item_size - post_residual) as f64 / next_item_size as f64;
            score += 20.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it (unless it's the new-bin candidate).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Relative-to-mean shaping: fat bins absorb items, thin bins preserved for small ones.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.10 * dev;
    } else {
        score += 0.06 * (-dev) * (item_size as f64 / bin_capacity as f64);
    }

    // Prefer filling bins below mean residual (compress variance).
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Late-stream consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mid-stream consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * post_residual as f64 * (open_bins_count as f64).ln();
    }

    // Residual fragmentation guard: avoid leaving residuals too small for
    // plausibly-sized items, unless very late in the stream.
    if post_residual > 0 && post_residual < bin_capacity / 5 && progress < 0.85 {
        score += 5.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placements are bad.
    if bin_residual == bin_capacity {
        let mut penalty = 45.0 - progress * 20.0;
        if next_item_size > 0 && post_residual as f64 > next_item_size as f64 + 30.0 {
            penalty -= 15.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 12.0;
        }
        if next_item_size > 0 && item_size == next_item_size {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 100.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
