pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    let mut score = pr;

    // Non-linear coupling of post residual with stream progress:
    // early on, prefer tight fills (low post_residual); later, weight residual quadratically.
    score += 12.0 * x * x * (0.5 + progress);

    // Reward snug fits (small post residual relative to item size) with smooth exponential term
    let snug = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * snug * snug * (1.0 - progress);

    // Penalize bins whose residual deviates from the mean residual (fragmentation control)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits perfectly into post_residual, reward this placement
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress);
    }

    // Mild penalty for spreading across many bins late in the stream
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * progress;

    // New-bin candidate: make empty bin mildly attractive only when it's a truly good deal
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: quantize post_residual into
    // capacity-fraction buckets. Small residuals (tight fits) are rewarded hard.
    let frac = post_residual as f64 / cap; // 0..1
    let class = (frac * 10.0).floor() as i32; // decile class of dead space
    score -= 12.0 * (10 - class) as f64;      // reward tighter classes

    // Perfect / near-perfect fits get a strong harmonic bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Integer-division threshold: residual divisible into coarse chunks is reusable.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot use this residual: penalize large leftover mildly
            score += 0.08 * frac * cap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer new bin only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Neutral-ish base; penalize slightly so tight existing fits win,
        // but beat very poor fits (large residuals in open bins).
        score = 55.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin can always host next item too
            score -= 8.0;
        }
        if item_size > 50 {
            score -= 5.0; // big items fine to start fresh
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - frac);

    // Prefer bins whose residual is below the mean (consolidation pressure).
    score += 0.15 * (post_residual as f64 - mean_residual).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item are wasted forever.
    // Treat gaps below a minimal usable size as double-penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 50.0;
    }

    // Squared penalty on small-but-unusable gaps (dead space in (0, ~10) range
    // is unlikely to fit future items drawn from typical distributions).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a brand-new bin when open bins could still absorb the item,
    // unless the fit is terrible (large post_residual) — then new bin is fine.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        // But if the current fit would leave a big awkward gap, soften new-bin penalty.
        if post_residual > 40 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this gap anyway; slightly reduce cost of residual here.
        score += 2.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into fuller bins.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins below mean residual early vs late in stream
    // (late in stream, close bins out aggressively).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if (post_residual as f64) < mean_residual {
        score -= 3.0 * progress;
    } else {
        score += 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral-ish baseline, slightly above good fits.
    if bin_residual == bin_capacity {
        return bin_capacity as f64 * 0.5 + 10.0;
    }

    let progress = step_index as f64 / total_items.max(1) as f64;

    // Lookahead: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-step match: strongly reward.
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportionally to tightness of the pair.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize dead space, worse for big leftovers.
            let gap = (next_item_size - post_residual) as f64;
            score += 12.0 * (gap / bin_capacity as f64);
            // Extra penalty if leftover is small-but-unusable (dead space).
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Relative to mean residual: placing in a bin below-average residual
    // (tighter bin) is good; above-average (loose bin) wastes capacity.
    let diff = mean_residual - post_residual as f64;
    score -= 0.25 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild preference for consolidation early in the stream.
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit wins (post_residual already encodes this).

    // Reward near-exact fits superlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio).powi(6);

