            score += 12.0 + 0.15 * post_residual as f64;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Lookahead: reward bins that can also host the next item snugly.
            let lookahead_fit = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - lookahead_fit / bin_capacity as f64).powi(4);
        }
    } else {
        // Last item: pure tightness, no lookahead needed.
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: make an empty bin only attractive when
    // alternatives are poor or global residuals are already fragmented.
    if bin_residual == bin_capacity {
        // Mild default penalty so open bins with decent fits win.
        score += 8.0;
        // But if existing bins are highly fragmented (mean residual small relative
        // to typical items), opening a fresh bin is good.
        if mean_residual < 0.35 * bin_capacity as f64 {
            score -= 20.0 * (1.0 - mean_residual / (bin_capacity as f64));
        }
        // Late in the stream, prefer closing out bins rather than spreading.
        if progress > 0.7 {
            score += 15.0 * (progress - 0.7) * 10.0;
        }
    } else {
        // Penalize placing into bins whose residual deviates far above the mean
        // (keeps a balanced pool of usable residuals).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev.abs().sqrt() * 10.0;

        // Reward bins that keep residuals in the "useful zone" (>= 10, <= 30).
        if post_residual >= 10 && post_residual <= 30 {
            score -= 10.0;
        }
        // Very small leftovers are wasted capacity.
        if post_residual < 10 && post_residual > 0 {
            score += 20.0;
        }
    }

    // Mild global pressure: with many open bins, discourage opening new ones.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
