    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_slack = (pr - nxt) / cap;
        if fit_slack >= 0.0 {
            // Smooth reward decaying with leftover after next item.
            score -= 0.6 * (1.0 - fit_slack) * (1.0 - fit_slack) * (1.0 + progress);
        } else {
            // Smooth penalty proportional to infeasibility.
            score += 0.4 * (-fit_slack);
        }
    }

    // Last-chance bin: strongly favor using it (smooth multiplicative discount).
    if fitting_bins_count == 1 {
        score -= 1.5;
    }

    // Mild reward for consolidating into many-bin regimes.
    score -= 0.05 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    // New-bin candidate: empty bin has pr_norm == 1; make it attractive only
    // when post-residual of existing bins would be tiny dead space or early stream.
    if bin_residual == bin_capacity {
        // Smooth gate: new bin preferred early or when item is large.
        let item_norm = item_size as f64 / cap;
        score = 0.2 + (1.0 - item_norm) * (1.0 - progress) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / (total_items.max(1) as f64);

    // ---- Harmonic class of the post-residual ----
    if post_residual == 0 {
        // Perfect closure: best possible outcome
        score -= 60.0;
    } else {
        let r = post_residual;
        // Class A: residual is a multiple of 10 -> likely reusable by future items
        if r % 10 == 0 {
            score -= 12.0;
        } else if r % 5 == 0 {
            score -= 5.0;
        } else {
            // awkward class: prime-ish / odd dead space
            score += 6.0;
        }
        // Dead-space penalty: unusably small residual (min item is 10)
        if r < 10 {
            score += 25.0;
        }
        // Sweet spot: small but still usable residual (tight fit, low waste)
        if r >= 10 && r < 25 {
            score -= 10.0;
        } else if r >= 25 && r < 50 {
            score -= 3.0;
        }
        // Integer-division threshold: residual splits into >=2 more min-items
        if r / 20 >= 2 {
            score -= 4.0;
        }
        // Lookahead coupling: would the next item fit nicely afterwards?
        if next_item_size > 0 {
            let nr = r as i64 - next_item_size as i64;
            if nr == 0 {
                score -= 25.0; // chain closure with lookahead item
            } else if nr > 0 {
                if (nr as u32) < 10 {
                    score -= 9.0; // next item consumes residual to near-closure
                }
                if (nr as u32) % 10 == 0 {
                    score -= 6.0; // leaves a harmonic residual
                }
            } else {
                // next item won't fit here: mild penalty proportional to gap
                score += (-nr) as f64 * 0.05;
            }
        }
    }

    // ---- Last-chance bin: strongly favor using the only bin that fits ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin; adjusted by stream phase and load.
        // Early in the stream or when open bins are nearly full, opening is cheap.
        let mut new_bin_score = 48.0;
        new_bin_score -= progress * 8.0;                 // later: prefer consolidating
        new_bin_score -= open_bins_count as f64 * 0.4;   // many open bins: avoid sprawl
        new_bin_score += mean_residual * 0.08;           // high mean residual: reuse bins
        if next_item_size > 0 && next_item_size <= bin_capacity {
            new_bin_score -= 2.0; // fresh bin can always host the lookahead item
        }
        score = new_bin_score;
    }

    // ---- Global context terms ----
    // Prefer bins whose residual is below the mean (fill the fullest bins first)
    score += (mean_residual - bin_residual as f64).max(-100.0) * 0.06;
    // Mild pressure toward fewer open bins as the stream progresses
    score += open_bins_count as f64 * 0.02 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "useful" residual threshold relative to typical item sizes.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        // Tiny sliver: nearly dead space -> big penalty.
        score += (10.0 - gap) * 8.0;
    } else if gap >= 10.0 && gap < 20.0 {
        // Small gap that only fits the smallest items: moderate penalty.
        score += (20.0 - gap) * 2.5;
    }

    // Reward very tight fits (post_residual small relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bins pressure: penalize placements that leave many bins open
    // with scattered residuals; encourage consolidating into few bins.
    score += open_bins_count as f64 * 0.8;

    // But counteract pressure when this bin is the last chance before
    // opening a new bin — using it avoids a fresh bin entirely.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual blocks the next item: mild penalty.
        score += 5.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean — placing into a below-average-residual bin keeps
    // large-residual bins available for larger future items.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.3;

    // New-bin candidate: opening a fresh bin is discouraged unless the
    // current item would create severe dead space in every open bin.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: slightly worse than a decent fit,
        // better than a terrible one.
        score = 60.0 + open_bins_count as f64 * 2.0;
        // Late in the stream, fewer items remain: reusing open bins matters less.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus: strongly favor bins that get filled to capacity.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the remaining space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits; reward proportionally to how well it fills the leftover.
            let fill_after_next = post_residual - next_item_size;
            score -= 0.5 * (1.0 - fill_after_next as f64 / bin_capacity as f64) * 100.0;
        } else {
            // Next item won't fit here; penalize small dead space that becomes unusable.
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += (next_item_size as f64 - waste) * 2.0;
            }
        }
    } else {
        // Last item: strongly prefer filling bins as tightly as possible.
        score -= 200.0;
    }

    // Relative-to-mean coupling: bins with residual far below the mean are scarcer
    // resources; placing here when it fits tightly is good.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.3 * (mean_residual - res);
    } else {
        score += 0.2 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; make it less
    // attractive than a good fit in an open bin, but attractive when the item is
    // large and would leave tiny unusable slivers in open bins.
    if bin_residual == bin_capacity {
        let tight_open_fit = open_bins_count > 0
            && fitting_bins_count > 0
            && (post_residual == 0 || (next_item_size > 0 && next_item_size <= post_residual));
        if tight_open_fit {
            score += 400.0; // an open bin fits well; don't open a new one
        } else {
            score -= 50.0; // prefer opening a fresh bin over a bad fit
        }
    }

    // Mild stream-progression pressure: later in the stream, consolidate more
    // aggressively to close out bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0 * (res / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for snug fits (small post_residual).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * tight * tight;

    // Perfect fit gets a strong discount.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Small dead space is nearly as good as a perfect fit.
        score -= 30.0;
    }

    // Lookahead: reward bins whose leftover can host the next item exactly,
    // penalize leftovers that are just barely too small for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 / next_item_size as f64).ln().max(0.0);
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // stranded space relative to lookahead
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize placing into bins far below mean residual (wasting roomy bins)
    // but only when many alternatives exist.
    if fitting_bins_count > 2 {
        let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 10.0 * dev;
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible,
    // prefer small post_residual); late in the stream, be greedy about closing
    // bins and slightly favor reusing existing bins over opening new ones.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let late = t * t;
    score -= 12.0 * late; // global urgency discount toward reusing bins

    // New-bin candidate: only attractive when item is large relative to
    // capacity or when open bins are all crowded (high mean residual usage).
    if bin_residual == bin_capacity {
        let crowded = mean_residual / (bin_capacity as f64);
        let big_item = item_size as f64 / bin_capacity as f64;
        // Opening is good when bins are crowded and the item is large.
        let openness = 1.0 - crowded;
        score += 20.0 + 55.0 * openness - 40.0 * big_item - 10.0 * late;
        // If this bin is the only fitting option, opening new is still
        // competitive but not free.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Avoid opening new bins early when plenty of room exists.
        score += 25.0 * (1.0 - t) * openness;
    }

    // Mild penalty per open bin: encourage consolidation when stream is long.
    score += 0.6 * (open_bins_count as f64).ln().max(0.0) * (1.0 - late);

    // Fragmentation guard: penalize leaving residuals that are hard to fill
    // (odd small gaps in 1..=9 range are worst).
    if post_residual > 0 && post_residual <= 9 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: minimize waste, weighted non-linearly by stream progress
    let mut score = norm_pr * (1.0 + 2.0 * progress * progress);

    // Smooth polynomial coupling: penalize large residuals more as stream advances
    score += 0.8 * norm_pr * norm_pr * (0.5 + progress);

    // Reward high fill ratio with diminishing returns
    score -= fill * fill * (1.0 + 0.5 * progress);

    // Lookahead: bonus if next item fits the post-residual (smooth coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let fit_gap = norm_pr - nxt;
        if fit_gap >= 0.0 {
            score -= 1.5 * (1.0 - fit_gap * fit_gap).max(0.0) * (0.5 + progress);
        } else {
            score += 0.6 * fit_gap.abs() * (1.0 + progress);
        }
    }

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 + progress * progress);
    }

    // Slight preference for tighter bins among many candidates
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Deviation from mean residual: prefer residuals near mean (smooth balance)
    score += 0.3 * (norm_pr - mean_residual / cap).abs();

    // New-bin candidate: smooth penalty scaled by stream progress and item size
    if bin_residual == bin_capacity {
        score += 1.2 + 1.5 * progress + 0.8 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "reusable" is the residual?
    // Residuals that are multiples of common small item sizes (10, 20, 25, 50)
    // are more likely to be filled later; penalize odd/dead residuals.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Modulo-class reward: leftover divisible by 10 or 25 is high-value space.
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit: strongly favored
    } else if pr % 10 == 0 && pr % 50 != 0 {
        -18.0 // clean multiple of 10
    } else if pr % 25 == 0 {
        -14.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        8.0 + (pr % 5) as f64 * 3.0 // ragged dead space penalty
    };
    score += class_bonus;

    // Integer-division threshold: leftover big enough to hold a "typical" item
    // (>= 20) is worth keeping flexible; tiny leftovers (< 10) are near-dead.
    let big_left = pr / 20; // 0..=5 harmonic bucket
    score -= big_left as f64 * 4.0;

    // Lookahead coupling: does the leftover match the next item's class?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: reward, scaled by how snugly it couples.
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0) * 0.5;
            // Harmonic match: next item and residual share a divisor class.
            if pr % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this leftover: mild penalty if leftover small.
            score += (next_item_size - pr).min(30) as f64 * 0.4;
        }
    } else {
        // Last item: any placement is fine, slight preference for tight fits.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio < 0.7 {
            score -= 25.0;
        } else {
            score -= 5.0; // poor fit: don't over-reward
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer open bins with reasonable class bonuses; only favor the new bin
    // when open-bin leftovers are ragged/dead (their class penalty pushes them up).
    if bin_residual == bin_capacity {
        // Neutral-ish base; add mild penalty so good open-bin classes win,
        // but ragged open-bin residuals (score > ~cap) will lose to it.
        score += 12.0;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Slight global preference to keep bin count down: reward using existing bins.
    if bin_residual < bin_capacity {
        score -= 3.0;
        // Coupling with mean residual: prefer bins below mean residual (tighter bins)
        // to keep a spread of usable leftovers across the fleet.
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are "unusable" for typical items are the real enemy.
    // Define dead-space threshold: residual too small to hold a meaningful item.
    let dead_threshold = 10.0_f64; // below this, gap is nearly dead
    let mid_threshold = 30.0_f64;  // gaps in (10,30] are semi-dead

    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    } else if (post_residual as f64) < dead_threshold {
        // Tiny unusable gap: heavily penalize (waste locked in).
        score += (dead_threshold - post_residual as f64) * 3.0;
    } else if (post_residual as f64) <= mid_threshold {
        // Semi-dead gap: penalize proportionally more than raw residual.
        score += (mid_threshold - post_residual as f64) * 1.5;
    } else {
        // Large residual is flexible: slight reward for leaving usable space.
        score -= (post_residual as f64 - mid_threshold) * 0.1;
    }

    // Reward tight fits: fill fraction of the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // --- Open bins pressure ---
    // Discourage opening new bins when many bins are open; encourage
    // consolidating into existing bins as open_bins_count grows.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + open_bins_count as f64 * 1.2;
    } else {
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins),
    // leaving larger-residual bins for future larger items.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 5.0;
        } else {
            // next item cannot use the gap: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Stream progression: late in the stream, be more aggressive about
    // filling bins tightly rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if !is_new_bin {
        score -= progress * 6.0;
    } else {
        score += progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score -= 0.35 * (bin_residual as f64 - post_residual as f64);

    // Exact-fill reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // ---- 2-step lookahead coupling ----
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: this bin will be exactly filled by the next item
            score -= 50.0;
        } else if post_residual >= next_item_size {
            // Next item still fits afterwards: mild bonus, scaled by snugness
            let snug = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 12.0 * snug;
        } else {
            // Dead space: next item cannot use the remainder
            let waste = (next_item_size as f64 - post_residual as f64) / next_item_size as f64;
            score += 18.0 * waste;
        }
    }

    // Relative-to-mean-residual shaping: bins with residuals near the mean are
    // "typical" targets; outliers (very large residual) should absorb big items.
    let resid_f = bin_residual as f64;
    let dev = resid_f - mean_residual;
    if dev > 0.0 {
        // Fatter-than-average bin: encourage using it up
        score -= 0.10 * dev;
    } else {
        // Thinner-than-average bin: discourage wasting it on large items
        score += 0.06 * (-dev) * (item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin, but less when current fit is terrible
        // (huge post_residual with a small next item) or few bins open.
        let mut penalty = 40.0;
        if next_item_size > 0 && post_residual as f64 > next_item_size as f64 + 30.0 {
            penalty -= 15.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        score += penalty;
    }

    // Late-stream consolidation: near the end, prefer filling existing bins
    let progress = step_index as f64 / total_items as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit emphasis: reward tight fits non-linearly.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize small dead space (< ~10) that is hard to reuse; reward larger residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 6.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 15.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here: mild penalty, scaled by how far off it is.
        score += 4.0 + 0.1 * (next_item_size as f64 - post_residual as f64).min(50.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer existing bins by default, but open a new
    // bin when fits are loose and mean residual across open bins is small.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.55;
        // Open a new bin more readily when existing bins are fragmented.
        score -= 10.0 * (mean_residual / bin_capacity as f64);
        // Early in the stream, keep bins open (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
        // If this bin is the only fitting bin, never prefer a new bin.
        if fitting_bins_count <= 1 {
            score += 1000.0;
        }
    }

    // Mild pressure against accumulating many open bins with low residual.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for filling bins with residual close to mean (balance).
    score += 0.03 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: tolerate moderate residuals mildly; late: punish residual waste quadratically.
    let coupling = norm_pr * norm_pr * (0.5 + 2.0 * progress) * 40.0;
    score += coupling;

    // Cubic term: large dead-space late in the stream is heavily penalized.
    score += norm_pr.powi(3) * 120.0 * progress;

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tight = (1.0 - norm_pr).powi(2);
    score -= tight * 30.0;

    // Lookahead: reward if next item fits into post_residual smoothly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let slack = (pr - n) / cap;
            score -= 25.0 * (1.0 - slack).powi(2);
        } else {
            // Next item won't fit: penalize proportionally to overflow amount.
            let overflow = (n - pr) / cap;
            score += 20.0 * overflow * (1.0 + progress);
        }
    }

    // Last chance bin: strongly reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Mean residual pressure: bins far below mean residual are less attractive.
    score += (mean_residual - pr) * 0.15;

    // New-bin candidate (empty bin) baseline: slightly discouraged unless residuals are high.
    if bin_residual == bin_capacity {
        score += 8.0 + 60.0 * (1.0 - progress) * 0.0 + 10.0 * (1.0 - norm_pr) * 0.0;
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item sizes
    // (10, 20, 25, 50) are more reusable; odd/prime-ish residues are dead space.
    let harmonic_bonus: u32 = if post_residual == 0 {
        60
    } else if post_residual % 50 == 0 {
        40
    } else if post_residual % 25 == 0 {
        30
    } else if post_residual % 10 == 0 {
        20
    } else if post_residual % 5 == 0 {
        10
    } else {
        0
    };
    score -= harmonic_bonus as f64;

    // Compatibility with the lookahead item: does post_residual admit next_item_size
    // exactly or with a harmonic residue?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0; // perfect two-item pairing
        } else if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            if leftover_after_next % 10 == 0 {
                score -= 15.0;
            }
            score += (leftover_after_next as f64) * 0.1;
        } else {
            score += 12.0; // lookahead item cannot follow here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let waste_if_here = (bin_residual - item_size) as f64;
        // Prefer an open bin that leaves a harmonic residual over a new bin.
        if waste_if_here <= 30.0 || harmonic_bonus >= 20 {
            score += 25.0;
        }
        // Late in the stream, consolidation matters more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild diversity penalty: avoid scattering residual space across many bins.
    score += (open_bins_count as f64) * 0.3;

    // Prefer bins whose residual is close to the mean (balanced packing).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, minimum item size)
    // are the worst outcome; make them extremely expensive.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Slightly larger "hard to fill" gaps (10..20) are also risky.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // If the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 10.0 + (10.0 - slack.min(10) as f64) * 1.5;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use the leftover: dead space penalty scaled by gap size.
        score += (post_residual as f64) * 0.8;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: penalize spreading across many bins when residual is large.
    score += open_bins_count as f64 * 0.6;

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the item simply doesn't fit anywhere else (post_residual would be huge
    // for an empty bin, so bias it based on congestion).
    if bin_residual == bin_capacity {
        let congestion = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 5.0 - congestion * 4.0;
        // Late in the stream, prefer consolidating into existing bins.
        score += (step_index as f64 / total_items.max(1) as f64) * 8.0;
    }

    // Mild preference for filling bins that are already relatively full
    // (small residual before placement = good consolidation).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills leftover
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();
        if diff < 1.0 {
            score -= 40.0; // perfect chain: next item exactly fills this bin
        } else if post >= next {
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportionally to wasted gap
            score += 5.0 + 0.5 * (next - post);
        }
    } else {
        // last item: prefer minimal post residual
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare residual against mean residual: leaving residual far below mean
    // means this bin becomes dead space relative to fleet average
    let mean_gap = mean_residual - post as f64;
    if mean_gap > 0.0 {
        score += 0.3 * mean_gap;
    } else {
        score -= 0.15 * (-mean_gap);
    }

    // New-bin candidate: only attractive if item is large or no good open fit
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        score -= 10.0 * tightness;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin anyway
        } else {
            score += 12.0 * pressure;
        }
        if next_item_size > 0 && next_item_size as f64 > post as f64 {
            score += 8.0; // fresh bin will chain with next item
        }
    }

    // Progress pressure: late in stream, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit bias: reward tight fits.
    if post_residual == 0 {
        score -= 500.0; // perfect closure is always great
    } else {
        // Non-linear tightness reward: prefer small post_residual.
        let tight = 1.0 / (1.0 + post_residual as f64 / 10.0);
        score -= 120.0 * tight;

        // Lookahead: if the next item fits into the post-residual, reward heavily.
        if next_item_size > 0 && next_item_size <= post_residual {
            let combo_waste = post_residual - next_item_size;
            score -= 80.0 / (1.0 + combo_waste as f64 / 5.0);
        } else if next_item_size > 0 {
            // Penalize leaving residual that the next item cannot use (dead space risk).
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless residual is fragmented.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it's chosen only when open bins are poor.
        score += 60.0;
        // But if mean residual across open bins is small (fragmented), new bin is attractive.
        score -= (mean_residual * 1.5).min(120.0);
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // Many open bins: discourage opening more.
        score += 3.0 * open_bins_count as f64;
    } else {
        // Reward filling bins that are already partially used (reduce bin count pressure).
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 30.0 * fill;
    }

    // Mild global pressure: when many bins are open, favor placements that close bins.
    if post_residual < 10 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    // normalized post residual
    let p = r / c;
    // base: prefer small post residual (tight fit), smooth quadratic coupling with stream progress
    let mut score = p * p * (1.0 + 2.0 * x) + 0.35 * p;
    // early stream: keep bins flexible (penalize very tight fills early, reward later)
    score += (1.0 - x) * p * (1.0 - p) * 4.0;
    // dead-space penalty: residuals too small to be useful later
    let dead = (p * (1.0 - p * 4.0)).max(0.0);
    score += dead * (2.0 + 3.0 * x);
    // last-chance bonus: only fitting bin -> strong reward to avoid new bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * (1.0 - p);
    }
    // lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= r {
            score -= 2.5 * (n / c);
        } else {
            score += 1.5 * ((n - r) / c);
        }
    }
    // prefer filling bins with larger residuals relative to mean (balance across bins)
    score += 0.15 * (mean_residual - r) / c;
    // slight preference to use already-open bins vs opening new ones
    score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: reward strongly.
    if post_residual == 0 {
