    }

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    // Residuals that form "usable classes" (>= 50, or small exact classes) are valuable.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Dead-space penalty: residuals in (0, 10) are nearly useless (min item is 1..100 but small items rare).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Class-based reward: post_residual in the "half-class" (>= 50) can host large future items.
    if post_residual >= bin_capacity / 2 {
