                score -= 2.0 * chain_count.min(4.0);
            }
            if after > 0.0 && after < n * 0.5 && after < 25.0 {
                score += 4.0 + 3.0 * x;
            }
            // Two-step lookahead: residual after next item should be zero or
            // comfortably above a plausible follow-up item.
            if after > 0.0 && after < 15.0 && next_item_size > item_size {
                score += 3.0;
            }
            // Near-perfect fit reward: leftover after next item is tiny.
            if after > 0.0 && after < n * 0.1 {
                score += 3.0 + 3.0 * x;
            }
            // NEW: exact divisibility chain — residual can absorb k copies of
            // the next item with zero remainder, a guaranteed no-waste fill.
