        // leftover can hold several copies of the next item exactly, opening
        // a new bin guarantees a zero-waste fill chain.
        if fitting_bins_count > 0 && next_item_size > 1 {
            let n = next_item_size as f64;
            let fresh_left = c - item_size as f64;
