    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        for k in 2u32..4 {
            let target = n * k as f64;
            if r < target && target - r <= 4.0 {
                score -= 1.5 + 1.5 * x;
                break;
            }
        }
    }

    score
}

