        // slightly costlier late, but only while usable residual remains.
        if open_bins_count > 3 && x > 0.3 && mean_residual > 0.2 * c {
            penalty += 0.6 * (open_bins_count as f64 - 3.0).min(6.0) * (0.3 + x);
