    if !is_new_bin && next_item_size > 0 && post_residual > 0 {
        let n = next_item_size as f64;
        let two = 2.0 * n;
        if r >= two && r < two + 4.0 {
            score -= 3.0 + 2.0 * x;
        } else if r >= n * 0.8 && r < two - 1.0 && r + n <= c {
            score += 2.0 * (1.0 - (r - n * 0.8) / (n * 1.2)) * (0.5 + x);
        }
    }

    score
}

