        }
        // Waste-budget lookahead — penalize opening a fresh bin when the
        // fresh leftover is itself an unfillable sliver, and reward it when
        // the leftover can absorb the next item snugly.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
