                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // MUTATION: waste-amortization guard — when the fresh leftover would
        // strand more absolute dead space than the worst open-bin option
        // would, make opening a new bin costlier; but if the fresh leftover
        // is smaller than the best open-bin post-residual, opening is cheap.
        if fitting_bins_count > 0 && open_bins_count > 0 {
