        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term — if the post-residual can hold the next
    // item with a leftover that is itself reusable (>= half the next item or
    // exactly zero), reward it; scaled by how many bins compete.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // MUTATION: dead-space variance pressure — among competing bins, prefer
    // the one whose post-residual stays close to the fleet mean residual
    // (keeps all bins uniformly usable), strongest mid-stream; and penalize
    // bins whose residual is far below the mean (they strand proportionally
    // more dead space relative to siblings).
    if !is_new_bin && post_residual > 0 && open_bins_count > 1 {
        let dev_r = r - mean_residual;
        if dev_r < 0.0 {
            score += 0.03 * (-dev_r) * x;
        } else if dev_r > 0.0 {
            score -= 0.02 * dev_r * (1.0 - x);
        }
    }

    // MUTATION: two-item lookahead sweep — when the post-residual can hold
    // the next item twice (or one copy plus at least half of another), the
    // bin remains highly reusable; reward it progressively.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        if r >= 2.0 * n {
            score -= 1.5 + 1.5 * x;
        } else if r >= 1.5 * n {
            score -= 0.8 + 0.8 * x;
        }
    }

    score
}

