    let mut score = r;

    // Base: superlinear tightness bonus on the space actually consumed.
    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (10.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect fill: strong reward, escalating late.
    if post_residual == 0 {
        score -= 900.0 + 100.0 * x;
    }

    // Dead-space penalty: residuals in (0, 10) are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 10.0 * x;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Half-class residuals can host large future items.
    if post_residual >= bin_capacity / 2 {
        score -= 18.0;
    }

    // Nice-chunk residuals are reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // ---- 2-step lookahead coupling ----
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r == n {
            score -= 420.0 + 20.0 * x;
        } else if n <= r {
            let post2 = post_residual - next_item_size;
            let snug = 1.0 - post2 as f64 / c;
            score -= 15.0 + post2 as f64 * 0.3 + 10.0 * snug;
            if post2 % 10 == 0 {
                score -= 5.0;
            }
            // Bin keeps absorbing: post_residual can host the next item repeatedly.
            let chain = (post_residual as f64 / n).floor();
            if chain >= 2.0 {
                score -= 3.0 * chain.min(4.0);
            }
            // Exact divisibility chain — zero-waste fill guarantee.
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 2 {
                score -= 6.0 + 4.0 * x;
            }
            // Two-step chain viability.
            if post2 > 0 && (post2 as f64 * 2.0) >= n {
                score -= 3.0 + 2.0 * x;
            }
            // Avoid stranding a sliver below half the next item.
            if post2 > 0 && (post2 as f64) < n * 0.5 {
                score += 5.0 + 4.0 * x;
            }
        } else {
            let waste = (n - r) / n;
            score += 20.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 10.0;
            }
            if post_residual > 0 {
                let gap = n - r;
                if gap < 8.0 {
                    score += 4.0 * (1.0 - gap / 8.0) * (0.5 + x);
                }
            }
        }
    }

    // Last-chance bin: strongly prefer using it (unless it's the new-bin candidate).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0 + 20.0 * x;
    }

    // Relative-to-mean shaping: fat bins absorb items, thin bins preserved.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.10 * dev;
    } else {
        score += 0.06 * (-dev) * (item_size as f64 / c);
    }

    // Prefer filling bins below mean residual (compress variance).
    score -= (mean_residual - r) * 0.5;

    // Late-stream consolidation.
    score -= 8.0 * x * (1.0 - p);

    // Mid-stream consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Residual fragmentation guard.
    if post_residual > 0 && post_residual < bin_capacity / 5 && x < 0.85 {
        score += 5.0;
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
        }
    }

    // Awkward-fraction dead-space pressure, strongest mid-stream.
    if !is_new_bin && post_residual > 0 {
        let dp = p.min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // ---- New-bin candidate handling ----
    if is_new_bin {
        let fresh_left = c - item_size as f64;
        let mut penalty = 45.0 - progress_none(x) * 20.0;
        if next_item_size > 0 && r > next_item_size as f64 + 30.0 {
            penalty -= 15.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 12.0;
        }
        if next_item_size > 0 && item_size == next_item_size {
            penalty += 10.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 18.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 100.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        // Fresh-bin leftover exactly/nearly fits the next item.
        if next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 7.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 {
                    penalty -= 3.0 + 2.0 * x;
                }
            }
            if fresh_left >= n && r > 0.0 && r < n {
                penalty -= 6.0 + 6.0 * x;
            }
        }
        // Near-perfect fresh fill.
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Only fitting bin strands less than half the next item — go fresh.
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 8.0 + 5.0 * x;
        }
        // Heavy fragmentation: fresh + consolidation is preferable.
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 4.0 + 3.0 * x;
        }
        // Late stream with large mean residual — squeeze existing bins harder.
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        // Waste-budget coupling.
        if open_bins_count > 0 {
            let frag = mean_residual / c;
            if frag < 0.3 {
                penalty += (0.3 - frag) * 20.0 * (1.0 - x);
            } else if frag > 0.55 && open_bins_count > 3 {
                penalty -= (frag - 0.55) * 18.0 * (0.5 + x);
            }
        }
        penalty += 10.0 * x * x;
        if x > 0.95 && open_bins_count > 1 {
            penalty -= 4.0;
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    score
}

fn progress_none(x: f64) -> f64 { x }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = r / c;
    let placed = (bin_residual - post_residual) as f64;

    // Base: superlinear small-post-residual preference, progress-scaled.
    let mut score = p * p * (1.0 + 2.0 * x) + 0.35 * p;

    // Tightness bonus on what was just placed.
    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (8.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect fill: strong reward, escalating late when bins are scarce.
    if post_residual == 0 {
        score -= 55.0 + 10.0 * x;
    }

    // Early stream: keep bins flexible.
    score += (1.0 - x) * p * (1.0 - p) * 3.0;

    // Dead-space penalty (quadratic in usable-space loss).
    let dead = (p * (1.0 - p * 4.0)).max(0.0);
    score += dead * (2.0 + 3.0 * x) + 2.5 * dead * dead * (1.0 + x);
    if post_residual > 0 {
        let min_live = (next_item_size.max(1) as f64).min(20.0);
        if r > 0.0 && r < min_live {
            score += 3.0 * (1.0 - r / min_live) * (1.0 + x);
        }
    }

    // Tiny unrescuable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + 4.0 * x;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Fragmentation guard.
    if post_residual > 0 && post_residual < bin_capacity / 5 && x < 0.85 {
        score += 4.0;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if x > 0.5 {
            score -= 10.0 * x;
        }
    }

    // Lookahead with snugness, chaining, and two-step chain depth.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r == n {
            score -= 40.0 + 5.0 * x;
        } else if n <= r {
            let snug = 1.0 - (r - n) / c;
            score -= 10.0 * snug;
            if r >= 2.0 * n {
                score -= 4.0;
            }
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                score += 5.0;
            } else if after >= n {
                score -= 3.0;
            }
            let chain_count = (r / n).floor();
            if chain_count >= 2.0 {
                score -= 2.0 * chain_count.min(4.0);
            }
            if after > 0.0 && after < n * 0.5 && after < 25.0 {
                score += 4.0 + 3.0 * x;
            }
            if after > 0.0 && after < n * 0.1 {
                score += 3.0 + 3.0 * x;
            }
            // Exact divisibility chain — zero-waste fill guarantee.
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 2 {
                score -= 5.0 + 4.0 * x;
            }
            // Two-step chain viability.
            if after > 0.0 && (after * 2.0) >= n && after < n {
                score -= 2.0 + 2.0 * x;
            }
            // Post-fit residual that is itself a multiple of the next item
            // promises a fully consumable chain — reward deeply.
            if after > 0.0 && next_item_size > 0 && after as u32 % next_item_size == 0 {
                score -= 3.0 + 3.0 * x;
            }
        } else {
            let waste = (n - r) / n;
            score += 15.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 8.0;
            }
            if r > 0.0 && r < 20.0 {
                score += 3.0 * (1.0 - r / 20.0);
            }
            if r > 0.0 {
                score += 5.0 * waste * (1.0 - x);
            }
            if r > 0.0 {
                let gap = n - r;
                if gap < 8.0 {
                    score += 4.0 * (1.0 - gap / 8.0) * (0.5 + x);
                }
            }
        }
    }

    // Mean-residual coupling.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.08 * dev;
    } else {
        score += 0.05 * (-dev) * (item_size as f64 / c);
    }

    // New-bin candidate handling with adaptive escape valves.
    let is_new_bin = bin_residual == bin_capacity;
    let fresh_left = c - item_size as f64;
    if is_new_bin {
        let mut penalty = 35.0;
        if next_item_size > 0 && r > next_item_size as f64 + 30.0 {
            penalty -= 12.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 10.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 15.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        penalty -= 8.0 * x;
        if fitting_bins_count > 0 && open_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n * 0.5 {
                penalty -= 6.0 + 6.0 * (1.0 - r / n);
            }
        }
        if item_size as f64 >= 0.7 * c && x < 0.4 {
            penalty -= 6.0;
        }
        if fitting_bins_count > 0 && post_residual > 0 && post_residual < 12 && open_bins_count > 1 {
            penalty -= 9.0;
        }
        if fitting_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < 0.15 * c && open_bins_count > 2 {
                penalty -= 5.0 + 3.0 * x;
            }
        }
        if open_bins_count > 4 && mean_residual > 0.5 * c {
            penalty -= 4.0;
        }
        if next_item_size > 0 && open_bins_count > 0 {
            let n = next_item_size as f64;
            if r < n && n > 0.6 * c {
                penalty -= 7.0 + 5.0 * x;
            }
        }
        if x > 0.8 && item_size as f64 > 0.5 * c {
            penalty -= 5.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 1 && r > 0.6 * c && mean_residual < 0.35 * c {
            penalty -= 8.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < mean_residual * 0.5 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        penalty += 10.0 * x * x;
        if x > 0.95 && open_bins_count > 1 {
            penalty -= 4.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 {
            let n = next_item_size as f64;
            if r < n && r < 0.2 * c {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n && fresh_left >= n {
                penalty -= 6.0 + 6.0 * x;
            }
            if fresh_left > 0.6 * c && r < 0.1 * c && open_bins_count > 0 {
                penalty -= 5.0;
            }
            if fresh_left >= n && fresh_left % n.max(1.0) < 1.0 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        if item_size as f64 > 0.55 * c && x < 0.25 && open_bins_count > 2 {
            penalty -= 5.0;
        }
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 3.0 + 3.0 * x;
        }
        // Only fitting bin strands less than half the next item — open fresh.
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        // Late stream with large mean residual — squeeze existing bins.
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        // Waste-budget coupling — when total stranded residual is small
        // relative to the stream, fresh bins get pricier; when fragmentation
        // is high, they get cheaper. Drives compaction.
        if open_bins_count > 0 {
            let frag = mean_residual / c;
            let sprawl = open_bins_count as f64;
            if frag < 0.3 {
                penalty += (0.3 - frag) * 20.0 * (1.0 - x);
            } else if frag > 0.55 && sprawl > 3.0 {
                penalty -= (frag - 0.55) * 18.0 * (0.5 + x);
            }
        }
        // Near-perfect fresh fill — if the item almost exactly fills a new
        // bin, opening it is nearly free.
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Fresh-bin leftover divisibility sweep — reward when the fresh
        // leftover can absorb several copies of the next item exactly.
        if next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 6.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // Mid-stream sprawl control.
        if x > 0.3 && x < 0.85 && open_bins_count > 6 && mean_residual > 0.3 * c {
            penalty += 3.0 + 3.0 * (open_bins_count as f64 - 6.0).min(6.0);
        }
        // Dead-space budget comparison — open fresh when it wastes strictly
        // less than the best open-bin leftover below the next item.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            let open_waste = if r < n { n - r } else { 0.0 };
            let fresh_waste = if fresh_left < n { n - fresh_left } else { 0.0 };
            if open_waste > fresh_waste + 1.0 {
                penalty -= (open_waste - fresh_waste).min(15.0) * (0.4 + 0.4 * x);
            } else if fresh_waste > open_waste + 1.0 {
                penalty += (fresh_waste - open_waste).min(15.0) * (0.3 + 0.3 * x);
            }
        }
        // Fresh-bin leftover divisibility chain — opening is nearly
        // dead-space-free.
        if next_item_size > 0 {
            let n = next_item_size.max(1);
            let fl = c - item_size as u32;
            if fl >= n * 2 && fl % n == 0 {
                penalty -= 6.0 + 5.0 * x;
            }
        }
        // Dead sliver on open bins while fresh leftover stays live — open fresh.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 {
            let n = next_item_size as f64;
            if r < n * 0.25 && fresh_left >= n {
                penalty -= 5.0 + 5.0 * x;
            }
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — reward filling the fullest bin.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio shaping — penalize placements that leave residual
    // below the next item size (permanently unusable space).
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n {
            let dead_frac = (n - r) / n;
            score += dead_frac * dead_frac * (3.0 + 4.0 * x);
        }
    }

    // Awkward-fraction residual pressure, strongest mid-stream.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term — post-residual hosting the next item with
    // a reusable leftover is rewarded.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // Fine-grained discrimination among multiple fitting bins: prefer the
    // bin whose leftover can host the next item; penalize leftovers just
    // below the next size proportionally.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
        let n = next_item_size as f64;
        if r >= n {
            let snug = 1.0 - (r - n) / n;
            score -= 2.5 * snug * (0.5 + x);
        } else {
            let frac = r / n;
            score += 2.0 * frac * (1.0 + x);
        }
    }

    // Live-space preservation among several fitting bins.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
        let n = next_item_size as f64;
        if r < n && r < 15.0 {
            score += 4.0 + 3.0 * x;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = r / c;
    let placed = (bin_residual - post_residual) as f64;

    // Base: superlinear small-post-residual preference, progress-scaled.
    let mut score = p * p * (1.0 + 2.0 * x) + 0.35 * p;

    // Tightness bonus on what was just placed.
    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (8.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect fill: strong reward, escalating late when bins are scarce.
    if post_residual == 0 {
        score -= 55.0 + 10.0 * x;
    }

    // Early stream: keep bins flexible.
    score += (1.0 - x) * p * (1.0 - p) * 3.0;

    // Dead-space penalty (quadratic in usable-space loss).
    let dead = (p * (1.0 - p * 4.0)).max(0.0);
    score += dead * (2.0 + 3.0 * x) + 2.5 * dead * dead * (1.0 + x);
    if post_residual > 0 {
        let min_live = (next_item_size.max(1) as f64).min(20.0);
        if r > 0.0 && r < min_live {
            score += 3.0 * (1.0 - r / min_live) * (1.0 + x);
        }
    }

    // Tiny unrescuable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + 4.0 * x;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Fragmentation guard.
    if post_residual > 0 && post_residual < bin_capacity / 5 && x < 0.85 {
        score += 4.0;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if x > 0.5 {
            score -= 10.0 * x;
        }
    }

    // Lookahead with snugness, chaining, and two-step chain depth.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r == n {
            score -= 40.0 + 5.0 * x;
        } else if n <= r {
            let snug = 1.0 - (r - n) / c;
            score -= 10.0 * snug;
            if r >= 2.0 * n {
                score -= 4.0;
            }
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                score += 5.0;
            } else if after >= n {
                score -= 3.0;
            }
            let chain_count = (r / n).floor();
            if chain_count >= 2.0 {
                score -= 2.0 * chain_count.min(4.0);
            }
            if after > 0.0 && after < n * 0.5 && after < 25.0 {
                score += 4.0 + 3.0 * x;
            }
            if after > 0.0 && after < n * 0.1 {
                score += 3.0 + 3.0 * x;
            }
            // Exact divisibility chain — zero-waste fill guarantee.
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 2 {
                score -= 5.0 + 4.0 * x;
            }
            // Two-step chain viability.
            if after > 0.0 && (after * 2.0) >= n && after < n {
                score -= 2.0 + 2.0 * x;
            }
            // Harmonic chain — residual divisible by next item with room for
            // at least three copies is a compaction goldmine.
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 3 {
                score -= 3.0 + 3.0 * x;
            }
        } else {
            let waste = (n - r) / n;
            score += 15.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 8.0;
            }
            if r > 0.0 && r < 20.0 {
                score += 3.0 * (1.0 - r / 20.0);
            }
            if r > 0.0 {
                score += 5.0 * waste * (1.0 - x);
            }
            if r > 0.0 {
                let gap = n - r;
                if gap < 8.0 {
                    score += 4.0 * (1.0 - gap / 8.0) * (0.5 + x);
                }
            }
        }
    }

    // Mean-residual coupling.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.08 * dev;
    } else {
        score += 0.05 * (-dev) * (item_size as f64 / c);
    }

    // New-bin candidate handling with adaptive escape valves.
    let is_new_bin = bin_residual == bin_capacity;
    let fresh_left = c - item_size as f64;
    if is_new_bin {
        let mut penalty = 35.0;
        if next_item_size > 0 && r > next_item_size as f64 + 30.0 {
            penalty -= 12.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 10.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 15.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        penalty -= 8.0 * x;
        if fitting_bins_count > 0 && open_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n * 0.5 {
                penalty -= 6.0 + 6.0 * (1.0 - r / n);
            }
        }
        if item_size as f64 >= 0.7 * c && x < 0.4 {
            penalty -= 6.0;
        }
        if fitting_bins_count > 0 && post_residual > 0 && post_residual < 12 && open_bins_count > 1 {
            penalty -= 9.0;
        }
        if fitting_bins_count > 0 {
            let slack = fresh_left;
            if slack < 0.15 * c && open_bins_count > 2 {
                penalty -= 5.0 + 3.0 * x;
            }
        }
        if open_bins_count > 4 && mean_residual > 0.5 * c {
            penalty -= 4.0;
        }
        if next_item_size > 0 && open_bins_count > 0 {
            let n = next_item_size as f64;
            if r < n && n > 0.6 * c {
                penalty -= 7.0 + 5.0 * x;
            }
        }
        if x > 0.8 && item_size as f64 > 0.5 * c {
            penalty -= 5.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 1 && r > 0.6 * c && mean_residual < 0.35 * c {
            penalty -= 8.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 {
            let slack = fresh_left;
            if slack < mean_residual * 0.5 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        penalty += 10.0 * x * x;
        if x > 0.95 && open_bins_count > 1 {
            penalty -= 4.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 {
            let n = next_item_size as f64;
            if r < n && r < 0.2 * c {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        // Compare best achievable post-residual on an open bin against the
        // fresh-bin leftover; prefer the new bin when it strands less waste.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n && fresh_left >= n {
                penalty -= 6.0 + 6.0 * x;
            }
            if fresh_left > 0.6 * c && r < 0.1 * c && open_bins_count > 0 {
                penalty -= 5.0;
            }
            // Fresh-bin residual exactly fits the next item: zero-waste follow-up.
            if fresh_left >= n && fresh_left % n.max(1.0) < 1.0 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        // Large item early on — dedicated bin beats carving a partial one.
        if item_size as f64 > 0.55 * c && x < 0.25 && open_bins_count > 2 {
            penalty -= 5.0;
        }
        // Heavy fragmentation: opening fresh and consolidating is preferable.
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 3.0 + 3.0 * x;
        }
        // When the only fitting bins would leave residual smaller than half
        // the next item, opening fresh is cheap — avoids stranding.
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        // Late stream with large mean residual — squeeze existing bins harder.
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        // Waste-budget coupling — when total stranded residual is small
        // relative to the stream, fresh bins get pricier; when fragmentation
        // is high, they get cheaper. Drives compaction.
        if open_bins_count > 0 {
            let frag = mean_residual / c;
            let sprawl = open_bins_count as f64;
            if frag < 0.3 {
                penalty += (0.3 - frag) * 20.0 * (1.0 - x);
            } else if frag > 0.55 && sprawl > 3.0 {
                penalty -= (frag - 0.55) * 18.0 * (0.5 + x);
            }
        }
        // Near-perfect fresh fill — if the item almost exactly fills a new
        // bin, opening it is nearly free.
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Fresh-bin leftover divisibility sweep — reward when the fresh
        // leftover can absorb several copies of the next item exactly.
        if next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 6.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // Waste-budget lookahead: penalize opening a fresh bin when the fresh
        // leftover is itself an unfillable sliver; reward a snug two-item horizon.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if fresh_left > 0.0 && fresh_left < n {
                penalty += 8.0 + 6.0 * x;
            }
            if fresh_left >= n && fresh_left < n * 1.5 {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        // Mid-stream sprawl control.
        if x > 0.3 && x < 0.85 && open_bins_count > 6 && mean_residual > 0.3 * c {
