            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 6.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // MUTATION: fresh-bin vs open-bin waste comparison — if every fitting
        // open bin would strand more dead space than the fresh leftover, the
        // new bin becomes cheaper; if the fresh leftover is worse, pricier.
        if fitting_bins_count > 0 && post_residual > 0 {
            let fresh_left2 = c - item_size as f64;
            let open_dead = r.min(fresh_left2);
            if fresh_left2 < open_dead * 0.5 {
                penalty -= 5.0 + 5.0 * x;
            } else if fresh_left2 > open_dead * 2.0 && open_dead < 0.15 * c {
                penalty += 4.0 * (1.0 - x);
            }
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — reward filling the fullest available bin,
    // scaled by open-bin sprawl.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio pressure — penalize bins whose residual is an awkward
    // fraction of capacity, strongest mid-stream where choices still matter.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term — if the post-residual can hold the next
    // item with a leftover that is itself reusable, reward it; scaled by
    // competing bins.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // MUTATION: waste-quantization refinement — post-residuals that are exact
    // multiples of 25 or 50 pair well with common mid-size items; reward
    // slightly stronger late in the stream where compaction matters most.
    if !is_new_bin && post_residual > 0 {
        if post_residual % 50 == 0 {
            score -= 2.5 + 1.5 * x;
        } else if post_residual % 25 == 0 {
            score -= 1.0 + 1.0 * x;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = r / c;
    let placed = (bin_residual - post_residual) as f64;
    let mut score = post_residual as f64;

    // Base: superlinear tightness bonus on the space actually consumed.
    score -= 0.35 * placed;
    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (8.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect fit: reward strongly, escalating late.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals in (0, 10) are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 20.0 * x;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Half-class reward: post_residual can host large future items.
    if post_residual >= bin_capacity / 2 {
        score -= 20.0;
    }

    // Nice-chunk residuals are reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // ---- 2-step lookahead coupling with chaining ----
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n == r {
            score -= 400.0 + 50.0 * x;
        } else if n <= r {
            let post2 = post_residual - next_item_size;
            let snug = 1.0 - post2 as f64 / c;
            score -= 15.0 + post2 as f64 * 0.3 + 10.0 * snug;
            if post2 % 10 == 0 {
                score -= 5.0;
            }
            if r >= 2.0 * n {
                score -= 6.0;
                let chain = (r / n).floor().min(4.0);
                if post_residual % next_item_size == 0 {
                    score -= 4.0 + 4.0 * x * chain;
                }
            }
            let after = post2 as f64;
            if after > 0.0 && after < n * 0.5 {
                score += 5.0 + 3.0 * x;
            } else if after >= n {
                score -= 3.0;
            }
        } else {
            let waste = (n - r) / n;
            score += 20.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 10.0;
            }
            if r > 0.0 {
                let gap = n - r;
                if gap < 8.0 {
                    score += 4.0 * (1.0 - gap / 8.0) * (0.5 + x);
                }
            }
        }
    }

    // Last-chance bin: strongly prefer using it (unless it's the new-bin candidate).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 + 20.0 * x;
    }

    // Relative-to-mean shaping.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.10 * dev;
    } else {
        score += 0.06 * (-dev) * (item_size as f64 / c);
    }

    // Prefer filling bins below mean residual (compress variance).
    score -= (mean_residual - r) * 0.5;

    // Late-stream consolidation.
    score -= 8.0 * x * (1.0 - p);

    // Mid-stream consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Residual fragmentation guard.
    if post_residual > 0 && post_residual < bin_capacity / 5 && x < 0.85 {
        score += 5.0;
    }

    // Residual-absorbability: post-residual can hold next item with reusable leftover.
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // Awkward-fraction dead-space pressure mid-stream.
    if !is_new_bin && post_residual > 0 {
        let dp = p.min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // New-bin candidate handling with adaptive escape valves.
    if is_new_bin {
        let mut penalty = 40.0 - progress_like(x) * 20.0;
        let fresh_left = c - item_size as f64;
        if next_item_size > 0 && r > next_item_size as f64 + 30.0 {
            penalty -= 15.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 12.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 15.0;
        }
        if next_item_size > 0 && item_size == next_item_size {
            penalty += 10.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 100.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        penalty -= 8.0 * x;
        // Fresh-bin leftover divisibility: reward when leftover absorbs copies of next item.
        if next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 6.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 {
                    penalty -= 2.0 + 2.0 * x;
                }
                if r > 0.0 && r < n && open_bins_count > 0 {
                    penalty -= 6.0 + 6.0 * x;
                }
            }
        }
        // Near-perfect fresh fill.
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Waste-budget coupling: fragmented sprawl makes fresh bins cheaper.
        if open_bins_count > 0 {
            let frag = mean_residual / c;
            if frag < 0.3 {
                penalty += (0.3 - frag) * 20.0 * (1.0 - x);
            } else if frag > 0.55 && open_bins_count > 3 {
                penalty -= (frag - 0.55) * 18.0 * (0.5 + x);
            }
        }
        // Only fitting bin would strand less than half the next item.
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        // Late stream with large mean residual — squeeze existing bins harder.
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        penalty += 10.0 * x * x;
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
        // Global compaction pressure toward the fullest bin.
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    score
}

