        }
        // MUTATION: fresh-bin leftover should be judged against the whole
        // stream's residual profile — if the fresh leftover is far larger
        // than the mean residual of open bins, the new bin will hoard space
        // and starve compaction; penalize that imbalance.
        if open_bins_count > 0 {
            let imbalance = (fresh_left - mean_residual).max(0.0) / c;
            if imbalance > 0.2 {
                penalty += imbalance * 8.0 * (0.5 + x);
            }
        }
