    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        if r < n {
            let waste = r;
            score += (waste / n) * (2.0 + 3.0 * x) * (1.0 + 0.15 * (fitting_bins_count.min(6) as f64));
