            // residual that itself exactly divides the following item, the bin
            // closes with zero waste over two placements.
            if after > 0.0 && next_item_size > 0 && (after as u32) % next_item_size.max(1) == 0 && after >= n {
                score -= 3.0 + 3.0 * x;
