        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — reward filling the fullest available bin,
    // scaled by open-bin sprawl.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio pressure — penalize bins whose residual is an awkward
    // fraction of capacity, strongest mid-stream where choices still matter.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term — if the post-residual can hold the next
    // item with a leftover that is itself reusable (>= half the next item or
    // exactly zero), reward it; scaled by how many bins compete.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // MUTATION: post-residual reusability sweep — a residual that can host the
    // next item multiple times with minimal final waste is a compaction
    // guarantee; reward it proportionally to usable copies, strongest late.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        if r >= n {
            let copies = (r / n).floor();
            let leftover = r - copies * n;
            if leftover < n * 0.2 {
                score -= (1.5 + 2.0 * x) * copies.min(4.0) * (1.0 - leftover / (n * 0.2));
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 4) are worthless; penalize hard.
    if post_residual < 4 {
        score -= 60.0; // near-perfect fit, excellent
    } else if post_residual < 10 {
        // dead space: unusable for almost any item
        score += 120.0;
    } else if post_residual < 20 {
        score += 40.0;
    }

    // Reward bins whose residual matches the next item's size (lookahead fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // this bin becomes dead after placement if next item can't use it
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 10.0 + pressure * 2.0;
        // But if no existing bin fits well (large dead space elsewhere),
        // mean_residual high suggests fragmentation -> make new bin cheaper.
        if mean_residual > 30.0 {
            score -= 20.0;
        }
    } else {
        // Existing bin: small bonus for being below-average fragmented.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

