    // item with a leftover that is itself reusable (>= half the next item or
    // exactly zero), reward it; scaled by how many bins compete.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // MUTATION: multi-item absorbability sweep — reward residuals that can
    // chain several next-item copies with near-zero final waste, weighted by
    // stream progress so late-stream exact packing dominates.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        if r >= n {
            let copies = (r / n).floor();
            let leftover = r - copies * n;
            if leftover == 0.0 && copies >= 2.0 {
                score -= 3.0 + 2.0 * copies.min(4.0) * (0.5 + x);
            } else if leftover < n * 0.2 && copies >= 1.0 {
                score -= 1.0 + 1.5 * x;
            }
        }
    }

    score
}

