    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (mod-based dead-space classes) ---
    let post = post_residual;
    // Class 0: post == 0 -> perfect fit, heavily reward.
    if post == 0 {
        score -= 1000.0;
    } else {
        // Small usable residuals are good; tiny unusable slivers (<10) are dead.
        if post < 10 {
            score += 60.0; // dead space penalty
        }
        // Harmonic class: post / 25 buckets (0..=4)
        let class = (post / 25) as f64;
        score -= 12.0 * class; // prefer bins leaving larger, more reusable chunks
        // Modulo coupling: residuals divisible by 10 align with typical item sizes
        if post % 10 == 0 {
            score -= 8.0;
        } else if post % 10 >= 5 {
            score += 3.0; // odd fractions less reusable
        }
    }

    // --- Lookahead coupling with next_item_size ---
    if next_item_size > 0 {
        if post == next_item_size {
            score -= 250.0; // exact fit for the next item: chain placement
        } else if post > next_item_size {
            // residual can host next item; reward proportion of tightness
            let slack = (post - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize slightly if gap is small
            let gap = (next_item_size - post) as f64;
            score += gap.min(40.0) * 0.5;
        }
        // Modulo harmony: post and next item share a divisor class of 10
        if post >= next_item_size && (post - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else {
        // Last item: pure tightness
        score -= 50.0;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0; // strongly prefer using the only fitting bin
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0); // competition: prefer tightest anyway
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: baseline cost of opening a bin.
        score = bin_capacity as f64 - item_size as f64 + 40.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing else fits, must open
        } else if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            // item nearly fills a bin: opening is attractive
            score -= 25.0;
        }
        // As stream matures, mildly discourage bin proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // --- Mean residual context: avoid worsening a bad fleet average ---
    if mean_residual > 0.0 && bin_residual != bin_capacity {
        let dev = (post as f64 - mean_residual).abs();
        score += 0.15 * dev; // keep residuals homogeneous, packable
    }

    // --- Progress-based tightness bonus ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - post as f64 / bin_capacity as f64);

    score
}

