    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — reward filling the fullest available bin,
    // scaled by open-bin sprawl. MUTATION: strengthened and coupled to how
    // many bins compete for the item, amplifying best-fit pressure.
    if !is_new_bin {
        let sprawl = (open_bins_count as f64).min(12.0).ln().max(0.0);
        score -= (0.04 + 0.02 * x) * (bin_residual as f64 / c) * sprawl;
        if fitting_bins_count > 2 {
            score -= 1.0 + 0.5 * (fitting_bins_count.min(6) as f64);
        }
    }

    // Dead-space ratio pressure.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // MUTATION: competition-aware snugness — when several bins fit the item,
    // extra-reward the one whose post-residual is closest to the next item
    // size, sharpening residual reuse across the pool.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && fitting_bins_count > 1 {
        let n = next_item_size as f64;
        let gap = (r - n).abs();
        if gap < 0.15 * c {
            score -= 3.0 * (1.0 - gap / (0.15 * c)) * (0.5 + x);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Smooth non-linear waste penalty: residual waste becomes more costly as stream progresses
    let waste_curve = (pr / cap) * (pr / cap) * (0.5 + progress);
    score += 40.0 * waste_curve;

    // Perfect-fit reward with polynomial coupling to progress
    let fit_frac = 1.0 - (pr / cap);
    score -= 30.0 * fit_frac * fit_frac * (1.0 + 2.0 * progress);

    // Penalize tiny unusable residuals (dead space) smoothly
    let dead = if pr > 0.0 { (1.0 - pr / 10.0).max(0.0) } else { 0.0 };
    score += 15.0 * dead * dead;

    // Lookahead: reward residual that can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 8.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins when mean residual is high
    score += 0.5 * (open_bins_count as f64) * (mean_residual / cap - 0.5).abs();

    // New-bin candidate: penalize slightly unless current bin would waste heavily
    if bin_residual == bin_capacity {
        let waste_here = pr / cap;
        score -= 20.0 * (1.0 - waste_here) * (1.0 - waste_here);
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
