            penalty += 4.0 + 4.0 * x;
        }
        // Waste-budget coupling — when total stranded residual is small
        // relative to the stream, fresh bins get pricier; when fragmentation
        // is high, they get cheaper. Drives compaction.
        if open_bins_count > 0 {
            let frag = mean_residual / c;
            let sprawl = open_bins_count as f64;
            if frag < 0.3 {
                penalty += (0.3 - frag) * 20.0 * (1.0 - x);
            } else if frag > 0.55 && sprawl > 3.0 {
                penalty -= (frag - 0.55) * 18.0 * (0.5 + x);
            }
        }
        // Near-perfect fresh fill — if the item almost exactly fills a new
        // bin, opening it is nearly free.
        let fresh_left = c - item_size as f64;
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Fresh-bin leftover divisibility sweep — reward when the fresh
        // leftover can absorb several copies of the next item exactly.
        if next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 6.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // Fresh-bin leftover that strands dead space below the next item.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if fresh_left > 0.0 && fresh_left < n {
                penalty += 8.0 + 6.0 * x;
            }
            if fresh_left >= n && fresh_left < n * 1.5 {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — reward filling the fullest available bin,
    // scaled by open-bin sprawl.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio pressure — penalize bins whose residual is an awkward
    // fraction of capacity, strongest mid-stream where choices still matter.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term — if the post-residual can hold the next
    // item with a leftover that is itself reusable (>= half the next item or
    // exactly zero), reward it; scaled by how many bins compete.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // Live-residual yield — reward placements whose post-residual can still
    // hold the next item with room for a second copy, scaled by progress.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= 2.0 * n {
            score -= (1.5 + 2.5 * x) * (r / c);
        } else if r >= n {
            score -= 0.5 + 1.0 * x;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream processed (dynamic time horizon).
    let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 1. Tightness reward: strongly favor bins where the item fills a large
    //    share of the residual. Use a quadratic coupling so near-perfect fits
    //    are disproportionately rewarded.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 2.5 * fill_ratio * fill_ratio * (bin_residual as f64);

    // 2. Dead-space penalty: residual left behind that is too small to hold
    //    ANY plausible item (min size 1, but practically tiny slivers < next
    //    item are suspect). Penalize residuals that cannot accommodate the
    //    lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // 3. Perfect closure bonus: if this placement exactly empties the bin,
    //    reward it heavily (no wasted capacity at all).
    if post_residual == 0 {
        score -= 8.0;
    }

    // 4. Last-chance dynamics: if this is the ONLY open bin that can fit the
    //    item, using it avoids opening a new bin — reward it, more so late in
    //    the stream when consolidation matters.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0 + 3.0 * t;
    }

    // 5. New-bin candidate handling (bin_residual == bin_capacity):
    //    a fresh empty bin has maximal residual, so the tightness reward
    //    naturally vanishes. Give it a calibrated baseline penalty so it only
    //    wins when all existing fits are poor, scaled by how much residual
    //    wealth is already lying around in open bins.
    if bin_residual == bin_capacity {
        let residual_wealth = mean_residual * open_bins_count as f64;
        // If plenty of usable residual exists across open bins, discourage
        // opening yet another bin; decay this pressure over time slightly.
        score += 6.0 + 0.05 * residual_wealth - 2.0 * t;
        // But if the item is large relative to typical leftover space, a new
        // bin is a reasonable escape hatch — soften the penalty.
        if mean_residual > 0.0 && (item_size as f64) > mean_residual + 10.0 {
            score -= 3.0;
        }
    }

    // 6. Global-state coupling: when many bins are open and mean residual is
    //    high, prefer placements that drain the largest residuals (best-fit
    //    across the fleet) to keep the fleet compact.
    if bin_residual < bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev; // smaller-than-average residual => lower score => favored
    }

    // 7. Early-stream exploration: early on, be slightly more willing to
    //    spread items (keeps residual flexibility for unknown future sizes);
    //    late in the stream, tighten aggressively.
    score -= (1.0 - t) * 1.5 * (post_residual as f64 / bin_capacity as f64);
    score += t * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // 8. Lookahead pairing bonus: if placing here leaves exactly enough room
    //    for the next item, that's a beautiful chain — reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
