        } else {
            let frac = r / n;
            score += 2.0 * frac * (1.0 + x);
        }
    }

    // MUTATION (gen 20): awkward-fraction pressure — penalize bins whose
    // post-residual sits at an awkward half-step fraction of capacity,
    // strongest mid-stream where choices still matter; combined with an
    // absorbability term rewarding leftovers that can host the next item
    // with a reusable remainder, tying fine residual fitting to lookahead.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space), scaled by stream progress
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * 100.0;
    score += norm_pr * (1.0 - progress) * 40.0;

    // Perfect fit reward (smooth, non-linear)
    let perfect = 1.0 - (pr / cap).powf(3.0);
    score -= perfect * 60.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 * (1.0 - norm_pr);
    }

    // Lookahead coupling: reward leaving space the next item can use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack_fit = 1.0 - ((pr - nxt) / cap);
            score -= slack_fit * 25.0 * (1.0 - progress);
        } else {
            // post residual too small for next item: penalize proportionally
            score += (nxt - pr) / cap * 30.0;
        }
    }

    // New-bin candidate: penalize slightly unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        let pressure = (open_bins_count as f64).ln() + 1.0;
        score += 55.0 - fragmentation * 45.0 * pressure * (0.5 + progress);
    } else {
        // Prefer bins tighter than the mean residual (smooth coupling)
        score += (bin_residual as f64 - mean_residual) / cap * 15.0;
    }

    // Mild preference for compacting many bins early
    score += (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * norm_pr * 20.0;

    score
}

