    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (8.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect fill: strong reward, escalating late.
    if post_residual == 0 {
        score -= 55.0 + 10.0 * x;
    }

    // Dead-space penalty (quadratic), plus near-dead slivers.
    let dead = (p * (1.0 - p * 4.0)).max(0.0);
    score += dead * (2.0 + 3.0 * x) + 2.5 * dead * dead * (1.0 + x);
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + 4.0 * x;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Fragmentation guard.
    if post_residual > 0 && post_residual < bin_capacity / 5 && x < 0.85 {
        score += 4.0;
    }

    // Half-class residuals stay flexible.
    if post_residual >= bin_capacity / 2 {
        score -= 12.0 * (1.0 - x);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if x > 0.5 {
