    let mut score = post_residual as f64;

    // Best-fit core: tighter fits preferred (non-linear squash).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: reward bins whose post-residual can host the next item (chain fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack_after_next / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that no plausible next item can use.
        score += 3.0 * (post_residual as f64 / 100.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful while good fits exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize new bins, harder when many open bins exist or mean residual is high.
            score += 20.0 + 2.0 * open_bins_count as f64 + 0.05 * mean_residual;
        } else {
            score -= 5.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for filling bins that are already partially loaded.
    if bin_residual < bin_capacity {
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 4.0 * fill;
    }

    // Discourage leaving residuals below the smallest plausible item when avoidable.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

