        if item_size as f64 > 0.55 * c && x < 0.25 && open_bins_count > 2 {
            penalty -= 5.0;
        }
        // Heavy fragmentation: opening fresh and consolidating is preferable.
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 3.0 + 3.0 * x;
        }
        // When the only fitting bins would leave residual smaller than half
        // the next item, opening fresh is cheap — avoids stranding.
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        // Late stream with large mean residual — squeeze existing bins harder.
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        // Waste-budget coupling.
        if open_bins_count > 0 {
            let frag = mean_residual / c;
            let sprawl = open_bins_count as f64;
            if frag < 0.3 {
                penalty += (0.3 - frag) * 20.0 * (1.0 - x);
            } else if frag > 0.55 && sprawl > 3.0 {
                penalty -= (frag - 0.55) * 18.0 * (0.5 + x);
            }
        }
        // Near-perfect fresh fill.
        let fresh_left = c - item_size as f64;
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Fresh-bin leftover divisibility sweep.
        if next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 6.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // MUTATION: dead-space parity coupling — when the fresh-bin leftover
        // complements the mean residual toward a full bin, opening fresh is
        // cheaper; this nudges consolidation of scattered residuals.
        if open_bins_count > 1 && mean_residual > 0.0 {
            if (fresh_left - mean_residual).abs() < 0.1 * c {
                penalty -= 3.0 + 3.0 * x;
            }
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio pressure.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // MUTATION: waste-floor pressure — mid/late stream, penalize bins whose
    // post-residual is stranded (below next item and below half-mean), pushing
    // selection toward bins whose leftover stays usable.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 && x > 0.35 {
        let n = next_item_size as f64;
        if r < n && r < mean_residual * 0.6 {
            score += (2.0 + 4.0 * x) * (1.0 - r / n.max(1.0));
        }
    }

    // MUTATION: pair-completion lookahead — reward bins whose post-residual
    // can exactly host the next item plus a small top-up, tightening the
    // dead-space ratio toward zero.
    if !is_new_bin && post_residual > 0 && next_item_size > 1 {
        let n = next_item_size as f64;
        if r > n {
            let tail = r - n;
            if tail > 0.0 && tail <= 8.0 {
                score -= 2.5 * (1.0 - tail / 8.0) * (1.0 + x);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with a mild non-linear reward
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate leftover space; late in the stream, penalize it harder.
    let progress_weight = 0.4 + 2.2 * progress * progress * (1.0 - 0.5 * progress);
    score += progress_weight * pr;

    // Penalize waste relative to the mean residual of open bins:
    // leaving more than average slack is undesirable dead space.
    score += 0.35 * (pr - mean_residual).abs() * (1.0 + progress);

    // Lookahead: reward bins whose post_residual can host the next item,
    // with a smooth non-linear bonus scaled by how much slack remains.
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let slack_after_next = (pr - next_item_size as f64).max(0.0) / cap;
        score -= fits_next * (6.0 + 14.0 * slack_after_next * (1.0 - slack_after_next) * 4.0);
        // Penalize if this placement wastes space the next item needed
        let shortfall = (next_item_size as f64 - pr).max(0.0);
        score += 0.25 * shortfall * (1.0 + 2.0 * progress);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, scaled smoothly with progress.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 20.0 * progress;
    }

    // Scarcity pressure: with many open bins, favor consolidation into existing bins.
    let scarcity = (open_bins_count as f64).ln().max(0.0);
    score += 0.15 * scarcity * norm_pr * (1.0 + progress);

    // New-bin candidate: make an empty bin unattractive unless the item is large
    // and no existing bin fits well (smoothly modulated by item size).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score += 8.0 + 30.0 * (1.0 - item_frac) * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
