                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // MUTATION: fresh-bin dead-space budget — scale the base penalty by
        // how well the fresh leftover can be reused relative to the stranded
        // waste the best open bin would produce. If the fresh leftover is
        // large but the open-bin residual is tiny, make the new bin cheaper
        // (its leftover is more valuable than the sliver being saved).
        if open_bins_count > 0 && fitting_bins_count > 0 {
            let frag = mean_residual / c;
            let fresh_usable = fresh_left / c;
            // Fresh leftover worth keeping when it exceeds the average
            // stranded residual by a margin — it can serve future items.
