            } else if waste_frac > 0.0 {
                score += 0.5 * waste_frac;
            }
        }
    }

    // MUTATION: mean-residual dead-space target — prefer bins whose
    // post-residual stays close to the fleet mean residual, keeping the
    // residual distribution tight so future items find uniform fits; the
    // tightness reward grows with stream progress where uniformity pays most.
    if !is_new_bin && post_residual > 0 && mean_residual > 0.0 {
        let spread = ((r - mean_residual) / c).abs();
        score += 1.2 * spread * (0.4 + x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance: gaps that no plausible item can fill are toxic ---
    // Items are 1..100; a residual gap below ~10 is nearly unusable "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // hard penalty for creating an unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: strongly reward closing a bin exactly
    }

    // Dead-space severity: penalize gaps that are too small relative to typical item mass
    let gap = post_residual as f64;
    if gap > 0.0 {
        // penalize gaps in the "awkward zone" 1..35 quadratically
        if gap < 35.0 {
            score += (35.0 - gap) * (35.0 - gap) * 0.02;
        }
        // reward large, reusable residuals mildly
        score -= gap * 0.05;
    }

    // --- Tight-fit reward: item fills most of the bin ---
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 15.0 * (fill_ratio - 0.8) / 0.2;
    }

    // --- Open-bin pressure: discourage spreading across many bins ---
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: if open bins are already loose, prefer filling them
    score -= (mean_residual - gap) * 0.3;

    // --- Last-chance bin: if this is the ONLY fitting bin, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- Lookahead: if next item fits perfectly in post_residual, big reward ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let nx = next_item_size as f64;
            let pr = post_residual as f64;
            // reward proportionally to how well next item uses the leftover
            score -= 10.0 * (nx / pr);
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early (plenty of stream left to fill it),
        // but costly late in the stream or when many bins are already open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 12.0 + 25.0 * progress + open_bins_count as f64 * 2.0;
        // However, if no open bin fits well (large dead space would result elsewhere),
        // the dead-space penalties above already push toward the new bin.
        // Small discount when item is large (big items are hard to place later):
        score -= item_size as f64 * 0.1;
    }

    score
}

