            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // MUTATION: competition-aware snugness — when multiple bins fit the item,
    // extra-reward the one whose post-residual is the tightest usable band;
    // when only one bin fits, mildly discount it to keep it attractive over
    // opening fresh (synergy with the last-chance bonus).
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        if r >= n {
            if fitting_bins_count >= 3 {
                score -= 1.0 + 1.5 * (r / c);
            } else if fitting_bins_count == 1 {
                score -= 1.5;
            }
        }
    }

    // MUTATION: residual-void shaping — residuals that can never host any
    // plausible future item (well below typical sizes) are pure waste; push
    // them away from being created, more so mid/late stream.
    if !is_new_bin && post_residual > 0 {
        let void_zone = 3.0;
        if r <= void_zone {
            score += 2.0 + 2.0 * x;
        }
    }

    score
}

