    // Residual-absorbability term — if the post-residual can hold
    // the next item with a leftover that is itself reusable (>= half the next
    // item or exactly zero), reward it; scaled by how many bins compete.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // MUTATION: competition-aware tightness — when several bins fit the
    // item, extra reward for the bin whose post-residual exactly matches a
    // small multiple of the next item (predictable future fill), scaled by
    // competition count to break ties toward the most reusable bin.
    if !is_new_bin && post_residual > 0 && next_item_size > 1 && fitting_bins_count > 1 {
        let n = next_item_size as f64;
        let k = (r / n).floor();
        if k >= 1.0 {
            let leftover = r - k * n;
            if leftover < 3.0 {
                score -= 1.0 + 0.8 * k.min(3.0) + 1.5 * x;
            }
        }
    }

    score
}

