    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    let mut score = pr;

    // Non-linear polynomial coupling with stream progress
    let poly = x * x * (1.0 - x) + x * (1.0 - x) * (1.0 - x);
    score += 8.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    score -= 6.0 * (1.0 - x).powi(3) * (0.5 + progress);

    // Penalize residuals that cannot fit the lookahead item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 3.0 * (1.0 - (pr / (next_item_size as f64).max(1.0)).min(1.0));
    } else if next_item_size > 0 {
        score -= 2.0 * (1.0 - (next_item_size as f64 / pr).min(1.0));
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // Slight preference to fill bins below mean residual (balance consolidation)
    score += 1.5 * (pr - mean_residual) / cap;

    // New-bin candidate: mildly penalize late in the stream, reward early
    if bin_residual == bin_capacity {
        score += 2.0 * progress - 1.0 * (1.0 - progress);
    }

    score
}

