    if !is_new_bin && next_item_size > 1 && post_residual >= next_item_size {
        let n = next_item_size as f64;
        let copies = (r / n).floor();
        let leftover = r - copies * n;
        if leftover == 0.0 {
            score -= (1.0 + 1.5 * x) * copies.min(6.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead-space "bands" based on
    // capacity fractions and modulo arithmetic.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual is a multiple of 10 (nice harmonic slot) -> reward.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    // Class B: post_residual in [1,9] is near-dead space -> penalize strongly.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Class C: post_residual in (10,20) awkward band -> mild penalty.
    if post_residual > 10 && post_residual < 20 {
        score += 4.0;
    }
    // Class D: post_residual divisible by 5 but not 10 -> small reward.
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }

    // Harmonic coupling with next item: if next item exactly fills post_residual,
    // this is a perfect chain -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits, check leftover class
            let nxt_left = post_residual - next_item_size;
            if nxt_left % 10 == 0 {
                score -= 12.0;
            }
            if nxt_left < 10 {
                score += 6.0;
            }
        } else {
            // next item won't fit here -> slight penalty proportional to overshoot
            score += ((next_item_size - post_residual) as f64) * 0.2;
        }
    }

    // Integer division threshold: post_residual >= half capacity is still useful.
    if post_residual * 2 >= bin_capacity {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * open_bins_count as f64;
        // But if no open bin fits well (post_residual of others would be tiny),
        // opening fresh is fine — handled by other bins' penalties.
    }

    // Progress-based drift: later in stream, prefer tighter fits (smaller residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += pr * (0.05 + 0.1 * progress) - pr * 0.1;

    // Mean residual coupling: if this bin's residual is far below mean, it's a
    // nearly-full bin — reward closing it out.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.3;
    }

    score
}

