        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — reward filling the fullest available bin.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio pressure — penalize awkward residual fractions,
    // strongest mid-stream.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // MUTATION (gen 24): residual-absorbability — reward placements whose
    // post-residual can hold the next item and leave a reusable remainder.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // MUTATION (gen 24): live two-step horizon — reward placements whose
    // post-residual holds the next item twice, scaled by stream progress.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= 2.0 * n {
            score -= (1.5 + 2.5 * x) * (r / c);
        } else if r >= n {
            score -= 0.5 + 1.0 * x;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual >= 10 {
        // gap too small for typical next items but not zero waste
        score += 12.0 + 0.5 * post_residual as f64;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead space only matters if the next item cannot use it
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.8 * (next_item_size - post_residual) as f64;
    }
    // Reward residual that fits the lookahead item (usable gap)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before it closes
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 20.0);
    score += 0.6 * pressure * (0.5 + progress);

    // Prefer bins with residual close to item size (tight fit preference)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 || mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    score
}

