    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — reward filling the fullest available bin,
    // scaled by open-bin sprawl.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio pressure — penalize bins whose residual is an awkward
    // fraction of capacity, strongest mid-stream where choices still matter.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term — if the post-residual can hold the next
    // item with a leftover that is itself reusable (>= half the next item or
    // exactly zero), reward it; scaled by how many bins compete.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // MUTATION: waste-differential compaction — price each candidate bin by
    // the stranded residual it would create relative to the best possible
    // placement; bins whose post-residual is closer to a multiple of the
    // next item's size are structurally cheaper to keep alive.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        let copies = (r / n).floor();
        let rem = r - copies * n;
        if rem > 0.0 && copies >= 1.0 {
            // Partially absorbable leftover: penalize in proportion to how
            // much of the next item it strands, softened late-stream.
            score += 1.2 * (rem / n) * (0.4 + 0.6 * x);
        }
        // Bins whose residual equals a small multiple of common sizes (5/10)
        // pair cleanly with typical items — small structural discount.
        if rem == 0.0 && r <= 0.5 * c {
            score -= 1.0 + 1.0 * x;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: reward tight fits (small post_residual), with a convex (quadratic)
    // coupling so tiny residuals are disproportionately favored.
    let mut score = post + 0.9 * (post / cap) * post;

    // Smooth stream-progress coupling: as the stream advances, tighten the
    // preference for compact residuals (cubic-in-progress multiplier).
    let tightener = 1.0 + 1.5 * progress * progress + 0.8 * progress;
    score *= tightener;

    // Penalize residuals that are "dead space" relative to the mean residual:
    // a bin whose post-residual deviates far above the open-bin mean wastes capacity.
    let dev = post - mean_residual;
    score += 0.35 * dev * dev / cap;

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly;
    // if the next item cannot use the post-residual at all, penalize smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            // perfect-chain bonus decays with the size of the leftover gap
            score -= 3.0 * (1.0 - gap / cap) * (1.0 + progress);
        } else {
            // unusable residual for the lookahead item
            score += 0.6 * (-gap) / cap * (1.0 + 2.0 * progress);
        }
    }

    // Scarcity pressure: if this is the only fitting bin, strongly favor using it
    // (avoid opening a new bin), scaled smoothly by how tight the fit is.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0 * (1.0 - post / cap);
    } else if fitting_bins_count > 1 {
        // many alternatives: mild penalty so the best-fitting bin wins via post term
        score += 0.15 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // relative to capacity (poor fit everywhere else) or late in the stream.
    if bin_residual == bin_capacity {
        let size_ratio = item / cap;
        let open_penalty = 2.5 + 6.0 * size_ratio * (1.0 - progress);
        score += open_penalty;
        // smooth discount: large items justify new bins more as stream progresses
        score -= 3.0 * size_ratio * progress;
    }

    // Mild reward for using a bin that is already heavily filled (smooth saturation).
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= 0.5 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = r / c;
    let placed = (bin_residual - post_residual) as f64;
    let mut score = post_residual as f64;

    // Base: superlinear small-post-residual preference, progress-scaled.
    score += p * p * (1.0 + 2.0 * x) + 0.35 * p;

    // Tightness bonus on what was just placed.
    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (8.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect fill: strong reward, escalating late when bins are scarce.
    if post_residual == 0 {
        score -= 55.0 + 10.0 * x;
    }

    // Early stream: keep bins flexible.
    score += (1.0 - x) * p * (1.0 - p) * 3.0;

    // Dead-space penalty (quadratic in usable-space loss).
    let dead = (p * (1.0 - p * 4.0)).max(0.0);
    score += dead * (2.0 + 3.0 * x) + 2.5 * dead * dead * (1.0 + x);
    if post_residual > 0 {
        let min_live = (next_item_size.max(1) as f64).min(20.0);
        if r > 0.0 && r < min_live {
            score += 3.0 * (1.0 - r / min_live) * (1.0 + x);
        }
    }

