        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 10.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 15.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        penalty -= 8.0 * x;
        if fitting_bins_count > 0 && open_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n * 0.5 {
                penalty -= 6.0 + 6.0 * (1.0 - r / n);
            }
        }
        if item_size as f64 >= 0.7 * c && x < 0.4 {
            penalty -= 6.0;
        }
        if fitting_bins_count > 0 && post_residual > 0 && post_residual < 12 && open_bins_count > 1 {
            penalty -= 9.0;
        }
        if fitting_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < 0.15 * c && open_bins_count > 2 {
                penalty -= 5.0 + 3.0 * x;
            }
        }
        if open_bins_count > 4 && mean_residual > 0.5 * c {
            penalty -= 4.0;
        }
        if next_item_size > 0 && open_bins_count > 0 {
            let n = next_item_size as f64;
            if r < n && n > 0.6 * c {
                penalty -= 7.0 + 5.0 * x;
            }
        }
        if x > 0.8 && item_size as f64 > 0.5 * c {
            penalty -= 5.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 1 && r > 0.6 * c && mean_residual < 0.35 * c {
            penalty -= 8.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < mean_residual * 0.5 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        penalty += 10.0 * x * x;
        if x > 0.95 && open_bins_count > 1 {
            penalty -= 4.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 {
            let n = next_item_size as f64;
            if r < n && r < 0.2 * c {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        // Compare best achievable post-residual on an open bin against the
        // fresh-bin leftover; prefer the new bin when it strands less waste.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            let fresh_left = c - item_size as f64;
            if r > 0.0 && r < n && fresh_left >= n {
                penalty -= 6.0 + 6.0 * x;
            }
            if fresh_left > 0.6 * c && r < 0.1 * c && open_bins_count > 0 {
                penalty -= 5.0;
            }
            if fresh_left >= n && fresh_left % n.max(1.0) < 1.0 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        if item_size as f64 > 0.55 * c && x < 0.25 && open_bins_count > 2 {
            penalty -= 5.0;
        }
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 3.0 + 3.0 * x;
        }
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        // Waste-budget coupling.
        if open_bins_count > 0 {
            let frag = mean_residual / c;
            let sprawl = open_bins_count as f64;
            if frag < 0.3 {
                penalty += (0.3 - frag) * 20.0 * (1.0 - x);
            } else if frag > 0.55 && sprawl > 3.0 {
                penalty -= (frag - 0.55) * 18.0 * (0.5 + x);
            }
        }
        // Near-perfect fresh fill.
        let fresh_left = c - item_size as f64;
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Fresh-bin leftover divisibility sweep.
        if next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 6.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // MUTATION: when the fresh leftover would strand less waste than the
        // best open-bin post-residual across all fitting bins, open fresh.
        if fitting_bins_count > 1 && next_item_size > 0 {
            let fresh_left = c - item_size as f64;
            if fresh_left < r && r < next_item_size as f64 {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio pressure.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // MUTATION: exact-fill sweep — reward bins where the item leaves a
    // residual that is an exact multiple of a small common size, tightening
    // compaction without opening new bins.
    if !is_new_bin && post_residual > 0 {
        if post_residual % 20 == 0 {
            score -= 3.0 + 2.0 * x;
        } else if post_residual % 25 == 0 {
            score -= 2.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10 classes.
    let class = (post_residual * 10 / bin_capacity) as f64;
    score += class * 0.8;

    // Exact-fill reward: post_residual zero is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward small post residuals (waste minimization, non-linear).
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Penalize "dead zone" residuals that few item sizes can use (11..19 band).
    if post_residual >= 11 && post_residual <= 19 {
        score += 18.0;
    }

    // Modulo arithmetic: residuals congruent to common item sizes are reusable.
    let reusable = (post_residual % 10 == 0) || (post_residual % 5 == 0 && post_residual <= 50);
    if reusable {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let nxt_class = (next_item_size * 10 / bin_capacity) as f64;
            score -= 4.0 + nxt_class * 0.5;
        } else {
            // Next item cannot use this residual: penalize wasting space.
            score += 8.0;
            // Harmonic mismatch penalty via integer division thresholds.
            if post_residual / 20 != next_item_size / 20 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make it attractive only when open bins are fragmented.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer reusing bins with good fits.
        score += 40.0;
        // If many bins fit the item, opening new bin is wasteful.
        if fitting_bins_count >= 2 {
            score += 25.0;
        }
        // If no bin offers a tight fit, opening a fresh bin is reasonable.
        if fitting_bins_count >= 1 && post_residual_dummy(bin_residual, item_size) > 25 {
            score -= 20.0;
        }
        // Late in stream, avoid opening bins unless necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer filling bins that are already low relative to the mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.15;

    score
}

// Helper inlined logic (no pseudo-random state): residual quality measure.
fn post_residual_dummy(residual: u32, item: u32) -> u32 {
    residual.saturating_sub(item)
}

