    // scaled by sprawl and progress, to drive compaction like the best-known.
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin {
        score -= 0.10 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
        score -= 4.0 * x * (bin_residual as f64 / c);
