        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n {
            let dead_frac = (n - r) / n;
            score += dead_frac * dead_frac * (3.0 + 4.0 * x);
        }
    }

    // Live-residual yield: reward placements whose post-residual can hold
    // the next item with room for a second copy.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= 2.0 * n {
            score -= (1.5 + 2.5 * x) * (r / c);
        } else if r >= n {
            score -= 0.5 + 1.0 * x;
        }
    }

    // MUTATION (gen 28): residual-absorbability refinement — if the
    // post-residual can hold the next item leaving either zero leftover or a
    // reusable remainder (>= half the next item), reward it, scaled by how
    // many bins compete (tighter competition = stronger reward).
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            let competition = 1.0 / (fitting_bins_count.max(1) as f64);
            if after == 0.0 {
                score -= (2.0 + 2.0 * x) * (1.0 + competition);
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x) * (1.0 + competition);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;

    // Cubic interaction: waste penalized more as stream progresses
    score += prn * prn * prn * (progress * 60.0) * bin_capacity as f64;

    // Quadratic smooth term rewarding tight fits (low post_residual), stronger early
    score -= (1.0 - prn) * (1.0 - prn) * (1.0 - progress) * 20.0;

    // Smoothly growing penalty for opening bins late in the stream
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (progress * progress * 30.0 + 5.0);

    // Last-chance bin: smooth sigmoid-like reward to use it
    if fitting_bins_count == 1 && new_bin == 0.0 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward leaving room for the next item (smooth polynomial)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let slack = pr - ns;
        if slack >= 0.0 {
            let sn = slack / bin_capacity as f64;
            score -= (1.0 - sn) * (1.0 - sn) * 10.0 * (1.0 - progress);
        } else {
            let deficit = (-slack) / bin_capacity as f64;
            score += deficit * deficit * 12.0;
        }
    }

    // Coupling with mean residual: penalize bins far from mean (smooth quadratic)
    let dev = pr - mean_residual;
    score += (dev / bin_capacity as f64) * (dev / bin_capacity as f64) * 8.0;

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln() * (prn * 2.0);

    score
}

