        // Near-perfect fresh fill — if the item almost exactly fills a new
        // bin, opening it is nearly free.
        let fresh_left = c - item_size as f64;
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Fresh-bin leftover divisibility sweep — reward when the fresh
        // leftover can absorb several copies of the next item exactly.
        if next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 6.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // Fresh-bin leftover that itself strands a sliver below the next
        // item is dead space too — price it in.
        if fitting_bins_count > 0 && next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 {
            penalty += 8.0 + 6.0 * x;
        }
        // Mid-stream sprawl control — many open bins with ample residual
        // mean fresh bins should cost more.
        if x > 0.3 && x < 0.85 && open_bins_count > 6 && mean_residual > 0.3 * c {
            penalty += 3.0 + 3.0 * (open_bins_count as f64 - 6.0).min(6.0);
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — reward filling the fullest available bin,
    // scaled by open-bin sprawl.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio pressure — penalize bins whose residual is an awkward
    // fraction of capacity, strongest mid-stream where choices still matter.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term — if the post-residual can hold the next
    // item with a leftover that is itself reusable (>= half the next item
    // or exactly zero), reward it; scaled by how many bins compete.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // Live-residual yield — reward placements whose post-residual can still
    // hold the next item with room for a second copy (a viable two-step
    // horizon), scaled by stream progress so late placements favor maximal
    // compaction.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= 2.0 * n {
            score -= (1.5 + 2.5 * x) * (r / c);
        } else if r >= n {
            score -= 0.5 + 1.0 * x;
        }
    }

    // Dead-space ratio shaping — scale the effective cost of a placement by
    // the fraction of the bin that becomes permanently unusable (residual
    // below the next item), pushing toward placements that keep residual live.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n {
            let dead_frac = (n - r) / n;
            score += dead_frac * dead_frac * (3.0 + 4.0 * x);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space classes: residuals 1..=9 are almost unusable for items >=10.
    if post_residual >= 1 && post_residual <= 9 {
        score += 25.0;
    }
    // Harmonic class: post_residual in (capacity/2, capacity) is a "half-class" hole.
    let half = bin_capacity / 2;
    if post_residual > half && post_residual < bin_capacity {
        score -= 8.0; // roomy leftover, still useful
    }

    // Lookahead coupling: reward if next item fits into the post residual exactly or closely.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0;
            if slack == 0 {
                score -= 20.0; // perfect chain fit
            } else if slack <= 9 {
                score += 10.0; // chain creates dead space
            }
        } else {
            // next item cannot use this leftover: mild penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline; open a new bin only when
    // the best existing fit leaves a large, awkward residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, softened as stream progresses (fewer chances left).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 35.0 + 20.0 * (1.0 - progress);
        // If item exactly fills a fresh bin, opening is great.
        if item_size == bin_capacity {
            score -= 60.0;
        }
        // If many bins already fit the item, discourage opening another.
        score += fitting_bins_count as f64 * 4.0;
    }

    // Tight-fit bonus: item occupies most of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 && bin_residual != bin_capacity {
        score -= 6.0 * fill_ratio;
    }

    // Slight preference for bins with below-average residual (consolidate waste).
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

