            score += dead_frac * dead_frac * (3.0 + 4.0 * x);
        }
    }

    // Live-space preservation among several fitting bins.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
        let n = next_item_size as f64;
        if r < n && r < 15.0 {
            score += 4.0 + 3.0 * x;
        }
    }

    // Fine-grained residual discrimination among multiple fitting bins.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
        let n = next_item_size as f64;
        if r >= n {
            let snug = 1.0 - (r - n) / n;
            score -= 2.5 * snug * (0.5 + x);
        } else {
            let frac = r / n;
            score += 2.0 * frac * (1.0 + x);
        }
    }

    // Second-level dead-space probe.
    if !is_new_bin && next_item_size > 0 && r >= next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after = r - n;
        if after > 0.0 && after < 15.0 {
            score += (1.0 + x) * (1.0 - after / 15.0) * 2.0;
        } else if after >= 15.0 && after < 30.0 {
