            score -= 3.0 + 3.0 * x;
        } else if after2 > 0.0 && after2 < 4.0 {
            score -= 1.5 + 1.5 * x;
        } else if after2 >= n && after2 < n + 4.0 {
            score -= 1.0 * (1.0 - x);
        } else if after2 > 0.0 && after2 < n * 0.4 {
            score += 1.5 * (0.5 + x);
        }
    }

    // Cross-bin tightness gradient.
    if !is_new_bin && fitting_bins_count > 1 {
        let tight = 1.0 - (r / c).min(1.0);
