    // MUTATION (gen 35): residual-efficiency gradient among fitting bins —
    // compare each candidate's post-residual to the cohort mean; bins that
    // strand notably less than the average get a nonlinear reward, bins
    // stranding more get a penalty. Sharpens close-fit selection, attacking
    // the diagnosed dead-space weakness.
    if !is_new_bin && fitting_bins_count > 2 && post_residual > 0 {
        let cohort = mean_residual.max(1.0);
        let rel = (r - cohort) / c;
        if rel < 0.0 {
            score -= (rel * -60.0).min(3.0) * (0.5 + x);
        } else {
            score += (rel * 40.0).min(2.0) * (0.5 + x);
        }
    }

    // MUTATION (gen 35): awkward-residual band pressure — residuals in the
    // 20..40 dead zone (too small for mid items, too big to ignore) get a
    // mild nonlinear penalty scaled by progress, pushing selection toward
    // either exact fits or much larger leftovers.
    if !is_new_bin && post_residual > 20 && post_residual < 40 {
        let depth = 1.0 - (post_residual as f64 - 20.0) / 20.0;
        score += 1.5 * depth * (0.4 + x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: strong reward for tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable fragments (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 * (1.0 - (next_item_size as f64 / post_residual as f64));
        } else {
            // Penalize leaving residual too small for the known next item.
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when good open bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * (1.0 - progress);
        // If mean residual is large, opening a new bin is wasteful.
        score += mean_residual * 0.15;
        // But if item is large relative to capacity, a fresh bin may be fine.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Slight preference for bins with residuals close to the item (global state coupling).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Time horizon: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Reward using bins with larger residuals when many bins are open (reduce sprawl).
    score -= 0.02 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

