    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if x > 0.5 {
            score -= 10.0 * x;
        }
    }

    // Lookahead with snugness, chaining, and two-step chain depth.
    if next_item_size > 0 {
        let n = next_item_size as f64;
