        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — reward filling the fullest available bin,
    // scaled by open-bin sprawl.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio pressure.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // Waste-stranding sweep.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        if r < n {
            score += 2.5 * (r / n) * (0.5 + x);
        } else if r < 2.0 * n {
            let after = r - n;
            if after > 0.0 && after < n {
                if after < 5.0 {
                    score += 2.0 * (1.0 - x);
                } else if after >= 5.0 && after < 15.0 {
                    score -= 1.0;
                }
            }
        }
    }

    // Cross-bin tightness gradient.
    if !is_new_bin && fitting_bins_count > 1 {
        let tight = 1.0 - (r / c).min(1.0);
        score -= 1.8 * tight * tight * (1.0 - (2.0 * x - 1.0).abs());
    }

    // Second-level dead-space probe.
    if !is_new_bin && next_item_size > 0 && r >= next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after = r - n;
        if after > 0.0 && after < 15.0 {
            score += (1.0 + x) * (1.0 - after / 15.0) * 2.0;
        } else if after >= 15.0 && after < 30.0 {
            score -= 0.8 * (1.0 - x);
        }
        if after > 0.0 && (after % 10.0) == 0.0 {
            score -= 1.2 + 1.2 * x;
        }
    }

    // Third-level chain probe.
    if !is_new_bin && next_item_size > 0 && r >= 2.0 * next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after2 = r - 2.0 * n;
        if after2 == 0.0 {
            score -= 3.0 + 3.0 * x;
        } else if after2 > 0.0 && after2 < 4.0 {
            score -= 1.5 + 1.5 * x;
        } else if after2 >= n && after2 < n + 4.0 {
            score -= 1.0 * (1.0 - x);
        } else if after2 > 0.0 && after2 < n * 0.4 {
            score += 1.5 * (0.5 + x);
        }
    }

    // Residual-efficiency gradient among fitting bins — compare each
    // candidate's post-residual to the cohort mean; bins stranding less
    // than average get a nonlinear reward, bins stranding more a penalty.
    if !is_new_bin && fitting_bins_count > 2 && post_residual > 0 {
        let cohort = mean_residual.max(1.0);
        let rel = (r - cohort) / c;
        if rel < 0.0 {
            score -= (rel * -60.0).min(3.0) * (0.5 + x);
        } else {
            score += (rel * 40.0).min(2.0) * (0.5 + x);
        }
    }

    // MUTATION (gen 36): two-step dead-space probe with absorbability
    // weighting — for fitting bins whose post-residual exceeds the next
    // item, evaluate how much of the remaining space a second future item
    // (approximated by the current item size) could still absorb. Leftovers
    // that cannot host a second item of any plausible size are penalized
    // progressively; leftovers that chain cleanly are rewarded. Extends the
    // residual-efficiency gradient one level deeper to shave the remaining
    // dead-space waste.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
        let n = next_item_size.max(1) as f64;
        let after = r - n;
        if after > 0.0 {
            let cur = item_size.max(1) as f64;
            let second_copies = (after / cur).floor();
            let strand2 = after - second_copies * cur;
            if second_copies == 0.0 {
                // Post-residual cannot host the current item again: pure
                // dead space unless the next item's own size covers it.
                if after < n * 0.5 {
                    score += 2.0 * (1.0 - after / (n * 0.5)) * (0.5 + x);
                } else {
                    score += 1.0 + 1.5 * x;
                }
            } else if strand2 < 3.0 {
                // Near-perfect two-step chain.
                score -= 2.5 + 2.5 * x;
            } else if strand2 < 0.15 * c {
                // Moderate strand: mild penalty scaled by strand size.
                score += 1.5 * (strand2 / (0.15 * c)) * (0.5 + x);
            }
            // Reward when the strand is a multiple of the next item size,
            // keeping the bin perpetually reusable.
            if strand2 >= n && (strand2 % n) < 1.0 {
                score -= 1.5 + 1.5 * x;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = r / c;
    let placed = (bin_residual - post_residual) as f64;

    // Base: superlinear small-post-residual preference, progress-scaled.
    let mut score = p * p * (1.0 + 2.0 * x) + 0.35 * p;

    // Tightness bonus on what was just placed.
    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (8.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect fill: strong reward, escalating late when bins are scarce.
    if post_residual == 0 {
        score -= 55.0 + 10.0 * x;
    } else if post_residual <= 5 {
        score -= 12.0 + 8.0 * x;
    }

    // Early stream: keep bins flexible.
    score += (1.0 - x) * p * (1.0 - p) * 3.0;

    // Dead-space penalty (quadratic in usable-space loss).
    let dead = (p * (1.0 - p * 4.0)).max(0.0);
    score += dead * (2.0 + 3.0 * x) + 2.5 * dead * dead * (1.0 + x);
    if post_residual > 0 {
        let min_live = (next_item_size.max(1) as f64).min(20.0);
        if r > 0.0 && r < min_live {
            score += 3.0 * (1.0 - r / min_live) * (1.0 + x);
        }
    }

    // Tiny unrescuable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + 4.0 * x;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Fragmentation guard.
    if post_residual > 0 && post_residual < bin_capacity / 5 && x < 0.85 {
        score += 4.0;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if x > 0.5 {
            score -= 10.0 * x;
        }
    }

    // Lookahead with snugness, chaining, and two-step chain depth.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r == n {
            score -= 40.0 + 5.0 * x;
        } else if n <= r {
            let snug = 1.0 - (r - n) / c;
            score -= 10.0 * snug;
            if r >= 2.0 * n {
                score -= 4.0;
            }
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                score += 5.0;
            } else if after >= n {
                score -= 3.0;
            }
            let chain_count = (r / n).floor();
            if chain_count >= 2.0 {
                score -= 2.0 * chain_count.min(4.0);
            }
            if after > 0.0 && after < n * 0.5 && after < 25.0 {
                score += 4.0 + 3.0 * x;
            }
            if after > 0.0 && after < n * 0.1 {
                score += 3.0 + 3.0 * x;
            }
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 2 {
                score -= 5.0 + 4.0 * x;
            }
            if after > 0.0 && (after * 2.0) >= n && after < n {
                score -= 2.0 + 2.0 * x;
            }
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 3 {
                score -= 3.0 + 3.0 * x;
            }
        } else {
            let waste = (n - r) / n;
            score += 15.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 8.0;
            }
            if r > 0.0 && r < 20.0 {
                score += 3.0 * (1.0 - r / 20.0);
            }
            if r > 0.0 {
                score += 5.0 * waste * (1.0 - x);
            }
            if r > 0.0 {
                let gap = n - r;
                if gap < 8.0 {
                    score += 4.0 * (1.0 - gap / 8.0) * (0.5 + x);
                }
            }
        }
    }

    // Mean-residual coupling.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.08 * dev;
    } else {
        score += 0.05 * (-dev) * (item_size as f64 / c);
    }

    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut penalty = 35.0;
        if next_item_size > 0 && r > next_item_size as f64 + 30.0 {
            penalty -= 12.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 10.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 15.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        penalty -= 8.0 * x;
        if fitting_bins_count > 0 && open_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n * 0.5 {
                penalty -= 6.0 + 6.0 * (1.0 - r / n);
            }
        }
        if item_size as f64 >= 0.7 * c && x < 0.4 {
            penalty -= 6.0;
        }
        if fitting_bins_count > 0 && post_residual > 0 && post_residual < 12 && open_bins_count > 1 {
            penalty -= 9.0;
        }
        if fitting_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < 0.15 * c && open_bins_count > 2 {
                penalty -= 5.0 + 3.0 * x;
            }
        }
        if open_bins_count > 4 && mean_residual > 0.5 * c {
            penalty -= 4.0;
        }
        if next_item_size > 0 && open_bins_count > 0 {
            let n = next_item_size as f64;
            if r < n && n > 0.6 * c {
                penalty -= 7.0 + 5.0 * x;
            }
        }
        if x > 0.8 && item_size as f64 > 0.5 * c {
            penalty -= 5.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 1 && r > 0.6 * c && mean_residual < 0.35 * c {
            penalty -= 8.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < mean_residual * 0.5 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        penalty += 10.0 * x * x;
        if x > 0.95 && open_bins_count > 1 {
            penalty -= 4.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 {
            let n = next_item_size as f64;
            if r < n && r < 0.2 * c {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            let fresh_left = c - item_size as f64;
            if r > 0.0 && r < n && fresh_left >= n {
                penalty -= 6.0 + 6.0 * x;
            }
            if fresh_left > 0.6 * c && r < 0.1 * c && open_bins_count > 0 {
                penalty -= 5.0;
            }
            if fresh_left >= n && fresh_left % n.max(1.0) < 1.0 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        if item_size as f64 > 0.55 * c && x < 0.25 && open_bins_count > 2 {
            penalty -= 5.0;
        }
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 3.0 + 3.0 * x;
        }
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            let fresh_left = c - item_size as f64;
            if fresh_left > 0.0 && fresh_left < n {
                penalty += 8.0 + 6.0 * x;
            }
            if fresh_left >= n && fresh_left < n * 1.5 {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        if x > 0.3 && x < 0.85 && open_bins_count > 6 && mean_residual > 0.3 * c {
            penalty += 3.0 + 3.0 * (open_bins_count as f64 - 6.0).min(6.0);
        }
        if fitting_bins_count > 0 && next_item_size > 1 {
            let n = next_item_size as f64;
            let fresh_left = c - item_size as f64;
            if fresh_left >= n && (fresh_left as u32) % next_item_size == 0 {
                penalty -= 3.0 + 3.0 * x;
            }
        }
        // Near-perfect fresh fill — opening is nearly free when the item
        // almost exactly fills a new bin.
        let fresh_left = c - item_size as f64;
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Fresh-bin leftover divisibility sweep — reward when the fresh
        // leftover can absorb several copies of the next item exactly.
        if next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 6.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // Scale fresh-bin cost by how well the best open-bin fit uses space.
        if fitting_bins_count > 0 {
            let best_use = 1.0 - (r / c).min(1.0);
            penalty += 14.0 * best_use * (0.4 + x);
        }
        // Open-bin fit quality sweep — sliver-stranding open bins make fresh
        // cheap; roomy open bins make fresh pricier.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_absorbs = fresh_left >= n;
            if r > 0.0 && r < n {
                let fresh_strand = if fresh_absorbs {
                    let copies = (fresh_left / n).floor();
                    let l = fresh_left - copies * n;
                    if l > 0.0 { l } else { 0.0 }
                } else { fresh_left };
                if fresh_strand + 2.0 < r {
                    penalty -= 8.0 + 6.0 * x;
                } else if r < fresh_strand {
                    penalty += 4.0 + 4.0 * x;
                }
            }
        }
        // Fresh-bin dead-space surcharge for odd slivers after next-item fit.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let after_f = fresh_left - n;
                if after_f > 0.0 && after_f < 20.0 && after_f < n {
                    penalty += (1.0 - after_f / 20.0) * (3.0 + 3.0 * x);
                } else if after_f == 0.0 {
                    penalty -= 4.0 + 3.0 * x;
                }
            }
        }
        // MUTATION (gen 36): waste-budget coupling — when mean residual is
        // low (tight packing), make fresh bins pricier early; when sprawl
        // and mean residual are both high, discount fresh bins.
        if open_bins_count > 0 {
            let frag = mean_residual / c;
            let sprawl = open_bins_count as f64;
            if frag < 0.3 {
                penalty += (0.3 - frag) * 20.0 * (1.0 - x);
            } else if frag > 0.55 && sprawl > 3.0 {
                penalty -= (frag - 0.55) * 18.0 * (0.5 + x);
            }
        }
        // MUTATION (gen 36): late-stream fresh surge pricing on wasteful opens.
        if x > 0.7 {
            let fresh_waste = fresh_left / c;
            if fresh_waste > 0.5 {
                penalty += (fresh_waste - 0.5) * 18.0 * (x - 0.7) / 0.3;
            }
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio shaping.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n {
            let dead_frac = (n - r) / n;
            score += dead_frac * dead_frac * (3.0 + 4.0 * x);
        }
    }

    // Live-residual yield — reward two-copy horizons.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= 2.0 * n {
            score -= (1.5 + 2.5 * x) * (r / c);
        } else if r >= n {
            score -= 0.5 + 1.0 * x;
        }
    }

    // MUTATION (gen 36): waste-stranding sweep — bins whose post-residual
    // falls just below the next item size strand dead space; bins leaving
    // a second usable chunk are preferred. Attacks the diagnosed dead-space
    // weakness with a fine-grained residual/lookahead coupling.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        if r < n {
            score += 2.5 * (r / n) * (0.5 + x);
        } else if r < 2.0 * n {
            let after = r - n;
            if after > 0.0 && after < n {
                if after < 5.0 {
                    score += 2.0 * (1.0 - x);
                } else if after < 15.0 {
                    score -= 1.0;
                }
            }
        }
    }

    // MUTATION (gen 36): residual-efficiency gradient among fitting bins —
    // bins stranding less than the cohort average get a nonlinear reward;
    // bins stranding more get a penalty. Sharpens selection among close fits.
    if !is_new_bin && fitting_bins_count > 2 && post_residual > 0 {
        let cohort = mean_residual.max(1.0);
        let rel = (r - cohort) / c;
        if rel < 0.0 {
            score -= (rel * -60.0).min(3.0) * (0.5 + x);
        } else {
            score += (rel * 40.0).min(2.0) * (0.5 + x);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = r / c;
    let placed = (bin_residual - post_residual) as f64;

    // Base: superlinear small-post-residual preference, progress-scaled.
    let mut score = p * p * (1.0 + 2.0 * x) + 0.35 * p;

    // Tightness bonus on what was just placed.
    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (8.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect fill: strong reward, escalating late when bins are scarce.
    if post_residual == 0 {
        score -= 55.0 + 10.0 * x;
    } else if post_residual <= 5 {
        score -= 12.0 + 8.0 * x;
    }

    // Early stream: keep bins flexible.
    score += (1.0 - x) * p * (1.0 - p) * 3.0;

    // Dead-space penalty (quadratic in usable-space loss).
    let dead = (p * (1.0 - p * 4.0)).max(0.0);
    score += dead * (2.0 + 3.0 * x) + 2.5 * dead * dead * (1.0 + x);
    if post_residual > 0 {
        let min_live = (next_item_size.max(1) as f64).min(20.0);
        if r > 0.0 && r < min_live {
            score += 3.0 * (1.0 - r / min_live) * (1.0 + x);
        }
    }

    // Tiny unrescuable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + 4.0 * x;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Fragmentation guard.
    if post_residual > 0 && post_residual < bin_capacity / 5 && x < 0.85 {
        score += 4.0;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if x > 0.5 {
            score -= 10.0 * x;
        }
    }

    // Lookahead with snugness, chaining, and two-step chain depth.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r == n {
            score -= 40.0 + 5.0 * x;
        } else if n <= r {
            let snug = 1.0 - (r - n) / c;
            score -= 10.0 * snug;
            if r >= 2.0 * n {
                score -= 4.0;
            }
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                score += 5.0;
            } else if after >= n {
                score -= 3.0;
            }
            let chain_count = (r / n).floor();
            if chain_count >= 2.0 {
                score -= 2.0 * chain_count.min(4.0);
            }
            if after > 0.0 && after < n * 0.5 && after < 25.0 {
                score += 4.0 + 3.0 * x;
            }
            if after > 0.0 && after < n * 0.1 {
                score += 3.0 + 3.0 * x;
            }
            // Exact divisibility chain — zero-waste fill guarantee.
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 2 {
                score -= 5.0 + 4.0 * x;
            }
            // Two-step chain viability.
            if after > 0.0 && (after * 2.0) >= n && after < n {
                score -= 2.0 + 2.0 * x;
            }
        } else {
            let waste = (n - r) / n;
            score += 15.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 8.0;
            }
            if r > 0.0 && r < 20.0 {
                score += 3.0 * (1.0 - r / 20.0);
            }
            if r > 0.0 {
                score += 5.0 * waste * (1.0 - x);
            }
            if r > 0.0 {
                let gap = n - r;
                if gap < 8.0 {
                    score += 4.0 * (1.0 - gap / 8.0) * (0.5 + x);
                }
            }
        }
    }

    // Mean-residual coupling.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.08 * dev;
    } else {
        score += 0.05 * (-dev) * (item_size as f64 / c);
    }

    // New-bin candidate handling with adaptive escape valves.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut penalty = 35.0;
        if next_item_size > 0 && r > next_item_size as f64 + 30.0 {
            penalty -= 12.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 10.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 15.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        penalty -= 8.0 * x;
        if fitting_bins_count > 0 && open_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n * 0.5 {
                penalty -= 6.0 + 6.0 * (1.0 - r / n);
            }
        }
        if item_size as f64 >= 0.7 * c && x < 0.4 {
            penalty -= 6.0;
        }
        if fitting_bins_count > 0 && post_residual > 0 && post_residual < 12 && open_bins_count > 1 {
            penalty -= 9.0;
        }
        if fitting_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < 0.15 * c && open_bins_count > 2 {
                penalty -= 5.0 + 3.0 * x;
            }
        }
        if open_bins_count > 4 && mean_residual > 0.5 * c {
            penalty -= 4.0;
        }
        if next_item_size > 0 && open_bins_count > 0 {
            let n = next_item_size as f64;
            if r < n && n > 0.6 * c {
                penalty -= 7.0 + 5.0 * x;
            }
        }
        if x > 0.8 && item_size as f64 > 0.5 * c {
            penalty -= 5.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 1 && r > 0.6 * c && mean_residual < 0.35 * c {
            penalty -= 8.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < mean_residual * 0.5 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        penalty += 10.0 * x * x;
        if x > 0.95 && open_bins_count > 1 {
            penalty -= 4.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 {
            let n = next_item_size as f64;
            if r < n && r < 0.2 * c {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        // Compare best achievable post-residual on an open bin against the
        // fresh-bin leftover; prefer the new bin when it strands less waste.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            let fresh_left = c - item_size as f64;
            if r > 0.0 && r < n && fresh_left >= n {
                penalty -= 6.0 + 6.0 * x;
            }
            if fresh_left > 0.6 * c && r < 0.1 * c && open_bins_count > 0 {
                penalty -= 5.0;
            }
            // Fresh-bin residual exactly fits the next item: zero-waste follow-up.
            if fresh_left >= n && fresh_left % n.max(1.0) < 1.0 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        // Large item early on — dedicated bin beats carving a partial one.
        if item_size as f64 > 0.55 * c && x < 0.25 && open_bins_count > 2 {
            penalty -= 5.0;
        }
        // Heavy fragmentation: opening fresh and consolidating is preferable.
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 3.0 + 3.0 * x;
        }
        // When the only fitting bins would leave residual smaller than half
        // the next item, opening fresh is cheap — avoids stranding.
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        // Late stream with large mean residual — squeeze existing bins harder.
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        // Waste-budget coupling — when total stranded residual is small
        // relative to the stream, fresh bins get pricier; when fragmentation
        // is high, they get cheaper. Drives compaction.
        if open_bins_count > 0 {
            let frag = mean_residual / c;
            let sprawl = open_bins_count as f64;
            if frag < 0.3 {
                penalty += (0.3 - frag) * 20.0 * (1.0 - x);
            } else if frag > 0.55 && sprawl > 3.0 {
                penalty -= (frag - 0.55) * 18.0 * (0.5 + x);
            }
        }
        // Near-perfect fresh fill — if the item almost exactly fills a new
        // bin, opening it is nearly free.
        let fresh_left = c - item_size as f64;
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Fresh-bin leftover divisibility sweep — reward when the fresh
        // leftover can absorb several copies of the next item exactly.
        if next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 6.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // Scale fresh-bin cost by how well the best open-bin fit would use
        // space — when open bins fit tightly, fresh bins cost more.
        if fitting_bins_count > 0 {
            let best_use = 1.0 - (r / c).min(1.0);
            penalty += 14.0 * best_use * (0.4 + x);
        }
        // Open-bin fit quality sweep — when the best open-bin post-residual
        // is a tiny unusable sliver, opening fresh becomes much cheaper;
        // when the open-bin leftover is large and reusable, fresh bins get
        // pricier. Directly attacks dead-space waste.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_leftover = c - item_size as f64;
            let fresh_absorbs = fresh_leftover >= n;
            if r > 0.0 && r < n {
                let fresh_strand = if fresh_absorbs {
                    let copies = (fresh_leftover / n).floor();
                    let l = fresh_leftover - copies * n;
                    if l > 0.0 { l } else { 0.0 }
                } else { fresh_leftover };
                if fresh_strand + 2.0 < r {
                    penalty -= 8.0 + 6.0 * x;
                } else if r < fresh_strand {
                    penalty += 4.0 + 4.0 * x;
                }
            }
        }
        // Dead-space budget sweep refinement — widen the trade window so
        // that open-bin residuals just above the next item size are also
        // compared against the fresh-bin strand.
        if fitting_bins_count > 0 && next_item_size > 0 && r >= next_item_size as f64 {
            let n = next_item_size.max(1) as f64;
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                let fresh_leftover = c - item_size as f64;
                let fresh_strand = if fresh_leftover >= n {
                    let copies = (fresh_leftover / n).floor();
                    let l = fresh_leftover - copies * n;
                    if l > 0.0 { l } else { 0.0 }
                } else { fresh_leftover };
                if fresh_strand + 4.0 < after {
                    penalty -= 5.0 + 4.0 * x;
                } else if after < fresh_strand {
                    penalty += 3.0 + 3.0 * x;
                }
            }
        }
        // Three-step fresh-bin viability probe.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_leftover = c - item_size as f64;
            if fresh_leftover < n && r >= 2.0 * n && (r % n) == 0.0 {
                penalty += 6.0 + 5.0 * x;
            }
            let fresh_copies = (fresh_leftover / n).floor();
            let open_copies = (r / n).floor();
            if fresh_copies > open_copies && fresh_copies >= 3.0 && r > 0.0 {
                penalty -= 3.0 + 3.0 * x;
            }
        }
        // Late-stream fresh-bin surge pricing.
        if x > 0.7 {
            let fresh_waste = fresh_left / c;
            if fresh_waste > 0.5 {
                penalty += (fresh_waste - 0.5) * 18.0 * (x - 0.7) / 0.3;
            }
        }
        // Fresh-bin dead-space surcharge — when the fresh leftover after
        // absorbing the next item is a small odd sliver that no typical item
        // (<= 20) can absorb, charge extra; when exactly reusable, discount.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let after_f = fresh_left - n;
                if after_f > 0.0 && after_f < 20.0 && after_f < n {
                    penalty += (1.0 - after_f / 20.0) * (3.0 + 3.0 * x);
                } else if after_f == 0.0 {
                    penalty -= 4.0 + 3.0 * x;
                }
            }
        }
        // MUTATION (gen 36): fresh-bin dead-space surcharge extended to the
        // multi-copy absorption case — compute the true stranded sliver
        // after maximal copies of the next item fit the fresh leftover and
        // price it nonlinearly; also discount fresh bins whose leftover
        // leaves an exactly-absorbable remainder for small common items.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let sliver = fresh_left - copies * n;
                if sliver > 0.0 && sliver < 20.0 {
                    penalty += (1.0 - sliver / 20.0) * (2.0 + 2.0 * x);
                } else if sliver == 0.0 && copies >= 2.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — reward filling the fullest available bin,
    // scaled by open-bin sprawl.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio pressure.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // Waste-stranding sweep.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        if r < n {
            score += 2.5 * (r / n) * (0.5 + x);
        } else if r < 2.0 * n {
            let after = r - n;
            if after > 0.0 && after < n {
                if after < 5.0 {
                    score += 2.0 * (1.0 - x);
                } else if after >= 5.0 && after < 15.0 {
                    score -= 1.0;
                }
            }
        }
    }

    // Cross-bin tightness gradient.
    if !is_new_bin && fitting_bins_count > 1 {
        let tight = 1.0 - (r / c).min(1.0);
        score -= 1.8 * tight * tight * (1.0 - (2.0 * x - 1.0).abs());
    }

    // Second-level dead-space probe.
    if !is_new_bin && next_item_size > 0 && r >= next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after = r - n;
        if after > 0.0 && after < 15.0 {
            score += (1.0 + x) * (1.0 - after / 15.0) * 2.0;
        } else if after >= 15.0 && after < 30.0 {
            score -= 0.8 * (1.0 - x);
        }
        if after > 0.0 && (after % 10.0) == 0.0 {
            score -= 1.2 + 1.2 * x;
        }
    }

    // Third-level chain probe.
    if !is_new_bin && next_item_size > 0 && r >= 2.0 * next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after2 = r - 2.0 * n;
        if after2 == 0.0 {
            score -= 3.0 + 3.0 * x;
        } else if after2 > 0.0 && after2 < 4.0 {
            score -= 1.5 + 1.5 * x;
        } else if after2 >= n && after2 < n + 4.0 {
            score -= 1.0 * (1.0 - x);
        } else if after2 > 0.0 && after2 < n * 0.4 {
            score += 1.5 * (0.5 + x);
        }
    }

    // Residual-efficiency gradient among fitting bins.
    if !is_new_bin && fitting_bins_count > 2 && post_residual > 0 {
        let cohort = mean_residual.max(1.0);
        let rel = (r - cohort) / c;
        if rel < 0.0 {
            score -= (rel * -60.0).min(3.0) * (0.5 + x);
        } else {
            score += (rel * 40.0).min(2.0) * (0.5 + x);
        }
    }

    // MUTATION (gen 36): fourth-level chain probe — when the residual can
    // absorb three copies of the next item, price the terminal sliver.
    // Exact three-fill (sliver 0) is heavily rewarded; a sliver below the
    // next item that no small item (<= 20) can absorb is penalized, while
    // a sliver that a small common item can still absorb gets a mild
    // reward. This extends the dead-space attack one chain level deeper,
    // directly targeting the diagnosed residual/dead-space weakness.
    if !is_new_bin && next_item_size > 0 && r >= 3.0 * next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after3 = r - 3.0 * n;
        if after3 == 0.0 {
            score -= 4.0 + 4.0 * x;
        } else if after3 > 0.0 && after3 < n {
            if after3 > 20.0 || after3 > n.min(20.0) {
                score += 1.5 + 1.5 * x;
            } else {
                score -= 1.0 + 1.0 * x;
            }
        } else if after3 >= n {
            score -= 1.2 * (1.0 - after3 / c);
        }
    }

    // MUTATION (gen 36): terminal-sliver absorbability sweep — for open-bin
    // residuals that strand a sliver under 20 after the next item, check
    // whether any plausible small item (2..=20) divides the sliver; if so,
    // the dead space is recoverable and gets a mild reward, otherwise it is
    // truly stranded and gets a sharper late-stream penalty.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 {
        let n = next_item_size.max(1) as f64;
        if r > n {
            let sliver = r - (r / n).floor() * n;
            if sliver > 0.0 && sliver < 20.0 {
                let mut absorbable = false;
                let s = sliver as u32;
                let mut k = 2;
                while k <= s {
                    if s % k == 0 {
                        absorbable = true;
                        break;
                    }
                    k += 1;
                }
                if absorbable {
                    score -= 0.8 + 0.8 * x;
                } else {
                    score += 1.2 + 1.5 * x;
                }
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = r / c;
    let placed = (bin_residual - post_residual) as f64;

    // Base: superlinear small-post-residual preference, progress-scaled.
    let mut score = p * p * (1.0 + 2.0 * x) + 0.35 * p;

    // Tightness bonus on what was just placed.
    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (8.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect fill: strong reward, escalating late when bins are scarce.
    if post_residual == 0 {
        score -= 55.0 + 10.0 * x;
    } else if post_residual <= 5 {
        score -= 12.0 + 8.0 * x;
    }

    // Early stream: keep bins flexible.
    score += (1.0 - x) * p * (1.0 - p) * 3.0;

    // Dead-space penalty (quadratic in usable-space loss).
    let dead = (p * (1.0 - p * 4.0)).max(0.0);
    score += dead * (2.0 + 3.0 * x) + 2.5 * dead * dead * (1.0 + x);
    if post_residual > 0 {
        let min_live = (next_item_size.max(1) as f64).min(20.0);
        if r > 0.0 && r < min_live {
            score += 3.0 * (1.0 - r / min_live) * (1.0 + x);
        }
    }

    // Tiny unrescuable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + 4.0 * x;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Fragmentation guard.
    if post_residual > 0 && post_residual < bin_capacity / 5 && x < 0.85 {
        score += 4.0;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if x > 0.5 {
            score -= 10.0 * x;
        }
    }

    // Lookahead with snugness, chaining, and two-step chain depth.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r == n {
            score -= 40.0 + 5.0 * x;
        } else if n <= r {
            let snug = 1.0 - (r - n) / c;
            score -= 10.0 * snug;
            if r >= 2.0 * n {
                score -= 4.0;
            }
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                score += 5.0;
            } else if after >= n {
                score -= 3.0;
            }
            let chain_count = (r / n).floor();
            if chain_count >= 2.0 {
                score -= 2.0 * chain_count.min(4.0);
            }
            if after > 0.0 && after < n * 0.5 && after < 25.0 {
                score += 4.0 + 3.0 * x;
            }
            if after > 0.0 && after < n * 0.1 {
                score += 3.0 + 3.0 * x;
            }
            // Exact divisibility chain — zero-waste fill guarantee.
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 2 {
                score -= 5.0 + 4.0 * x;
            }
            // Two-step chain viability.
            if after > 0.0 && (after * 2.0) >= n && after < n {
                score -= 2.0 + 2.0 * x;
            }
        } else {
            let waste = (n - r) / n;
            score += 15.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 8.0;
            }
            if r > 0.0 && r < 20.0 {
                score += 3.0 * (1.0 - r / 20.0);
            }
            if r > 0.0 {
                score += 5.0 * waste * (1.0 - x);
            }
            if r > 0.0 {
                let gap = n - r;
                if gap < 8.0 {
                    score += 4.0 * (1.0 - gap / 8.0) * (0.5 + x);
                }
            }
        }
    }

    // Mean-residual coupling.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.08 * dev;
    } else {
        score += 0.05 * (-dev) * (item_size as f64 / c);
    }

    // New-bin candidate handling with adaptive escape valves.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut penalty = 35.0;
        if next_item_size > 0 && r > next_item_size as f64 + 30.0 {
            penalty -= 12.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 10.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 15.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        penalty -= 8.0 * x;
        if fitting_bins_count > 0 && open_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n * 0.5 {
                penalty -= 6.0 + 6.0 * (1.0 - r / n);
            }
        }
        if item_size as f64 >= 0.7 * c && x < 0.4 {
            penalty -= 6.0;
        }
        if fitting_bins_count > 0 && post_residual > 0 && post_residual < 12 && open_bins_count > 1 {
            penalty -= 9.0;
        }
        if fitting_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < 0.15 * c && open_bins_count > 2 {
                penalty -= 5.0 + 3.0 * x;
            }
        }
        if open_bins_count > 4 && mean_residual > 0.5 * c {
            penalty -= 4.0;
        }
        if next_item_size > 0 && open_bins_count > 0 {
            let n = next_item_size as f64;
            if r < n && n > 0.6 * c {
                penalty -= 7.0 + 5.0 * x;
            }
        }
        if x > 0.8 && item_size as f64 > 0.5 * c {
            penalty -= 5.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 1 && r > 0.6 * c && mean_residual < 0.35 * c {
            penalty -= 8.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < mean_residual * 0.5 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        penalty += 10.0 * x * x;
        if x > 0.95 && open_bins_count > 1 {
            penalty -= 4.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 {
            let n = next_item_size as f64;
            if r < n && r < 0.2 * c {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        // Compare best achievable post-residual on an open bin against the
        // fresh-bin leftover; prefer the new bin when it strands less waste.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            let fresh_left = c - item_size as f64;
            if r > 0.0 && r < n && fresh_left >= n {
                penalty -= 6.0 + 6.0 * x;
            }
            if fresh_left > 0.6 * c && r < 0.1 * c && open_bins_count > 0 {
                penalty -= 5.0;
            }
            // Fresh-bin residual exactly fits the next item: zero-waste follow-up.
            if fresh_left >= n && fresh_left % n.max(1.0) < 1.0 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        // Large item early on — dedicated bin beats carving a partial one.
        if item_size as f64 > 0.55 * c && x < 0.25 && open_bins_count > 2 {
            penalty -= 5.0;
        }
        // Heavy fragmentation: opening fresh and consolidating is preferable.
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 3.0 + 3.0 * x;
        }
        // When the only fitting bins would leave residual smaller than half
        // the next item, opening fresh is cheap — avoids stranding.
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        // Late stream with large mean residual — squeeze existing bins harder.
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        // Waste-budget coupling — when total stranded residual is small
        // relative to the stream, fresh bins get pricier; when fragmentation
        // is high, they get cheaper. Drives compaction.
        if open_bins_count > 0 {
            let frag = mean_residual / c;
            let sprawl = open_bins_count as f64;
            if frag < 0.3 {
                penalty += (0.3 - frag) * 20.0 * (1.0 - x);
            } else if frag > 0.55 && sprawl > 3.0 {
                penalty -= (frag - 0.55) * 18.0 * (0.5 + x);
            }
        }
        // Near-perfect fresh fill — if the item almost exactly fills a new
        // bin, opening it is nearly free.
        let fresh_left = c - item_size as f64;
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Fresh-bin leftover divisibility sweep — reward when the fresh
        // leftover can absorb several copies of the next item exactly.
        if next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 6.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // Scale fresh-bin cost by how well the best open-bin fit would use
        // space — when open bins fit tightly, fresh bins cost more.
        if fitting_bins_count > 0 {
            let best_use = 1.0 - (r / c).min(1.0);
            penalty += 14.0 * best_use * (0.4 + x);
        }
        // Open-bin fit quality sweep — when the best open-bin post-residual
        // is a tiny unusable sliver, opening fresh becomes much cheaper;
        // when the open-bin leftover is large and reusable, fresh bins get
        // pricier. Directly attacks dead-space waste.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_leftover = c - item_size as f64;
            let fresh_absorbs = fresh_leftover >= n;
            if r > 0.0 && r < n {
                let fresh_strand = if fresh_absorbs {
                    let copies = (fresh_leftover / n).floor();
                    let l = fresh_leftover - copies * n;
                    if l > 0.0 { l } else { 0.0 }
                } else { fresh_leftover };
                if fresh_strand + 2.0 < r {
                    penalty -= 8.0 + 6.0 * x;
                } else if r < fresh_strand {
                    penalty += 4.0 + 4.0 * x;
                }
            }
        }
        // Dead-space budget sweep refinement — widen the trade window so
        // that open-bin residuals just above the next item size are also
        // compared against the fresh-bin strand.
        if fitting_bins_count > 0 && next_item_size > 0 && r >= next_item_size as f64 {
            let n = next_item_size.max(1) as f64;
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                let fresh_leftover = c - item_size as f64;
                let fresh_strand = if fresh_leftover >= n {
                    let copies = (fresh_leftover / n).floor();
                    let l = fresh_leftover - copies * n;
                    if l > 0.0 { l } else { 0.0 }
                } else { fresh_leftover };
                if fresh_strand + 4.0 < after {
                    penalty -= 5.0 + 4.0 * x;
                } else if after < fresh_strand {
                    penalty += 3.0 + 3.0 * x;
                }
            }
        }
        // Three-step fresh-bin viability probe.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_leftover = c - item_size as f64;
            if fresh_leftover < n && r >= 2.0 * n && (r % n) == 0.0 {
                penalty += 6.0 + 5.0 * x;
            }
            let fresh_copies = (fresh_leftover / n).floor();
            let open_copies = (r / n).floor();
            if fresh_copies > open_copies && fresh_copies >= 3.0 && r > 0.0 {
                penalty -= 3.0 + 3.0 * x;
            }
        }
        // Late-stream fresh-bin surge pricing.
        if x > 0.7 {
            let fresh_waste = fresh_left / c;
            if fresh_waste > 0.5 {
                penalty += (fresh_waste - 0.5) * 18.0 * (x - 0.7) / 0.3;
            }
        }
        // Fresh-bin dead-space surcharge — when the fresh leftover after
        // absorbing the next item is a small odd sliver that no typical item
        // (<= 20) can absorb, charge extra; when the fresh leftover is
        // exactly reusable, discount further.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let after_f = fresh_left - n;
                if after_f > 0.0 && after_f < 20.0 && after_f < n {
                    penalty += (1.0 - after_f / 20.0) * (3.0 + 3.0 * x);
                } else if after_f == 0.0 {
                    penalty -= 4.0 + 3.0 * x;
                }
            }
        }
        // MUTATION (gen 37): fresh-bin long-run absorption probe — estimate
        // how many future items the fresh leftover can hold at the mean
        // item scale implied by mean_residual. When the fresh bin promises
        // multi-item absorption that the current open-bin leftover cannot
        // match, discount it; when the open bin already holds more copies,
        // surcharge the fresh bin.
        if next_item_size > 0 && fitting_bins_count > 0 && open_bins_count > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_copies2 = (fresh_left / n).floor();
            let open_copies2 = (r / n).floor();
            if fresh_copies2 >= 2.0 && fresh_copies2 > open_copies2 + 0.5 {
                penalty -= 2.0 + 2.0 * (fresh_copies2 - open_copies2).min(3.0) * x;
            } else if open_copies2 > fresh_copies2 && open_copies2 >= 2.0 {
                penalty += 2.0 + 2.0 * x;
            }
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — reward filling the fullest available bin,
    // scaled by open-bin sprawl.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio pressure.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // Waste-stranding sweep.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        if r < n {
            score += 2.5 * (r / n) * (0.5 + x);
        } else if r < 2.0 * n {
            let after = r - n;
            if after > 0.0 && after < n {
                if after < 5.0 {
                    score += 2.0 * (1.0 - x);
                } else if after >= 5.0 && after < 15.0 {
                    score -= 1.0;
                }
            }
        }
    }

    // Cross-bin tightness gradient.
    if !is_new_bin && fitting_bins_count > 1 {
        let tight = 1.0 - (r / c).min(1.0);
        score -= 1.8 * tight * tight * (1.0 - (2.0 * x - 1.0).abs());
    }

    // Second-level dead-space probe.
    if !is_new_bin && next_item_size > 0 && r >= next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after = r - n;
        if after > 0.0 && after < 15.0 {
            score += (1.0 + x) * (1.0 - after / 15.0) * 2.0;
        } else if after >= 15.0 && after < 30.0 {
            score -= 0.8 * (1.0 - x);
        }
        if after > 0.0 && (after % 10.0) == 0.0 {
            score -= 1.2 + 1.2 * x;
        }
    }

    // Third-level chain probe.
    if !is_new_bin && next_item_size > 0 && r >= 2.0 * next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after2 = r - 2.0 * n;
        if after2 == 0.0 {
            score -= 3.0 + 3.0 * x;
        } else if after2 > 0.0 && after2 < 4.0 {
            score -= 1.5 + 1.5 * x;
        } else if after2 >= n && after2 < n + 4.0 {
            score -= 1.0 * (1.0 - x);
        } else if after2 > 0.0 && after2 < n * 0.4 {
            score += 1.5 * (0.5 + x);
        }
    }

    // Residual-efficiency gradient among fitting bins — compare each
    // candidate's post-residual to the cohort mean; bins stranding less
    // get a nonlinear reward, bins stranding more get a penalty.
    if !is_new_bin && fitting_bins_count > 2 && post_residual > 0 {
        let cohort = mean_residual.max(1.0);
        let rel = (r - cohort) / c;
        if rel < 0.0 {
            score -= (rel * -60.0).min(3.0) * (0.5 + x);
        } else {
            score += (rel * 40.0).min(2.0) * (0.5 + x);
        }
    }

    // MUTATION (gen 37): absolute dead-space tariff — beyond the cohort
    // gradient, charge a direct convex penalty on the raw stranded residual
    // whenever it is too small for the next item, so that among equal
    // post-residual bands the chooser still prefers the smallest strand.
    // Complemented by a reward when the strand is an exact multiple of
    // small common sizes (10/5), making it reusable by later items.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let n = next_item_size.max(1) as f64;
        let strand = r / n;
        score += 1.2 * strand * strand * (0.6 + 0.8 * x);
        if post_residual % 10 == 0 {
            score -= 1.5 * (0.5 + x);
        } else if post_residual % 5 == 0 {
            score -= 0.8 * (0.5 + x);
        }
    }

    // MUTATION (gen 37): two-item lookahead — when the residual after
    // placing the next item still exceeds the mean open-bin demand proxy,
    // the bin can likely host one more item beyond the immediate lookahead;
    // reward that depth slightly, scaled by stream progress.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 {
        let n = next_item_size.max(1) as f64;
        if r >= n {
            let after = r - n;
            if after >= mean_residual.max(n) {
                score -= 1.0 + 1.5 * x;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = r / c;
    let placed = (bin_residual - post_residual) as f64;

    // Base: superlinear small-post-residual preference, progress-scaled.
    let mut score = p * p * (1.0 + 2.0 * x) + 0.35 * p;

    // Tightness bonus on what was just placed.
    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (8.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect fill: strong reward, escalating late when bins are scarce.
    if post_residual == 0 {
        score -= 55.0 + 10.0 * x;
    } else if post_residual <= 5 {
        score -= 12.0 + 8.0 * x;
    }

    // Early stream: keep bins flexible.
    score += (1.0 - x) * p * (1.0 - p) * 3.0;

    // Dead-space penalty (quadratic in usable-space loss).
    let dead = (p * (1.0 - p * 4.0)).max(0.0);
    score += dead * (2.0 + 3.0 * x) + 2.5 * dead * dead * (1.0 + x);
    if post_residual > 0 {
        let min_live = (next_item_size.max(1) as f64).min(20.0);
        if r > 0.0 && r < min_live {
            score += 3.0 * (1.0 - r / min_live) * (1.0 + x);
        }
    }

    // Tiny unrescuable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + 4.0 * x;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Fragmentation guard.
    if post_residual > 0 && post_residual < bin_capacity / 5 && x < 0.85 {
        score += 4.0;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if x > 0.5 {
            score -= 10.0 * x;
        }
    }

    // Lookahead with snugness, chaining, and two-step chain depth.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r == n {
            score -= 40.0 + 5.0 * x;
        } else if n <= r {
            let snug = 1.0 - (r - n) / c;
            score -= 10.0 * snug;
            if r >= 2.0 * n {
                score -= 4.0;
            }
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                score += 5.0;
            } else if after >= n {
                score -= 3.0;
            }
            let chain_count = (r / n).floor();
            if chain_count >= 2.0 {
                score -= 2.0 * chain_count.min(4.0);
            }
            if after > 0.0 && after < n * 0.5 && after < 25.0 {
                score += 4.0 + 3.0 * x;
            }
            if after > 0.0 && after < n * 0.1 {
                score += 3.0 + 3.0 * x;
            }
            // Exact divisibility chain — zero-waste fill guarantee.
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 2 {
                score -= 5.0 + 4.0 * x;
            }
            // Two-step chain viability.
            if after > 0.0 && (after * 2.0) >= n && after < n {
                score -= 2.0 + 2.0 * x;
            }
            // Post-fit residual that is itself a multiple of the next item.
            if after > 0.0 && next_item_size > 0 && after as u32 % next_item_size == 0 {
                score -= 3.0 + 3.0 * x;
            }
        } else {
            let waste = (n - r) / n;
            score += 15.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 8.0;
            }
            if r > 0.0 && r < 20.0 {
                score += 3.0 * (1.0 - r / 20.0);
            }
            if r > 0.0 {
                score += 5.0 * waste * (1.0 - x);
            }
            if r > 0.0 {
                let gap = n - r;
                if gap < 8.0 {
                    score += 4.0 * (1.0 - gap / 8.0) * (0.5 + x);
                }
            }
        }
    }

    // Mean-residual coupling.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.08 * dev;
    } else {
        score += 0.05 * (-dev) * (item_size as f64 / c);
    }

    // New-bin candidate handling with adaptive escape valves.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut penalty = 35.0;
        if next_item_size > 0 && r > next_item_size as f64 + 30.0 {
            penalty -= 12.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 10.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 15.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        penalty -= 8.0 * x;
        if fitting_bins_count > 0 && open_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n * 0.5 {
                penalty -= 6.0 + 6.0 * (1.0 - r / n);
            }
        }
        if item_size as f64 >= 0.7 * c && x < 0.4 {
            penalty -= 6.0;
        }
        if fitting_bins_count > 0 && post_residual > 0 && post_residual < 12 && open_bins_count > 1 {
            penalty -= 9.0;
        }
        if fitting_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < 0.15 * c && open_bins_count > 2 {
                penalty -= 5.0 + 3.0 * x;
            }
        }
        if open_bins_count > 4 && mean_residual > 0.5 * c {
            penalty -= 4.0;
        }
        if next_item_size > 0 && open_bins_count > 0 {
            let n = next_item_size as f64;
            if r < n && n > 0.6 * c {
                penalty -= 7.0 + 5.0 * x;
            }
        }
        if x > 0.8 && item_size as f64 > 0.5 * c {
            penalty -= 5.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 1 && r > 0.6 * c && mean_residual < 0.35 * c {
            penalty -= 8.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < mean_residual * 0.5 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        penalty += 10.0 * x * x;
        if x > 0.95 && open_bins_count > 1 {
            penalty -= 4.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 {
            let n = next_item_size as f64;
            if r < n && r < 0.2 * c {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        if item_size as f64 > 0.55 * c && x < 0.25 && open_bins_count > 2 {
            penalty -= 5.0;
        }
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 3.0 + 3.0 * x;
        }
        // Only fitting bin strands less than half the next item — open fresh.
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        // Late stream with large mean residual — squeeze existing bins.
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        // Waste-budget coupling — compaction pressure on fresh bins.
        if open_bins_count > 0 {
            let frag = mean_residual / c;
            if frag < 0.3 {
                penalty += (0.3 - frag) * 20.0 * (1.0 - x);
            } else if frag > 0.55 && open_bins_count > 3 {
                penalty -= (frag - 0.55) * 18.0 * (0.5 + x);
            }
        }
        // Near-perfect fresh fill — opening is nearly free.
        let fresh_left = c - item_size as f64;
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Fresh-bin leftover divisibility sweep.
        if next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 6.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // Scale fresh-bin cost by open-bin fit quality.
        if fitting_bins_count > 0 {
            let best_use = 1.0 - (r / c).min(1.0);
            penalty += 14.0 * best_use * (0.4 + x);
        }
        // Open-bin sliver vs fresh strand comparison.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_absorbs = fresh_left >= n;
            if r > 0.0 && r < n {
                let fresh_strand = if fresh_absorbs {
                    let copies = (fresh_left / n).floor();
                    let l = fresh_left - copies * n;
                    if l > 0.0 { l } else { 0.0 }
                } else { fresh_left };
                if fresh_strand + 2.0 < r {
                    penalty -= 8.0 + 6.0 * x;
                } else if r < fresh_strand {
                    penalty += 4.0 + 4.0 * x;
                }
            }
        }
        // Open-bin residual just above the next item vs fresh strand.
        if fitting_bins_count > 0 && next_item_size > 0 && r >= next_item_size as f64 {
            let n = next_item_size.max(1) as f64;
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                let fresh_strand = if fresh_left >= n {
                    let copies = (fresh_left / n).floor();
                    let l = fresh_left - copies * n;
                    if l > 0.0 { l } else { 0.0 }
                } else { fresh_left };
                if fresh_strand + 4.0 < after {
                    penalty -= 5.0 + 4.0 * x;
                } else if after < fresh_strand {
                    penalty += 3.0 + 3.0 * x;
                }
            }
        }
        // Fresh-bin multi-copy viability probe.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left < n && r >= 2.0 * n && (r % n) == 0.0 {
                penalty += 6.0 + 5.0 * x;
            }
            let fresh_copies = (fresh_left / n).floor();
            let open_copies = (r / n).floor();
            if fresh_copies > open_copies && fresh_copies >= 3.0 && r > 0.0 {
                penalty -= 3.0 + 3.0 * x;
            }
        }
        // Late-stream fresh-bin surge pricing.
        if x > 0.7 {
            let fresh_waste = fresh_left / c;
            if fresh_waste > 0.5 {
                penalty += (fresh_waste - 0.5) * 18.0 * (x - 0.7) / 0.3;
            }
        }
        // Fresh-bin dead-space surcharge on odd slivers; discount exact reuse.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let after_f = fresh_left - n;
                if after_f > 0.0 && after_f < 20.0 && after_f < n {
                    penalty += (1.0 - after_f / 20.0) * (3.0 + 3.0 * x);
                } else if after_f == 0.0 {
                    penalty -= 4.0 + 3.0 * x;
                }
            }
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — reward filling the fullest bin.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio shaping — penalize placements stranding residual below
    // the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n {
            let dead_frac = (n - r) / n;
            score += dead_frac * dead_frac * (3.0 + 4.0 * x);
        }
    }

    // Live-space preservation among several fitting bins.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
        let n = next_item_size as f64;
        if r < n && r < 15.0 {
            score += 4.0 + 3.0 * x;
        }
    }

    // Fine discrimination among multiple fitting bins on next-item snugness.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
        let n = next_item_size as f64;
        if r >= n {
            let snug = 1.0 - (r - n) / n;
            score -= 2.5 * snug * (0.5 + x);
        } else {
            let frac = r / n;
            score += 2.0 * frac * (1.0 + x);
        }
    }

    // MUTATION (gen 37): residual-efficiency gradient among fitting bins —
    // compare each candidate's post-residual to the cohort mean residual;
    // bins stranding less than the cohort average get a nonlinear reward,
    // bins stranding more get a penalty. Sharpens close-fit selection and
    // attacks the diagnosed dead-space weakness.
    if !is_new_bin && fitting_bins_count > 2 && post_residual > 0 {
        let cohort = mean_residual.max(1.0);
        let rel = (r - cohort) / c;
        if rel < 0.0 {
            score -= (rel * -60.0).min(3.0) * (0.5 + x);
        } else {
            score += (rel * 40.0).min(2.0) * (0.5 + x);
        }
    }

    // MUTATION (gen 37): second-level dead-space probe — after placing the
    // next item, if the remaining residual is a tiny unrescuable sliver,
    // penalize; if it is a clean multiple of the next size, reward.
    if !is_new_bin && next_item_size > 0 && r >= next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after = r - n;
        if after > 0.0 && after < 15.0 {
            score += (1.0 + x) * (1.0 - after / 15.0) * 2.0;
        } else if after >= 15.0 && after < 30.0 {
            score -= 0.8 * (1.0 - x);
        }
        if after > 0.0 && (after % 10.0) == 0.0 {
            score -= 1.2 + 1.2 * x;
        }
    }

    // MUTATION (gen 37): third-level chain probe — two next-items ahead.
    if !is_new_bin && next_item_size > 0 && r >= 2.0 * next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after2 = r - 2.0 * n;
        if after2 == 0.0 {
            score -= 3.0 + 3.0 * x;
        } else if after2 > 0.0 && after2 < 4.0 {
            score -= 1.5 + 1.5 * x;
        } else if after2 >= n && after2 < n + 4.0 {
            score -= 1.0 * (1.0 - x);
        } else if after2 > 0.0 && after2 < n * 0.4 {
            score += 1.5 * (0.5 + x);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = r / c;
    let placed = (bin_residual - post_residual) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let n = next_item_size.max(1) as f64;

    let mut score = p * p * (1.0 + 2.0 * x) + 0.3 * p;

    // Superlinear tightness bonus on what was just placed.
    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (9.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect / near-perfect fills, escalating late.
    if post_residual == 0 {
        score -= 60.0 + 12.0 * x;
    } else if post_residual <= 5 {
        score -= 12.0 + 8.0 * x;
    }

    // Early stream: keep bins flexible.
    score += (1.0 - x) * p * (1.0 - p) * 3.0;

    // Dead-space penalty (quadratic in usable-space loss).
    let dead = (p * (1.0 - p * 4.0)).max(0.0);
    score += dead * (2.0 + 3.0 * x) + 2.5 * dead * dead * (1.0 + x);

    // Tiny unrescuable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + 4.0 * x;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Fragmentation guard.
    if post_residual > 0 && post_residual < bin_capacity / 5 && x < 0.85 {
        score += 4.0;
    }

    // Last-chance bin bonus.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
        if x > 0.5 {
            score -= 10.0 * x;
        }
    }

    // ---- Lookahead with snugness, chaining, chain depth ----
    if next_item_size > 0 {
        if r == n {
            score -= 45.0 + 5.0 * x;
        } else if n <= r {
            let snug = 1.0 - (r - n) / c;
            score -= 10.0 * snug;
            if r >= 2.0 * n {
                score -= 4.0;
            }
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                score += 5.0;
            } else if after >= n {
                score -= 3.0;
            }
            let chain_count = (r / n).floor();
            if chain_count >= 2.0 {
                score -= 2.0 * chain_count.min(4.0);
            }
            if after > 0.0 && after < n * 0.1 {
                score += 3.0 + 3.0 * x;
            }
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 2 {
                score -= 5.0 + 4.0 * x;
            }
            if after > 0.0 && (after * 2.0) >= n && after < n {
                score -= 2.0 + 2.0 * x;
            }
        } else {
            let waste = (n - r) / n;
            score += 15.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 8.0;
            }
            if r > 0.0 && r < 20.0 {
                score += 3.0 * (1.0 - r / 20.0);
            }
            if r > 0.0 {
                score += 5.0 * waste * (1.0 - x);
                let gap = n - r;
                if gap < 8.0 {
                    score += 4.0 * (1.0 - gap / 8.0) * (0.5 + x);
                }
            }
        }
    }

    // Mean-residual coupling.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.08 * dev;
    } else {
        score += 0.05 * (-dev) * (item_size as f64 / c);
    }

    // ---- New-bin candidate: full trade against best open-bin strand ----
    if is_new_bin {
        let fresh_left = c - item_size as f64;
        let mut penalty = 35.0;
        if next_item_size > 0 && r > n + 30.0 {
            penalty -= 12.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 10.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 15.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        penalty -= 8.0 * x;
        if fitting_bins_count > 0 && open_bins_count > 0 && next_item_size > 0 && r > 0.0 && r < n * 0.5 {
            penalty -= 6.0 + 6.0 * (1.0 - r / n);
