            score -= (rel * -60.0).min(3.0) * (0.5 + x);
        } else {
            score += (rel * 40.0).min(2.0) * (0.5 + x);
        }
    }

    // MUTATION (gen 37): dual-lookahead compaction — when the next item fits
    // this bin exactly AND the fresh-bin leftover would strand more waste,
    // reward strongly; when the next item cannot fit any post-residual but a
    // fresh bin's leftover would host it perfectly, tilt toward opening fresh
