                score += 5.0;
            } else if after >= n {
                score -= 3.0;
            }
            let chain_count = (r / n).floor();
            if chain_count >= 2.0 {
                score -= 2.0 * chain_count.min(4.0);
            }
            if after > 0.0 && after < n * 0.5 && after < 25.0 {
                score += 4.0 + 3.0 * x;
            }
            if after > 0.0 && after < n * 0.1 {
                score += 3.0 + 3.0 * x;
            }
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 2 {
                score -= 5.0 + 4.0 * x;
            }
            if after > 0.0 && (after * 2.0) >= n && after < n {
                score -= 2.0 + 2.0 * x;
            }
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 3 {
                score -= 3.0 + 3.0 * x;
            }
        } else {
            let waste = (n - r) / n;
            score += 15.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 8.0;
            }
            if r > 0.0 && r < 20.0 {
                score += 3.0 * (1.0 - r / 20.0);
            }
            if r > 0.0 {
                score += 5.0 * waste * (1.0 - x);
            }
            if r > 0.0 {
                let gap = n - r;
                if gap < 8.0 {
                    score += 4.0 * (1.0 - gap / 8.0) * (0.5 + x);
                }
            }
        }
    }

    // Mean-residual coupling.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.08 * dev;
    } else {
        score += 0.05 * (-dev) * (item_size as f64 / c);
    }

    // New-bin candidate handling with adaptive escape valves.
    let is_new_bin = bin_residual == bin_capacity;
    let fresh_left = c - item_size as f64;
    if is_new_bin {
        let mut penalty = 35.0;
        if next_item_size > 0 && r > next_item_size as f64 + 30.0 {
            penalty -= 12.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 10.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 15.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        penalty -= 8.0 * x;
        if fitting_bins_count > 0 && open_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n * 0.5 {
                penalty -= 6.0 + 6.0 * (1.0 - r / n);
            }
        }
        if item_size as f64 >= 0.7 * c && x < 0.4 {
            penalty -= 6.0;
        }
        if fitting_bins_count > 0 && post_residual > 0 && post_residual < 12 && open_bins_count > 1 {
            penalty -= 9.0;
        }
        if fitting_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < 0.15 * c && open_bins_count > 2 {
                penalty -= 5.0 + 3.0 * x;
            }
        }
        if open_bins_count > 4 && mean_residual > 0.5 * c {
            penalty -= 4.0;
        }
        if next_item_size > 0 && open_bins_count > 0 {
            let n = next_item_size as f64;
            if r < n && n > 0.6 * c {
                penalty -= 7.0 + 5.0 * x;
            }
        }
        if x > 0.8 && item_size as f64 > 0.5 * c {
            penalty -= 5.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 1 && r > 0.6 * c && mean_residual < 0.35 * c {
            penalty -= 8.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < mean_residual * 0.5 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        penalty += 10.0 * x * x;
        if x > 0.95 && open_bins_count > 1 {
            penalty -= 4.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 {
            let n = next_item_size as f64;
            if r < n && r < 0.2 * c {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n && fresh_left >= n {
                penalty -= 6.0 + 6.0 * x;
            }
            if fresh_left > 0.6 * c && r < 0.1 * c && open_bins_count > 0 {
                penalty -= 5.0;
            }
            if fresh_left >= n && fresh_left % n.max(1.0) < 1.0 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        if item_size as f64 > 0.55 * c && x < 0.25 && open_bins_count > 2 {
            penalty -= 5.0;
        }
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 3.0 + 3.0 * x;
        }
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        // Waste-budget coupling: fragmented stream -> fresh bins cheaper;
        // tight stream -> fresh bins pricier.
        if open_bins_count > 0 {
            let frag = mean_residual / c;
            let sprawl = open_bins_count as f64;
            if frag < 0.3 {
                penalty += (0.3 - frag) * 20.0 * (1.0 - x);
            } else if frag > 0.55 && sprawl > 3.0 {
                penalty -= (frag - 0.55) * 18.0 * (0.5 + x);
            }
        }
        // Near-perfect fresh fill discount.
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Fresh-bin leftover divisibility sweep.
        if next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 6.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // Scale fresh-bin cost by open-bin fit quality.
        if fitting_bins_count > 0 {
            let best_use = 1.0 - (r / c).min(1.0);
            penalty += 14.0 * best_use * (0.4 + x);
        }
        // Open-bin fit quality sweep vs fresh strand.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_absorbs = fresh_left >= n;
            if r > 0.0 && r < n {
                let fresh_strand = if fresh_absorbs {
                    let copies = (fresh_left / n).floor();
                    let l = fresh_left - copies * n;
                    if l > 0.0 { l } else { 0.0 }
                } else { fresh_left };
                if fresh_strand + 2.0 < r {
                    penalty -= 8.0 + 6.0 * x;
                } else if r < fresh_strand {
                    penalty += 4.0 + 4.0 * x;
                }
            }
        }
        // Wider trade window: open-bin residuals just above next item.
        if fitting_bins_count > 0 && next_item_size > 0 && r >= next_item_size as f64 {
            let n = next_item_size.max(1) as f64;
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                let fresh_strand = if fresh_left >= n {
                    let copies = (fresh_left / n).floor();
                    let l = fresh_left - copies * n;
                    if l > 0.0 { l } else { 0.0 }
                } else { fresh_left };
                if fresh_strand + 4.0 < after {
                    penalty -= 5.0 + 4.0 * x;
                } else if after < fresh_strand {
                    penalty += 3.0 + 3.0 * x;
                }
            }
        }
        // Three-step fresh-bin viability probe.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left < n && r >= 2.0 * n && (r % n) == 0.0 {
                penalty += 6.0 + 5.0 * x;
            }
            let fresh_copies = (fresh_left / n).floor();
            let open_copies = (r / n).floor();
            if fresh_copies > open_copies && fresh_copies >= 3.0 && r > 0.0 {
                penalty -= 3.0 + 3.0 * x;
            }
        }
        // Late-stream fresh-bin surge pricing.
        if x > 0.7 {
            let fresh_waste = fresh_left / c;
            if fresh_waste > 0.5 {
                penalty += (fresh_waste - 0.5) * 18.0 * (x - 0.7) / 0.3;
            }
        }
        // Fresh-bin dead-space surcharge for odd slivers.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let after_f = fresh_left - n;
                if after_f > 0.0 && after_f < 20.0 && after_f < n {
                    penalty += (1.0 - after_f / 20.0) * (3.0 + 3.0 * x);
                } else if after_f == 0.0 {
                    penalty -= 4.0 + 3.0 * x;
                }
            }
        }
        // MUTATION (gen 37): late-stream fresh-bin suppression — near the end
        // of the stream, opening a fresh bin that cannot be refilled by the
        // next item is almost always wasted capacity; make it expensive.
        if x > 0.85 && next_item_size > 0 && fresh_left < next_item_size as f64 && fitting_bins_count > 0 {
            penalty += 12.0 * (x - 0.85) / 0.15;
        }
        // MUTATION (gen 37): fresh-bin exact-capacity probe — when the item
        // plus next item exactly fills a fresh bin but open bins strand
        // dead space, opening fresh is a two-item zero-waste play.
        if next_item_size > 0 && (fresh_left as u32) == next_item_size && fitting_bins_count > 0 {
            penalty -= 10.0 + 6.0 * x;
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio shaping.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // Waste-stranding sweep.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        if r < n {
            score += 2.5 * (r / n) * (0.5 + x);
        } else if r < 2.0 * n {
            let after = r - n;
            if after > 0.0 && after < n {
                if after < 5.0 {
                    score += 2.0 * (1.0 - x);
                } else if after >= 5.0 && after < 15.0 {
                    score -= 1.0;
                }
            }
        }
    }

    // Cross-bin tightness gradient.
    if !is_new_bin && fitting_bins_count > 1 {
        let tight = 1.0 - (r / c).min(1.0);
        score -= 1.8 * tight * tight * (1.0 - (2.0 * x - 1.0).abs());
    }

    // Second-level dead-space probe.
    if !is_new_bin && next_item_size > 0 && r >= next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after = r - n;
        if after > 0.0 && after < 15.0 {
            score += (1.0 + x) * (1.0 - after / 15.0) * 2.0;
        } else if after >= 15.0 && after < 30.0 {
            score -= 0.8 * (1.0 - x);
        }
        if after > 0.0 && (after % 10.0) == 0.0 {
            score -= 1.2 + 1.2 * x;
        }
    }

    // Third-level chain probe.
    if !is_new_bin && next_item_size > 0 && r >= 2.0 * next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after2 = r - 2.0 * n;
        if after2 == 0.0 {
            score -= 3.0 + 3.0 * x;
        } else if after2 > 0.0 && after2 < 4.0 {
            score -= 1.5 + 1.5 * x;
        } else if after2 >= n && after2 < n + 4.0 {
            score -= 1.0 * (1.0 - x);
        } else if after2 > 0.0 && after2 < n * 0.4 {
            score += 1.5 * (0.5 + x);
        }
    }

    // Residual-efficiency gradient among fitting bins.
    if !is_new_bin && fitting_bins_count > 2 && post_residual > 0 {
        let cohort = mean_residual.max(1.0);
        let rel = (r - cohort) / c;
        if rel < 0.0 {
            score -= (rel * -60.0).min(3.0) * (0.5 + x);
        } else {
            score += (rel * 40.0).min(2.0) * (0.5 + x);
        }
    }

    // MUTATION (gen 37): perfect-fill lookahead among fitting bins — when a
    // bin would be filled exactly by this item and the next one combined,
    // reward it strongly; this closes bins that would otherwise linger as
    // near-full stragglers consuming the bin budget.
    if !is_new_bin && next_item_size > 0 && post_residual > 0
        && post_residual as u32 == next_item_size {
        score -= 8.0 + 6.0 * x;
    }

    // MUTATION (gen 37): dead-space ratio pressure — penalize residuals
    // stranded in the awkward mid-band (unusable for typical small items
    // yet too large to ignore), scaled by stream progress.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = r / c;
    let placed = (bin_residual - post_residual) as f64;

    // Base: superlinear small-post-residual preference, progress-scaled.
    let mut score = p * p * (1.0 + 2.0 * x) + 0.35 * p;

    // Tightness bonus on what was just placed.
    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (8.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect fill: strong reward, escalating late when bins are scarce.
    if post_residual == 0 {
        score -= 55.0 + 10.0 * x;
    } else if post_residual <= 5 {
        score -= 12.0 + 8.0 * x;
    }

    // Early stream: keep bins flexible.
    score += (1.0 - x) * p * (1.0 - p) * 3.0;

    // Dead-space penalty (quadratic in usable-space loss).
    let dead = (p * (1.0 - p * 4.0)).max(0.0);
    score += dead * (2.0 + 3.0 * x) + 2.5 * dead * dead * (1.0 + x);
    if post_residual > 0 {
        let min_live = (next_item_size.max(1) as f64).min(20.0);
        if r > 0.0 && r < min_live {
            score += 3.0 * (1.0 - r / min_live) * (1.0 + x);
        }
    }

    // Tiny unrescuable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + 4.0 * x;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Fragmentation guard.
    if post_residual > 0 && post_residual < bin_capacity / 5 && x < 0.85 {
        score += 4.0;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if x > 0.5 {
            score -= 10.0 * x;
        }
    }

    // Lookahead with snugness, chaining, and two-step chain depth.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r == n {
            score -= 40.0 + 5.0 * x;
        } else if n <= r {
            let snug = 1.0 - (r - n) / c;
            score -= 10.0 * snug;
            if r >= 2.0 * n {
                score -= 4.0;
            }
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                score += 5.0;
            } else if after >= n {
                score -= 3.0;
            }
            let chain_count = (r / n).floor();
            if chain_count >= 2.0 {
                score -= 2.0 * chain_count.min(4.0);
            }
            if after > 0.0 && after < n * 0.5 && after < 25.0 {
                score += 4.0 + 3.0 * x;
            }
            if after > 0.0 && after < n * 0.1 {
                score += 3.0 + 3.0 * x;
            }
            // Exact divisibility chain — zero-waste fill guarantee.
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 2 {
                score -= 5.0 + 4.0 * x;
            }
            // Two-step chain viability.
            if after > 0.0 && (after * 2.0) >= n && after < n {
                score -= 2.0 + 2.0 * x;
            }
        } else {
            let waste = (n - r) / n;
            score += 15.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 8.0;
            }
            if r > 0.0 && r < 20.0 {
                score += 3.0 * (1.0 - r / 20.0);
            }
            if r > 0.0 {
                score += 5.0 * waste * (1.0 - x);
            }
            if r > 0.0 {
                let gap = n - r;
                if gap < 8.0 {
                    score += 4.0 * (1.0 - gap / 8.0) * (0.5 + x);
                }
            }
        }
    }

    // Mean-residual coupling.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.08 * dev;
    } else {
        score += 0.05 * (-dev) * (item_size as f64 / c);
    }

    // New-bin candidate handling with adaptive escape valves.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut penalty = 35.0;
        if next_item_size > 0 && r > next_item_size as f64 + 30.0 {
            penalty -= 12.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 10.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 15.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        penalty -= 8.0 * x;
        if fitting_bins_count > 0 && open_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n * 0.5 {
                penalty -= 6.0 + 6.0 * (1.0 - r / n);
            }
        }
        if item_size as f64 >= 0.7 * c && x < 0.4 {
            penalty -= 6.0;
        }
        if fitting_bins_count > 0 && post_residual > 0 && post_residual < 12 && open_bins_count > 1 {
            penalty -= 9.0;
        }
        if fitting_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < 0.15 * c && open_bins_count > 2 {
                penalty -= 5.0 + 3.0 * x;
            }
        }
        if open_bins_count > 4 && mean_residual > 0.5 * c {
            penalty -= 4.0;
        }
        if next_item_size > 0 && open_bins_count > 0 {
            let n = next_item_size as f64;
            if r < n && n > 0.6 * c {
                penalty -= 7.0 + 5.0 * x;
            }
        }
        if x > 0.8 && item_size as f64 > 0.5 * c {
            penalty -= 5.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 1 && r > 0.6 * c && mean_residual < 0.35 * c {
            penalty -= 8.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < mean_residual * 0.5 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        penalty += 10.0 * x * x;
        if x > 0.95 && open_bins_count > 1 {
            penalty -= 4.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 {
            let n = next_item_size as f64;
            if r < n && r < 0.2 * c {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        // Compare best achievable post-residual on an open bin against the
        // fresh-bin leftover; prefer the new bin when it strands less waste.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            let fresh_left = c - item_size as f64;
            if r > 0.0 && r < n && fresh_left >= n {
                penalty -= 6.0 + 6.0 * x;
            }
            if fresh_left > 0.6 * c && r < 0.1 * c && open_bins_count > 0 {
                penalty -= 5.0;
            }
            // Fresh-bin residual exactly fits the next item: zero-waste follow-up.
            if fresh_left >= n && fresh_left % n.max(1.0) < 1.0 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        // Large item early on — dedicated bin beats carving a partial one.
        if item_size as f64 > 0.55 * c && x < 0.25 && open_bins_count > 2 {
            penalty -= 5.0;
        }
        // Heavy fragmentation: opening fresh and consolidating is preferable.
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 3.0 + 3.0 * x;
        }
        // When the only fitting bins would leave residual smaller than half
        // the next item, opening fresh is cheap — avoids stranding.
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        // Late stream with large mean residual — squeeze existing bins harder.
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        // Waste-budget coupling — when total stranded residual is small
        // relative to the stream, fresh bins get pricier; when fragmentation
        // is high, they get cheaper. Drives compaction.
        if open_bins_count > 0 {
            let frag = mean_residual / c;
            let sprawl = open_bins_count as f64;
            if frag < 0.3 {
                penalty += (0.3 - frag) * 20.0 * (1.0 - x);
            } else if frag > 0.55 && sprawl > 3.0 {
                penalty -= (frag - 0.55) * 18.0 * (0.5 + x);
            }
        }
        // Near-perfect fresh fill — if the item almost exactly fills a new
        // bin, opening it is nearly free.
        let fresh_left = c - item_size as f64;
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Fresh-bin leftover divisibility sweep — reward when the fresh
        // leftover can absorb several copies of the next item exactly.
        if next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 6.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // Scale fresh-bin cost by how well the best open-bin fit would use
        // space — when open bins fit tightly, fresh bins cost more.
        if fitting_bins_count > 0 {
            let best_use = 1.0 - (r / c).min(1.0);
            penalty += 14.0 * best_use * (0.4 + x);
        }
        // Open-bin fit quality sweep — when the best open-bin post-residual
        // is a tiny unusable sliver, opening fresh becomes much cheaper;
        // when the open-bin leftover is large and reusable, fresh bins get
        // pricier. Directly attacks dead-space waste.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_leftover = c - item_size as f64;
            let fresh_absorbs = fresh_leftover >= n;
            if r > 0.0 && r < n {
                let fresh_strand = if fresh_absorbs {
                    let copies = (fresh_leftover / n).floor();
                    let l = fresh_leftover - copies * n;
                    if l > 0.0 { l } else { 0.0 }
                } else { fresh_leftover };
                if fresh_strand + 2.0 < r {
                    penalty -= 8.0 + 6.0 * x;
                } else if r < fresh_strand {
                    penalty += 4.0 + 4.0 * x;
                }
            }
        }
        // Dead-space budget sweep refinement — widen the trade window so
        // that open-bin residuals just above the next item size are also
        // compared against the fresh-bin strand.
        if fitting_bins_count > 0 && next_item_size > 0 && r >= next_item_size as f64 {
            let n = next_item_size.max(1) as f64;
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                let fresh_leftover = c - item_size as f64;
                let fresh_strand = if fresh_leftover >= n {
                    let copies = (fresh_leftover / n).floor();
                    let l = fresh_leftover - copies * n;
                    if l > 0.0 { l } else { 0.0 }
                } else { fresh_leftover };
                if fresh_strand + 4.0 < after {
                    penalty -= 5.0 + 4.0 * x;
                } else if after < fresh_strand {
                    penalty += 3.0 + 3.0 * x;
                }
            }
        }
        // Three-step fresh-bin viability probe.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_leftover = c - item_size as f64;
            if fresh_leftover < n && r >= 2.0 * n && (r % n) == 0.0 {
                penalty += 6.0 + 5.0 * x;
            }
            let fresh_copies = (fresh_leftover / n).floor();
            let open_copies = (r / n).floor();
            if fresh_copies > open_copies && fresh_copies >= 3.0 && r > 0.0 {
                penalty -= 3.0 + 3.0 * x;
            }
        }
        // Late-stream fresh-bin surge pricing.
        if x > 0.7 {
            let fresh_waste = fresh_left / c;
            if fresh_waste > 0.5 {
                penalty += (fresh_waste - 0.5) * 18.0 * (x - 0.7) / 0.3;
            }
        }
        // Fresh-bin dead-space surcharge — when the fresh leftover after
        // absorbing the next item is a small odd sliver that no typical item
        // (<= 20) can absorb, charge extra; when the fresh leftover is
        // exactly reusable, discount further.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let after_f = fresh_left - n;
                if after_f > 0.0 && after_f < 20.0 && after_f < n {
                    penalty += (1.0 - after_f / 20.0) * (3.0 + 3.0 * x);
                } else if after_f == 0.0 {
                    penalty -= 4.0 + 3.0 * x;
                }
            }
        }
        // MUTATION (gen 37): fresh-bin strand-vs-sprawl trade — the cost of
        // opening a fresh bin should scale with how much dead space it
        // strands relative to the number of open bins that could absorb it.
        // When sprawl is high, a fresh bin's stranded sliver is diluted
        // across fewer future placements, so discount it more aggressively;
        // when sprawl is low, charge proportionally more.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let sprawl_f = (open_bins_count as f64).max(1.0);
            if fresh_left > 0.0 && fresh_left < n {
                // Fresh bin strands an immediately-unusable sliver.
                penalty += (1.0 - fresh_left / n) * (4.0 + 2.0 * x) * (2.0 / sprawl_f).min(2.0);
            } else if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let l = fresh_left - copies * n;
                if l > 0.0 && l < n * 0.2 {
                    // Nearly exact divisibility: small discount, sprawl-scaled.
                    penalty -= (1.0 - l / (n * 0.2)) * 3.0 * (1.0 + x) * (sprawl_f / (sprawl_f + 3.0));
                }
            }
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — reward filling the fullest available bin,
    // scaled by open-bin sprawl.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio pressure.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // Waste-stranding sweep.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        if r < n {
            score += 2.5 * (r / n) * (0.5 + x);
        } else if r < 2.0 * n {
            let after = r - n;
            if after > 0.0 && after < n {
                if after < 5.0 {
                    score += 2.0 * (1.0 - x);
                } else if after >= 5.0 && after < 15.0 {
                    score -= 1.0;
                }
            }
        }
    }

    // Cross-bin tightness gradient.
    if !is_new_bin && fitting_bins_count > 1 {
        let tight = 1.0 - (r / c).min(1.0);
        score -= 1.8 * tight * tight * (1.0 - (2.0 * x - 1.0).abs());
    }

    // Second-level dead-space probe.
    if !is_new_bin && next_item_size > 0 && r >= next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after = r - n;
        if after > 0.0 && after < 15.0 {
            score += (1.0 + x) * (1.0 - after / 15.0) * 2.0;
        } else if after >= 15.0 && after < 30.0 {
            score -= 0.8 * (1.0 - x);
        }
        if after > 0.0 && (after % 10.0) == 0.0 {
            score -= 1.2 + 1.2 * x;
        }
    }

    // Third-level chain probe.
    if !is_new_bin && next_item_size > 0 && r >= 2.0 * next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after2 = r - 2.0 * n;
        if after2 == 0.0 {
            score -= 3.0 + 3.0 * x;
        } else if after2 > 0.0 && after2 < 4.0 {
            score -= 1.5 + 1.5 * x;
        } else if after2 >= n && after2 < n + 4.0 {
            score -= 1.0 * (1.0 - x);
        } else if after2 > 0.0 && after2 < n * 0.4 {
            score += 1.5 * (0.5 + x);
        }
    }

    // Residual-efficiency gradient among fitting bins — when multiple bins
    // fit, compare each candidate's post-residual to the mean of what the
    // others would leave; bins that strand notably less than the cohort
    // average get a nonlinear reward, bins stranding more get a penalty.
    // MUTATION (gen 37): sharpen the gradient — scale reward/penalty by the
    // number of competing fitting bins so discrimination intensifies when
    // more alternatives exist, and tighten the cap asymmetrically so
    // penalizing stranders outweighs rewarding tight fits slightly.
    if !is_new_bin && fitting_bins_count > 2 && post_residual > 0 {
        let cohort = mean_residual.max(1.0);
        let rel = (r - cohort) / c;
        let depth = (fitting_bins_count as f64).min(6.0) / 6.0;
        if rel < 0.0 {
            score -= ((rel * -60.0) * (0.6 + 0.6 * depth)).min(3.5) * (0.5 + x);
        } else {
            score += ((rel * 40.0) * (0.6 + 0.6 * depth)).min(1.8) * (0.5 + x);
        }
    }

    // MUTATION (gen 37): cohort-relative snugness sweep — among fitting bins,
    // prefer the one whose post-residual best anticipates the item AFTER the
    // next one, approximated as half the next item size. Bins leaving a
    // residual near n/2 (a likely next-next fit) or near zero get a
    // progress-scaled bonus; bins leaving residuals in the dead zone just
    // below n get a mild extra penalty. Attacks residual dead space directly.
    if !is_new_bin && fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 {
        let n = next_item_size.max(1) as f64;
        let half_n = n * 0.5;
        if r >= half_n {
            let closeness = 1.0 - ((r - half_n) / (c - half_n)).min(1.0);
            score -= 1.6 * closeness * closeness * (0.4 + x);
        } else {
            score += 1.2 * (1.0 - r / half_n) * (0.5 + x);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = r / c;
    let placed = (bin_residual - post_residual) as f64;

    // Base: superlinear small-post-residual preference, progress-scaled.
    let mut score = p * p * (1.0 + 2.0 * x) + 0.35 * p;

    // Tightness bonus on what was just placed.
    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (8.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect fill: strong reward, escalating late when bins are scarce.
    if post_residual == 0 {
        score -= 55.0 + 10.0 * x;
    } else if post_residual <= 5 {
        score -= 12.0 + 8.0 * x;
    }

    // Early stream: keep bins flexible.
    score += (1.0 - x) * p * (1.0 - p) * 3.0;

    // Dead-space penalty (quadratic in usable-space loss).
    let dead = (p * (1.0 - p * 4.0)).max(0.0);
    score += dead * (2.0 + 3.0 * x) + 2.5 * dead * dead * (1.0 + x);
    if post_residual > 0 {
        let min_live = (next_item_size.max(1) as f64).min(20.0);
        if r > 0.0 && r < min_live {
            score += 3.0 * (1.0 - r / min_live) * (1.0 + x);
        }
    }

    // Tiny unrescuable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + 4.0 * x;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Fragmentation guard.
    if post_residual > 0 && post_residual < bin_capacity / 5 && x < 0.85 {
        score += 4.0;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if x > 0.5 {
            score -= 10.0 * x;
        }
    }

    // Lookahead with snugness, chaining, and two-step chain depth.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r == n {
            score -= 40.0 + 5.0 * x;
        } else if n <= r {
            let snug = 1.0 - (r - n) / c;
            score -= 10.0 * snug;
            if r >= 2.0 * n {
                score -= 4.0;
            }
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                score += 5.0;
            } else if after >= n {
                score -= 3.0;
            }
            let chain_count = (r / n).floor();
            if chain_count >= 2.0 {
                score -= 2.0 * chain_count.min(4.0);
            }
            if after > 0.0 && after < n * 0.5 && after < 25.0 {
                score += 4.0 + 3.0 * x;
            }
            if after > 0.0 && after < n * 0.1 {
                score += 3.0 + 3.0 * x;
            }
            // Exact divisibility chain — zero-waste fill guarantee.
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 2 {
                score -= 5.0 + 4.0 * x;
            }
            // Two-step chain viability.
            if after > 0.0 && (after * 2.0) >= n && after < n {
                score -= 2.0 + 2.0 * x;
            }
        } else {
            let waste = (n - r) / n;
            score += 15.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 8.0;
            }
            if r > 0.0 && r < 20.0 {
                score += 3.0 * (1.0 - r / 20.0);
            }
            if r > 0.0 {
                score += 5.0 * waste * (1.0 - x);
            }
            if r > 0.0 {
                let gap = n - r;
                if gap < 8.0 {
                    score += 4.0 * (1.0 - gap / 8.0) * (0.5 + x);
                }
            }
        }
    }

    // Mean-residual coupling.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.08 * dev;
    } else {
        score += 0.05 * (-dev) * (item_size as f64 / c);
    }

    // New-bin candidate handling with adaptive escape valves.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut penalty = 35.0;
        if next_item_size > 0 && r > next_item_size as f64 + 30.0 {
            penalty -= 12.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 10.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 15.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        penalty -= 8.0 * x;
        if fitting_bins_count > 0 && open_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n * 0.5 {
                penalty -= 6.0 + 6.0 * (1.0 - r / n);
            }
        }
        if item_size as f64 >= 0.7 * c && x < 0.4 {
            penalty -= 6.0;
        }
        if fitting_bins_count > 0 && post_residual > 0 && post_residual < 12 && open_bins_count > 1 {
            penalty -= 9.0;
        }
        if fitting_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < 0.15 * c && open_bins_count > 2 {
                penalty -= 5.0 + 3.0 * x;
            }
        }
        if open_bins_count > 4 && mean_residual > 0.5 * c {
            penalty -= 4.0;
        }
        if next_item_size > 0 && open_bins_count > 0 {
            let n = next_item_size as f64;
            if r < n && n > 0.6 * c {
                penalty -= 7.0 + 5.0 * x;
            }
        }
        if x > 0.8 && item_size as f64 > 0.5 * c {
            penalty -= 5.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 1 && r > 0.6 * c && mean_residual < 0.35 * c {
            penalty -= 8.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < mean_residual * 0.5 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        penalty += 10.0 * x * x;
        if x > 0.95 && open_bins_count > 1 {
            penalty -= 4.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 {
            let n = next_item_size as f64;
            if r < n && r < 0.2 * c {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        // Compare best achievable post-residual on an open bin against the
        // fresh-bin leftover; prefer the new bin when it strands less waste.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            let fresh_left = c - item_size as f64;
            if r > 0.0 && r < n && fresh_left >= n {
                penalty -= 6.0 + 6.0 * x;
            }
            if fresh_left > 0.6 * c && r < 0.1 * c && open_bins_count > 0 {
                penalty -= 5.0;
            }
            // Fresh-bin residual exactly fits the next item: zero-waste follow-up.
            if fresh_left >= n && fresh_left % n.max(1.0) < 1.0 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        // Large item early on — dedicated bin beats carving a partial one.
        if item_size as f64 > 0.55 * c && x < 0.25 && open_bins_count > 2 {
            penalty -= 5.0;
        }
        // Heavy fragmentation: opening fresh and consolidating is preferable.
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 3.0 + 3.0 * x;
        }
        // When the only fitting bins would leave residual smaller than half
        // the next item, opening fresh is cheap — avoids stranding.
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        // Late stream with large mean residual — squeeze existing bins harder.
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        // Waste-budget coupling — when total stranded residual is small
        // relative to the stream, fresh bins get pricier; when fragmentation
        // is high, they get cheaper. Drives compaction.
        if open_bins_count > 0 {
            let frag = mean_residual / c;
            let sprawl = open_bins_count as f64;
            if frag < 0.3 {
                penalty += (0.3 - frag) * 20.0 * (1.0 - x);
            } else if frag > 0.55 && sprawl > 3.0 {
                penalty -= (frag - 0.55) * 18.0 * (0.5 + x);
            }
        }
        // Near-perfect fresh fill — if the item almost exactly fills a new
        // bin, opening it is nearly free.
        let fresh_left = c - item_size as f64;
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Fresh-bin leftover divisibility sweep — reward when the fresh
        // leftover can absorb several copies of the next item exactly.
        if next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 6.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // Scale fresh-bin cost by how well the best open-bin fit would use
        // space — when open bins fit tightly, fresh bins cost more.
        if fitting_bins_count > 0 {
            let best_use = 1.0 - (r / c).min(1.0);
            penalty += 14.0 * best_use * (0.4 + x);
        }
        // Open-bin fit quality sweep — when the best open-bin post-residual
        // is a tiny unusable sliver, opening fresh becomes much cheaper;
        // when the open-bin leftover is large and reusable, fresh bins get
        // pricier. Directly attacks dead-space waste.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_leftover = c - item_size as f64;
            let fresh_absorbs = fresh_leftover >= n;
            if r > 0.0 && r < n {
                let fresh_strand = if fresh_absorbs {
                    let copies = (fresh_leftover / n).floor();
                    let l = fresh_leftover - copies * n;
                    if l > 0.0 { l } else { 0.0 }
                } else { fresh_leftover };
                if fresh_strand + 2.0 < r {
                    penalty -= 8.0 + 6.0 * x;
                } else if r < fresh_strand {
                    penalty += 4.0 + 4.0 * x;
                }
            }
        }
        // Dead-space budget sweep refinement — widen the trade window so
        // that open-bin residuals just above the next item size are also
        // compared against the fresh-bin strand.
        if fitting_bins_count > 0 && next_item_size > 0 && r >= next_item_size as f64 {
            let n = next_item_size.max(1) as f64;
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                let fresh_leftover = c - item_size as f64;
                let fresh_strand = if fresh_leftover >= n {
                    let copies = (fresh_leftover / n).floor();
                    let l = fresh_leftover - copies * n;
                    if l > 0.0 { l } else { 0.0 }
                } else { fresh_leftover };
                if fresh_strand + 4.0 < after {
                    penalty -= 5.0 + 4.0 * x;
                } else if after < fresh_strand {
                    penalty += 3.0 + 3.0 * x;
                }
            }
        }
        // Three-step fresh-bin viability probe.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_leftover = c - item_size as f64;
            if fresh_leftover < n && r >= 2.0 * n && (r % n) == 0.0 {
                penalty += 6.0 + 5.0 * x;
            }
            let fresh_copies = (fresh_leftover / n).floor();
            let open_copies = (r / n).floor();
            if fresh_copies > open_copies && fresh_copies >= 3.0 && r > 0.0 {
                penalty -= 3.0 + 3.0 * x;
            }
        }
        // Late-stream fresh-bin surge pricing.
        if x > 0.7 {
            let fresh_waste = fresh_left / c;
            if fresh_waste > 0.5 {
                penalty += (fresh_waste - 0.5) * 18.0 * (x - 0.7) / 0.3;
            }
        }
        // Fresh-bin dead-space surcharge — when the fresh leftover after
        // absorbing the next item is a small odd sliver that no typical item
        // (<= 20) can absorb, charge extra; when the fresh leftover is
        // exactly reusable, discount further.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let after_f = fresh_left - n;
                if after_f > 0.0 && after_f < 20.0 && after_f < n {
                    penalty += (1.0 - after_f / 20.0) * (3.0 + 3.0 * x);
                } else if after_f == 0.0 {
                    penalty -= 4.0 + 3.0 * x;
                }
            }
        }
        // Gen-37 mutation: fresh-bin strand-vs-sprawl trade.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let sprawl_f = (open_bins_count as f64).max(1.0);
            if fresh_left > 0.0 && fresh_left < n {
                penalty += (1.0 - fresh_left / n) * (4.0 + 2.0 * x) * (2.0 / sprawl_f).min(2.0);
            } else if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let l = fresh_left - copies * n;
                if l > 0.0 && l < n * 0.2 {
                    penalty -= (1.0 - l / (n * 0.2)) * 3.0 * (1.0 + x) * (sprawl_f / (sprawl_f + 3.0));
                }
            }
        }
        // MUTATION (gen 38): fresh-bin horizon probe — when the fresh-bin
        // leftover is very small (< 10) but nonzero, it is a stranded sliver
        // that will likely never be used; charge a progress-scaled surcharge.
        // Conversely, when the fresh leftover is within 10 of capacity's
        // usable band (item is tiny relative to capacity), a fresh bin
        // preserves maximal flexibility and gets a mild discount.
        if fitting_bins_count > 0 {
            if fresh_left > 0.0 && fresh_left < 10.0 {
                penalty += (1.0 - fresh_left / 10.0) * (2.0 + 4.0 * x);
            }
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — reward filling the fullest available bin,
    // scaled by open-bin sprawl.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio pressure.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // Waste-stranding sweep.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        if r < n {
            score += 2.5 * (r / n) * (0.5 + x);
        } else if r < 2.0 * n {
            let after = r - n;
            if after > 0.0 && after < n {
                if after < 5.0 {
                    score += 2.0 * (1.0 - x);
                } else if after >= 5.0 && after < 15.0 {
                    score -= 1.0;
                }
            }
        }
    }

    // Cross-bin tightness gradient.
    if !is_new_bin && fitting_bins_count > 1 {
        let tight = 1.0 - (r / c).min(1.0);
        score -= 1.8 * tight * tight * (1.0 - (2.0 * x - 1.0).abs());
    }

    // Second-level dead-space probe.
    if !is_new_bin && next_item_size > 0 && r >= next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after = r - n;
        if after > 0.0 && after < 15.0 {
            score += (1.0 + x) * (1.0 - after / 15.0) * 2.0;
        } else if after >= 15.0 && after < 30.0 {
            score -= 0.8 * (1.0 - x);
        }
        if after > 0.0 && (after % 10.0) == 0.0 {
            score -= 1.2 + 1.2 * x;
        }
    }

    // Third-level chain probe.
    if !is_new_bin && next_item_size > 0 && r >= 2.0 * next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after2 = r - 2.0 * n;
        if after2 == 0.0 {
            score -= 3.0 + 3.0 * x;
        } else if after2 > 0.0 && after2 < 4.0 {
            score -= 1.5 + 1.5 * x;
        } else if after2 >= n && after2 < n + 4.0 {
            score -= 1.0 * (1.0 - x);
        } else if after2 > 0.0 && after2 < n * 0.4 {
            score += 1.5 * (0.5 + x);
        }
    }

    // Residual-efficiency gradient among fitting bins.
    if !is_new_bin && fitting_bins_count > 2 && post_residual > 0 {
        let cohort = mean_residual.max(1.0);
        let rel = (r - cohort) / c;
        let depth = (fitting_bins_count as f64).min(6.0) / 6.0;
        if rel < 0.0 {
            score -= ((rel * -60.0) * (0.6 + 0.6 * depth)).min(3.5) * (0.5 + x);
        } else {
            score += ((rel * 40.0) * (0.6 + 0.6 * depth)).min(1.8) * (0.5 + x);
        }
    }

    // Cohort-relative snugness sweep.
    if !is_new_bin && fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 {
        let n = next_item_size.max(1) as f64;
        let half_n = n * 0.5;
        if r >= half_n {
            let closeness = 1.0 - ((r - half_n) / (c - half_n)).min(1.0);
            score -= 1.6 * closeness * closeness * (0.4 + x);
        } else {
            score += 1.2 * (1.0 - r / half_n) * (0.5 + x);
        }
    }

    // MUTATION (gen 38): dead-space absorbability horizon — among fitting
    // bins, weight the post-residual by how likely ANY future item could use
    // it. A residual r is "live" if r >= smallest plausible item (approx.
    // min(item_size, next_item_size)); residuals just below that threshold
    // are pure dead weight and get an escalating penalty, while residuals
    // comfortably above it get a mild discount. Progress-scaled so late in
    // the stream (fewer chances to recycle a residual) the penalty bites
    // harder, directly attacking the diagnosed dead-space weakness.
    if !is_new_bin && post_residual > 0 {
        let min_item = if next_item_size > 0 {
            (item_size.min(next_item_size)).max(1) as f64
        } else {
            item_size.max(1) as f64
        };
        if r < min_item {
            score += (1.0 - r / min_item) * (5.0 + 5.0 * x);
        } else if r < min_item * 1.5 {
            score += 1.0 + x;
        } else {
            score -= 0.8 * (1.0 - x);
        }
    }

    // MUTATION (gen 38): bin-level fill saturation target — prefer bins whose
    // post-placement fill ratio lands in the high-saturation band
    // [0.85, 0.97]; fills above 0.97 with nonzero residual are slightly
    // penalized (near-exact but stranding), while fills below 0.85 are
    // gently pushed toward the band. Sharpens compaction without disturbing
    // the perfect-fill path.
    if !is_new_bin {
        let fill_after = (bin_residual as f64) / c;
        if fill_after >= 0.85 && fill_after <= 0.97 {
            score -= 2.0 + 2.0 * x;
        } else if fill_after > 0.97 && post_residual > 0 {
            score += 1.5 * (1.0 - x);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = r / c;
    let placed = (bin_residual - post_residual) as f64;

    // Base: superlinear small-post-residual preference, progress-scaled.
    let mut score = p * p * (1.0 + 2.0 * x) + 0.35 * p;

    // Tightness bonus on what was just placed.
    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (8.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect fill: strong reward, escalating late when bins are scarce.
    if post_residual == 0 {
        score -= 55.0 + 10.0 * x;
    } else if post_residual <= 5 {
        score -= 12.0 + 8.0 * x;
    }

    // Early stream: keep bins flexible.
    score += (1.0 - x) * p * (1.0 - p) * 3.0;

    // Dead-space penalty (quadratic in usable-space loss).
    let dead = (p * (1.0 - p * 4.0)).max(0.0);
    score += dead * (2.0 + 3.0 * x) + 2.5 * dead * dead * (1.0 + x);
    if post_residual > 0 {
        let min_live = (next_item_size.max(1) as f64).min(20.0);
        if r > 0.0 && r < min_live {
            score += 3.0 * (1.0 - r / min_live) * (1.0 + x);
        }
    }

    // Tiny unrescuable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + 4.0 * x;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Fragmentation guard.
    if post_residual > 0 && post_residual < bin_capacity / 5 && x < 0.85 {
        score += 4.0;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if x > 0.5 {
            score -= 10.0 * x;
        }
    }

    // Lookahead with snugness, chaining, and two-step chain depth.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r == n {
            score -= 40.0 + 5.0 * x;
        } else if n <= r {
            let snug = 1.0 - (r - n) / c;
            score -= 10.0 * snug;
            if r >= 2.0 * n {
                score -= 4.0;
            }
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                score += 5.0;
            } else if after >= n {
                score -= 3.0;
            }
            let chain_count = (r / n).floor();
            if chain_count >= 2.0 {
                score -= 2.0 * chain_count.min(4.0);
            }
            if after > 0.0 && after < n * 0.5 && after < 25.0 {
                score += 4.0 + 3.0 * x;
            }
            if after > 0.0 && after < n * 0.1 {
                score += 3.0 + 3.0 * x;
            }
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 2 {
                score -= 5.0 + 4.0 * x;
            }
            if after > 0.0 && (after * 2.0) >= n && after < n {
                score -= 2.0 + 2.0 * x;
            }
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 3 {
                score -= 3.0 + 3.0 * x;
            }
        } else {
            let waste = (n - r) / n;
            score += 15.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 8.0;
            }
            if r > 0.0 && r < 20.0 {
                score += 3.0 * (1.0 - r / 20.0);
            }
            if r > 0.0 {
                score += 5.0 * waste * (1.0 - x);
            }
            if r > 0.0 {
                let gap = n - r;
                if gap < 8.0 {
                    score += 4.0 * (1.0 - gap / 8.0) * (0.5 + x);
                }
            }
        }
    }

    // Mean-residual coupling.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.08 * dev;
    } else {
        score += 0.05 * (-dev) * (item_size as f64 / c);
    }

    // New-bin candidate handling with adaptive escape valves.
    let is_new_bin = bin_residual == bin_capacity;
    let fresh_left = c - item_size as f64;
    if is_new_bin {
        let mut penalty = 35.0;
        if next_item_size > 0 && r > next_item_size as f64 + 30.0 {
            penalty -= 12.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 10.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 15.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        penalty -= 8.0 * x;
        if fitting_bins_count > 0 && open_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n * 0.5 {
                penalty -= 6.0 + 6.0 * (1.0 - r / n);
            }
        }
        if item_size as f64 >= 0.7 * c && x < 0.4 {
            penalty -= 6.0;
        }
        if fitting_bins_count > 0 && post_residual > 0 && post_residual < 12 && open_bins_count > 1 {
            penalty -= 9.0;
        }
        if fitting_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < 0.15 * c && open_bins_count > 2 {
                penalty -= 5.0 + 3.0 * x;
            }
        }
        if open_bins_count > 4 && mean_residual > 0.5 * c {
            penalty -= 4.0;
        }
        if next_item_size > 0 && open_bins_count > 0 {
            let n = next_item_size as f64;
            if r < n && n > 0.6 * c {
                penalty -= 7.0 + 5.0 * x;
            }
        }
        if x > 0.8 && item_size as f64 > 0.5 * c {
            penalty -= 5.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 1 && r > 0.6 * c && mean_residual < 0.35 * c {
            penalty -= 8.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < mean_residual * 0.5 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        penalty += 10.0 * x * x;
        if x > 0.95 && open_bins_count > 1 {
            penalty -= 4.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 {
            let n = next_item_size as f64;
            if r < n && r < 0.2 * c {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n && fresh_left >= n {
                penalty -= 6.0 + 6.0 * x;
            }
            if fresh_left > 0.6 * c && r < 0.1 * c && open_bins_count > 0 {
                penalty -= 5.0;
            }
            if fresh_left >= n && fresh_left % n.max(1.0) < 1.0 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        if item_size as f64 > 0.55 * c && x < 0.25 && open_bins_count > 2 {
            penalty -= 5.0;
        }
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 3.0 + 3.0 * x;
        }
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        // Waste-budget lookahead.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if fresh_left > 0.0 && fresh_left < n {
                penalty += 8.0 + 6.0 * x;
            }
            if fresh_left >= n && fresh_left < n * 1.5 {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        if x > 0.3 && x < 0.85 && open_bins_count > 6 && mean_residual > 0.3 * c {
            penalty += 3.0 + 3.0 * (open_bins_count as f64 - 6.0).min(6.0);
        }
        if fitting_bins_count > 0 && next_item_size > 1 {
            let n = next_item_size as f64;
            if fresh_left >= n && (fresh_left as u32) % next_item_size == 0 {
                penalty -= 3.0 + 3.0 * x;
            }
        }
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        if fitting_bins_count > 0 {
            let best_use = 1.0 - (r / c).min(1.0);
            penalty += 14.0 * best_use * (0.4 + x);
        }
        if next_item_size > 0 && fitting_bins_count > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let after_f = fresh_left - n;
                if after_f > 0.0 && after_f < 20.0 && after_f < n {
                    penalty += (1.0 - after_f / 20.0) * (3.0 + 3.0 * x);
                } else if after_f == 0.0 {
                    penalty -= 4.0 + 3.0 * x;
                }
            }
        }
        // MUTATION (gen 38): strand-vs-sprawl trade — dilute fresh-bin
        // sliver cost across open-bin sprawl, reward near-exact divisibility
        // of the fresh leftover with the next item.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let sprawl_f = (open_bins_count as f64).max(1.0);
            if fresh_left > 0.0 && fresh_left < n {
                penalty += (1.0 - fresh_left / n) * (4.0 + 2.0 * x) * (2.0 / sprawl_f).min(2.0);
            } else if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let l = fresh_left - copies * n;
                if l > 0.0 && l < n * 0.2 && copies >= 2.0 {
                    penalty -= (1.0 - l / (n * 0.2)) * 3.0 * (1.0 + x) * (sprawl_f / (sprawl_f + 3.0));
                }
            }
        }
        // MUTATION (gen 38): direct strand comparison — when open-bin
        // post-residual is dead (below next item) but the fresh leftover
        // would absorb multiple next-item copies, opening fresh is cheap.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if r > 0.0 && r < n && fresh_left >= n {
                let copies = (fresh_left / n).floor();
                if copies >= 2.0 {
                    penalty -= 7.0 + 5.0 * x;
                }
            }
        }
        // MUTATION (gen 38): late-stream surge on wasteful fresh bins.
        if x > 0.7 && fresh_left > 0.5 * c {
            penalty += (fresh_left / c - 0.5) * 18.0 * (x - 0.7) / 0.3;
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio shaping.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n {
            let dead_frac = (n - r) / n;
            score += dead_frac * dead_frac * (3.0 + 4.0 * x);
        }
    }

    // Live-residual yield.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= 2.0 * n {
            score -= (1.5 + 2.5 * x) * (r / c);
        } else if r >= n {
            score -= 0.5 + 1.0 * x;
        }
    }

    // Residual-efficiency gradient among fitting bins.
    if !is_new_bin && fitting_bins_count > 2 && post_residual > 0 {
        let cohort = mean_residual.max(1.0);
        let rel = (r - cohort) / c;
        let depth = (fitting_bins_count as f64).min(6.0) / 6.0;
        if rel < 0.0 {
            score -= ((rel * -60.0) * (0.6 + 0.6 * depth)).min(3.5) * (0.5 + x);
        } else {
            score += ((rel * 40.0) * (0.6 + 0.6 * depth)).min(1.8) * (0.5 + x);
        }
    }

    // MUTATION (gen 38): cohort-relative snugness sweep — among fitting bins,
    // prefer post-residuals near n/2 (likely next-next fit) or near zero;
    // penalize dead-zone residuals just below n.
    if !is_new_bin && fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 {
        let n = next_item_size.max(1) as f64;
        let half_n = n * 0.5;
        if r >= half_n {
            let closeness = 1.0 - ((r - half_n) / (c - half_n)).min(1.0);
            score -= 1.6 * closeness * closeness * (0.4 + x);
        } else {
            score += 1.2 * (1.0 - r / half_n) * (0.5 + x);
        }
    }

    // MUTATION (gen 38): second-level dead-space probe — residuals that
    // after absorbing the next item strand a tiny odd sliver get penalized;
    // clean two-item chains get rewarded.
    if !is_new_bin && next_item_size > 0 && r >= next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after = r - n;
        if after > 0.0 && after < 15.0 {
            score += (1.0 + x) * (1.0 - after / 15.0) * 2.0;
        } else if after >= 15.0 && after < 30.0 {
            score -= 0.8 * (1.0 - x);
        }
        if after > 0.0 && (after % 10.0) == 0.0 {
            score -= 1.2 + 1.2 * x;
        }
    }

    // MUTATION (gen 38): third-level chain probe — exact two-copy fills
    // with nothing left over are compaction goldmines.
    if !is_new_bin && next_item_size > 0 && r >= 2.0 * next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after2 = r - 2.0 * n;
        if after2 == 0.0 {
            score -= 3.0 + 3.0 * x;
        } else if after2 > 0.0 && after2 < 4.0 {
            score -= 1.5 + 1.5 * x;
        } else if after2 > 0.0 && after2 < n * 0.4 {
            score += 1.5 * (0.5 + x);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = r / c;
    let placed = (bin_residual - post_residual) as f64;

    // Base: superlinear small-post-residual preference, progress-scaled.
    let mut score = p * p * (1.0 + 2.0 * x) + 0.35 * p;

    // Tightness bonus on what was just placed.
    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (8.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect fill: strong reward, escalating late when bins are scarce.
    if post_residual == 0 {
        score -= 55.0 + 10.0 * x;
    } else if post_residual <= 5 {
        score -= 12.0 + 8.0 * x;
    }

    // Early stream: keep bins flexible.
    score += (1.0 - x) * p * (1.0 - p) * 3.0;

    // Dead-space penalty (quadratic in usable-space loss).
    let dead = (p * (1.0 - p * 4.0)).max(0.0);
    score += dead * (2.0 + 3.0 * x) + 2.5 * dead * dead * (1.0 + x);
    if post_residual > 0 {
        let min_live = (next_item_size.max(1) as f64).min(20.0);
        if r > 0.0 && r < min_live {
            score += 3.0 * (1.0 - r / min_live) * (1.0 + x);
        }
    }

    // Tiny unrescuable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + 4.0 * x;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Fragmentation guard.
    if post_residual > 0 && post_residual < bin_capacity / 5 && x < 0.85 {
        score += 4.0;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if x > 0.5 {
            score -= 10.0 * x;
        }
    }

    // Lookahead with snugness, chaining, and two-step chain depth.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r == n {
            score -= 40.0 + 5.0 * x;
        } else if n <= r {
            let snug = 1.0 - (r - n) / c;
            score -= 10.0 * snug;
            if r >= 2.0 * n {
                score -= 4.0;
            }
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                score += 5.0;
            } else if after >= n {
                score -= 3.0;
            }
            let chain_count = (r / n).floor();
            if chain_count >= 2.0 {
                score -= 2.0 * chain_count.min(4.0);
            }
            if after > 0.0 && after < n * 0.5 && after < 25.0 {
                score += 4.0 + 3.0 * x;
            }
            if after > 0.0 && after < n * 0.1 {
                score += 3.0 + 3.0 * x;
            }
            // Exact divisibility chain — zero-waste fill guarantee.
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 2 {
                score -= 5.0 + 4.0 * x;
            }
            // Two-step chain viability.
            if after > 0.0 && (after * 2.0) >= n && after < n {
                score -= 2.0 + 2.0 * x;
            }
        } else {
            let waste = (n - r) / n;
            score += 15.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 8.0;
            }
            if r > 0.0 && r < 20.0 {
                score += 3.0 * (1.0 - r / 20.0);
            }
            if r > 0.0 {
                score += 5.0 * waste * (1.0 - x);
            }
            if r > 0.0 {
                let gap = n - r;
                if gap < 8.0 {
                    score += 4.0 * (1.0 - gap / 8.0) * (0.5 + x);
                }
            }
        }
    }

    // Mean-residual coupling.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.08 * dev;
    } else {
        score += 0.05 * (-dev) * (item_size as f64 / c);
    }

    // New-bin candidate handling with adaptive escape valves.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut penalty = 35.0;
        if next_item_size > 0 && r > next_item_size as f64 + 30.0 {
            penalty -= 12.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 10.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 15.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        penalty -= 8.0 * x;
        if fitting_bins_count > 0 && open_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n * 0.5 {
                penalty -= 6.0 + 6.0 * (1.0 - r / n);
            }
        }
        if item_size as f64 >= 0.7 * c && x < 0.4 {
            penalty -= 6.0;
        }
        if fitting_bins_count > 0 && post_residual > 0 && post_residual < 12 && open_bins_count > 1 {
            penalty -= 9.0;
        }
        if fitting_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < 0.15 * c && open_bins_count > 2 {
                penalty -= 5.0 + 3.0 * x;
            }
        }
        if open_bins_count > 4 && mean_residual > 0.5 * c {
            penalty -= 4.0;
        }
        if next_item_size > 0 && open_bins_count > 0 {
            let n = next_item_size as f64;
            if r < n && n > 0.6 * c {
                penalty -= 7.0 + 5.0 * x;
            }
        }
        if x > 0.8 && item_size as f64 > 0.5 * c {
            penalty -= 5.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 1 && r > 0.6 * c && mean_residual < 0.35 * c {
            penalty -= 8.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < mean_residual * 0.5 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        penalty += 10.0 * x * x;
        if x > 0.95 && open_bins_count > 1 {
            penalty -= 4.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 {
            let n = next_item_size as f64;
            if r < n && r < 0.2 * c {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        // Compare best achievable post-residual on an open bin against the
        // fresh-bin leftover; prefer the new bin when it strands less waste.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            let fresh_left = c - item_size as f64;
            if r > 0.0 && r < n && fresh_left >= n {
                penalty -= 6.0 + 6.0 * x;
            }
            if fresh_left > 0.6 * c && r < 0.1 * c && open_bins_count > 0 {
                penalty -= 5.0;
            }
            // Fresh-bin residual exactly fits the next item: zero-waste follow-up.
            if fresh_left >= n && fresh_left % n.max(1.0) < 1.0 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        // Large item early on — dedicated bin beats carving a partial one.
        if item_size as f64 > 0.55 * c && x < 0.25 && open_bins_count > 2 {
            penalty -= 5.0;
        }
        // Heavy fragmentation: opening fresh and consolidating is preferable.
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 3.0 + 3.0 * x;
        }
        // When the only fitting bins would leave residual smaller than half
        // the next item, opening fresh is cheap — avoids stranding.
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        // Late stream with large mean residual — squeeze existing bins harder.
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        // Waste-budget coupling — when total stranded residual is small
        // relative to the stream, fresh bins get pricier; when fragmentation
        // is high, they get cheaper. Drives compaction.
        if open_bins_count > 0 {
            let frag = mean_residual / c;
            let sprawl = open_bins_count as f64;
            if frag < 0.3 {
                penalty += (0.3 - frag) * 20.0 * (1.0 - x);
            } else if frag > 0.55 && sprawl > 3.0 {
                penalty -= (frag - 0.55) * 18.0 * (0.5 + x);
            }
        }
        // Near-perfect fresh fill — if the item almost exactly fills a new
        // bin, opening it is nearly free.
        let fresh_left = c - item_size as f64;
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Fresh-bin leftover divisibility sweep — reward when the fresh
        // leftover can absorb several copies of the next item exactly.
        if next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 6.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // Scale fresh-bin cost by how well the best open-bin fit would use
        // space — when open bins fit tightly, fresh bins cost more.
        if fitting_bins_count > 0 {
            let best_use = 1.0 - (r / c).min(1.0);
            penalty += 14.0 * best_use * (0.4 + x);
        }
        // Open-bin fit quality sweep — when the best open-bin post-residual
        // is a tiny unusable sliver, opening fresh becomes much cheaper;
        // when the open-bin leftover is large and reusable, fresh bins get
        // pricier. Directly attacks dead-space waste.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_leftover = c - item_size as f64;
            let fresh_absorbs = fresh_leftover >= n;
            if r > 0.0 && r < n {
                let fresh_strand = if fresh_absorbs {
                    let copies = (fresh_leftover / n).floor();
                    let l = fresh_leftover - copies * n;
                    if l > 0.0 { l } else { 0.0 }
                } else { fresh_leftover };
                if fresh_strand + 2.0 < r {
                    penalty -= 8.0 + 6.0 * x;
                } else if r < fresh_strand {
                    penalty += 4.0 + 4.0 * x;
                }
            }
        }
        // Dead-space budget sweep refinement — widen the trade window so
        // that open-bin residuals just above the next item size are also
        // compared against the fresh-bin strand.
        if fitting_bins_count > 0 && next_item_size > 0 && r >= next_item_size as f64 {
            let n = next_item_size.max(1) as f64;
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                let fresh_leftover = c - item_size as f64;
                let fresh_strand = if fresh_leftover >= n {
                    let copies = (fresh_leftover / n).floor();
                    let l = fresh_leftover - copies * n;
                    if l > 0.0 { l } else { 0.0 }
                } else { fresh_leftover };
                if fresh_strand + 4.0 < after {
                    penalty -= 5.0 + 4.0 * x;
                } else if after < fresh_strand {
                    penalty += 3.0 + 3.0 * x;
                }
            }
        }
        // Three-step fresh-bin viability probe.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_leftover = c - item_size as f64;
            if fresh_leftover < n && r >= 2.0 * n && (r % n) == 0.0 {
                penalty += 6.0 + 5.0 * x;
            }
            let fresh_copies = (fresh_leftover / n).floor();
            let open_copies = (r / n).floor();
            if fresh_copies > open_copies && fresh_copies >= 3.0 && r > 0.0 {
                penalty -= 3.0 + 3.0 * x;
            }
        }
        // Late-stream fresh-bin surge pricing.
        if x > 0.7 {
            let fresh_waste = fresh_left / c;
            if fresh_waste > 0.5 {
                penalty += (fresh_waste - 0.5) * 18.0 * (x - 0.7) / 0.3;
            }
        }
        // Fresh-bin dead-space surcharge — when the fresh leftover after
        // absorbing the next item is a small odd sliver that no typical item
        // (<= 20) can absorb, charge extra; when the fresh leftover is
        // exactly reusable, discount further.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let after_f = fresh_left - n;
                if after_f > 0.0 && after_f < 20.0 && after_f < n {
                    penalty += (1.0 - after_f / 20.0) * (3.0 + 3.0 * x);
                } else if after_f == 0.0 {
                    penalty -= 4.0 + 3.0 * x;
                }
            }
        }
        // Fresh-bin strand-vs-sprawl trade — the cost of opening a fresh bin
        // scales with how much dead space it strands relative to the number
        // of open bins that could absorb it.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let sprawl_f = (open_bins_count as f64).max(1.0);
            if fresh_left > 0.0 && fresh_left < n {
                penalty += (1.0 - fresh_left / n) * (4.0 + 2.0 * x) * (2.0 / sprawl_f).min(2.0);
            } else if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let l = fresh_left - copies * n;
                if l > 0.0 && l < n * 0.2 {
                    penalty -= (1.0 - l / (n * 0.2)) * 3.0 * (1.0 + x) * (sprawl_f / (sprawl_f + 3.0));
                }
            }
        }
        // MUTATION (gen 38): fresh-bin two-item lookahead — a new bin is only
        // worth opening if its leftover after absorbing the current item can
        // plausibly host the next item AND still leave workable space. When
        // the fresh leftover would be a stranded sliver that cannot host the
        // next item, charge a steep penalty; when it can host the next item
        // with room to spare, discount the fresh bin so lookahead-friendly
        // openings win. This targets dead space at the source.
        if fitting_bins_count > 0 && next_item_size > 0 && open_bins_count > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left < n {
                // Fresh bin strands a sliver the next item cannot use.
                penalty += (1.0 - fresh_left / n) * 10.0 * (0.6 + x);
            } else {
                let after_n = fresh_left - n;
                if after_n == 0.0 {
                    penalty -= 8.0 + 4.0 * x;
                } else if after_n >= n * 0.5 {
                    penalty -= 4.0 + 3.0 * x;
                } else if after_n < n * 0.25 {
                    penalty += (1.0 - after_n / (n * 0.25)) * 4.0 * (0.5 + x);
                }
            }
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — reward filling the fullest available bin,
    // scaled by open-bin sprawl.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio pressure.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // Waste-stranding sweep.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        if r < n {
            score += 2.5 * (r / n) * (0.5 + x);
        } else if r < 2.0 * n {
            let after = r - n;
            if after > 0.0 && after < n {
                if after < 5.0 {
                    score += 2.0 * (1.0 - x);
                } else if after >= 5.0 && after < 15.0 {
                    score -= 1.0;
                }
            }
        }
    }

    // Cross-bin tightness gradient.
    if !is_new_bin && fitting_bins_count > 1 {
        let tight = 1.0 - (r / c).min(1.0);
        score -= 1.8 * tight * tight * (1.0 - (2.0 * x - 1.0).abs());
    }

    // Second-level dead-space probe.
    if !is_new_bin && next_item_size > 0 && r >= next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after = r - n;
        if after > 0.0 && after < 15.0 {
            score += (1.0 + x) * (1.0 - after / 15.0) * 2.0;
        } else if after >= 15.0 && after < 30.0 {
            score -= 0.8 * (1.0 - x);
        }
        if after > 0.0 && (after % 10.0) == 0.0 {
            score -= 1.2 + 1.2 * x;
        }
    }

    // Third-level chain probe.
    if !is_new_bin && next_item_size > 0 && r >= 2.0 * next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after2 = r - 2.0 * n;
        if after2 == 0.0 {
            score -= 3.0 + 3.0 * x;
        } else if after2 > 0.0 && after2 < 4.0 {
            score -= 1.5 + 1.5 * x;
        } else if after2 >= n && after2 < n + 4.0 {
            score -= 1.0 * (1.0 - x);
        } else if after2 > 0.0 && after2 < n * 0.4 {
            score += 1.5 * (0.5 + x);
        }
    }

    // Residual-efficiency gradient among fitting bins.
    if !is_new_bin && fitting_bins_count > 2 && post_residual > 0 {
        let cohort = mean_residual.max(1.0);
        let rel = (r - cohort) / c;
        let depth = (fitting_bins_count as f64).min(6.0) / 6.0;
        if rel < 0.0 {
            score -= ((rel * -60.0) * (0.6 + 0.6 * depth)).min(3.5) * (0.5 + x);
        } else {
            score += ((rel * 40.0) * (0.6 + 0.6 * depth)).min(1.8) * (0.5 + x);
        }
    }

    // Cohort-relative snugness sweep.
    if !is_new_bin && fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 {
        let n = next_item_size.max(1) as f64;
        let half_n = n * 0.5;
        if r >= half_n {
            let closeness = 1.0 - ((r - half_n) / (c - half_n)).min(1.0);
            score -= 1.6 * closeness * closeness * (0.4 + x);
        } else {
            score += 1.2 * (1.0 - r / half_n) * (0.5 + x);
        }
    }

    // MUTATION (gen 38): combined two-item capacity probe — estimate whether
    // the current item plus the next item would fill this bin nearly exactly
    // (item + next ≈ residual). Such two-item completions are the strongest
    // anti-dead-space move available, so reward them superlinearly with
    // progress; penalize near-misses that leave a stranded sub-half gap.
    if !is_new_bin && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        let combined = item_size as f64 + n;
        let target = bin_residual as f64;
        if combined <= target {
            let gap = target - combined;
            if gap <= 3.0 {
                score -= (4.0 + 5.0 * x) * (1.0 - gap / 3.0);
            } else if gap < n * 0.5 {
                score += 1.5 * (1.0 - gap / (n * 0.5)) * (0.5 + x);
            }
        } else {
            let overshoot = (combined - target) / n;
            if overshoot < 0.15 {
                score += 2.0 * (1.0 - overshoot / 0.15) * (0.4 + x);
            }
        }
    }

    // MUTATION (gen 38): residual entropy guard — residuals that are neither
    // small (reusable) nor near multiples of common item sizes tend to
    // become permanent dead space. Apply a smooth quadratic penalty on the
    // "awkwardness" of the leftover, weighted by stream progress so late
    // stranded space is punished hardest.
    if !is_new_bin && post_residual > 0 {
        let n = if next_item_size > 0 { next_item_size as f64 } else { 10.0 };
        let unusable = (n - r).min(20.0).max(0.0) / 20.0;
        let oddness = {
            let m = r % 10.0;
            let d = m.min(10.0 - m);
            1.0 - d / 5.0
        };
        score += unusable * oddness * (1.5 + 3.0 * x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = r / c;
    let placed = (bin_residual - post_residual) as f64;

    // Base: superlinear small-post-residual preference, progress-scaled.
    let mut score = p * p * (1.0 + 2.0 * x) + 0.35 * p;

    // Tightness bonus on what was just placed.
    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (8.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect fill: strong reward, escalating late when bins are scarce.
    if post_residual == 0 {
        score -= 55.0 + 10.0 * x;
    } else if post_residual <= 5 {
        score -= 12.0 + 8.0 * x;
    }

    // Early stream: keep bins flexible.
    score += (1.0 - x) * p * (1.0 - p) * 3.0;

    // Dead-space penalty (quadratic in usable-space loss).
    let dead = (p * (1.0 - p * 4.0)).max(0.0);
    score += dead * (2.0 + 3.0 * x) + 2.5 * dead * dead * (1.0 + x);
    if post_residual > 0 {
        let min_live = (next_item_size.max(1) as f64).min(20.0);
        if r > 0.0 && r < min_live {
            score += 3.0 * (1.0 - r / min_live) * (1.0 + x);
        }
    }

    // Tiny unrescuable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + 4.0 * x;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Fragmentation guard.
    if post_residual > 0 && post_residual < bin_capacity / 5 && x < 0.85 {
        score += 4.0;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if x > 0.5 {
            score -= 10.0 * x;
        }
    }

    // Lookahead with snugness, chaining, and two-step chain depth.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r == n {
            score -= 40.0 + 5.0 * x;
        } else if n <= r {
            let snug = 1.0 - (r - n) / c;
            score -= 10.0 * snug;
            if r >= 2.0 * n {
                score -= 4.0;
            }
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                score += 5.0;
            } else if after >= n {
                score -= 3.0;
            }
            let chain_count = (r / n).floor();
            if chain_count >= 2.0 {
                score -= 2.0 * chain_count.min(4.0);
            }
            if after > 0.0 && after < n * 0.5 && after < 25.0 {
                score += 4.0 + 3.0 * x;
            }
            if after > 0.0 && after < n * 0.1 {
                score += 3.0 + 3.0 * x;
            }
            // Exact divisibility chain — zero-waste fill guarantee.
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 2 {
                score -= 5.0 + 4.0 * x;
            }
            // Two-step chain viability.
            if after > 0.0 && (after * 2.0) >= n && after < n {
                score -= 2.0 + 2.0 * x;
            }
        } else {
            let waste = (n - r) / n;
            score += 15.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 8.0;
            }
            if r > 0.0 && r < 20.0 {
                score += 3.0 * (1.0 - r / 20.0);
            }
            if r > 0.0 {
                score += 5.0 * waste * (1.0 - x);
            }
            if r > 0.0 {
                let gap = n - r;
                if gap < 8.0 {
                    score += 4.0 * (1.0 - gap / 8.0) * (0.5 + x);
                }
            }
        }
    }

    // Mean-residual coupling.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.08 * dev;
    } else {
        score += 0.05 * (-dev) * (item_size as f64 / c);
    }

    // New-bin candidate handling with adaptive escape valves.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut penalty = 35.0;
        if next_item_size > 0 && r > next_item_size as f64 + 30.0 {
            penalty -= 12.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 10.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 15.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        penalty -= 8.0 * x;
        if fitting_bins_count > 0 && open_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n * 0.5 {
                penalty -= 6.0 + 6.0 * (1.0 - r / n);
            }
        }
        if item_size as f64 >= 0.7 * c && x < 0.4 {
            penalty -= 6.0;
        }
        if fitting_bins_count > 0 && post_residual > 0 && post_residual < 12 && open_bins_count > 1 {
            penalty -= 9.0;
        }
        if fitting_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < 0.15 * c && open_bins_count > 2 {
                penalty -= 5.0 + 3.0 * x;
            }
        }
        if open_bins_count > 4 && mean_residual > 0.5 * c {
            penalty -= 4.0;
        }
        if next_item_size > 0 && open_bins_count > 0 {
            let n = next_item_size as f64;
            if r < n && n > 0.6 * c {
                penalty -= 7.0 + 5.0 * x;
            }
        }
        if x > 0.8 && item_size as f64 > 0.5 * c {
            penalty -= 5.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 1 && r > 0.6 * c && mean_residual < 0.35 * c {
            penalty -= 8.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < mean_residual * 0.5 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        penalty += 10.0 * x * x;
        if x > 0.95 && open_bins_count > 1 {
            penalty -= 4.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 {
            let n = next_item_size as f64;
            if r < n && r < 0.2 * c {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        // Compare best achievable post-residual on an open bin against the
        // fresh-bin leftover; prefer the new bin when it strands less waste.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            let fresh_left = c - item_size as f64;
            if r > 0.0 && r < n && fresh_left >= n {
                penalty -= 6.0 + 6.0 * x;
            }
            if fresh_left > 0.6 * c && r < 0.1 * c && open_bins_count > 0 {
                penalty -= 5.0;
            }
            // Fresh-bin residual exactly fits the next item: zero-waste follow-up.
            if fresh_left >= n && fresh_left % n.max(1.0) < 1.0 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        // Large item early on — dedicated bin beats carving a partial one.
        if item_size as f64 > 0.55 * c && x < 0.25 && open_bins_count > 2 {
            penalty -= 5.0;
        }
        // Heavy fragmentation: opening fresh and consolidating is preferable.
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 3.0 + 3.0 * x;
        }
        // When the only fitting bins would leave residual smaller than half
        // the next item, opening fresh is cheap — avoids stranding.
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        // Late stream with large mean residual — squeeze existing bins harder.
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        // Waste-budget coupling.
        if open_bins_count > 0 {
            let frag = mean_residual / c;
            let sprawl = open_bins_count as f64;
            if frag < 0.3 {
                penalty += (0.3 - frag) * 20.0 * (1.0 - x);
            } else if frag > 0.55 && sprawl > 3.0 {
                penalty -= (frag - 0.55) * 18.0 * (0.5 + x);
            }
        }
        // Near-perfect fresh fill.
        let fresh_left = c - item_size as f64;
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Fresh-bin leftover divisibility sweep.
        if next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let leftover = fresh_left - copies * n;
                if leftover == 0.0 && copies >= 2.0 {
                    penalty -= 6.0 + 3.0 * copies.min(4.0) * x;
                } else if leftover < n * 0.15 && copies >= 1.0 {
                    penalty -= 2.0 + 2.0 * x;
                }
            }
        }
        // Scale fresh-bin cost by best open-bin fit usage.
        if fitting_bins_count > 0 {
            let best_use = 1.0 - (r / c).min(1.0);
            penalty += 14.0 * best_use * (0.4 + x);
        }
        // Open-bin fit quality sweep.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_leftover = c - item_size as f64;
            let fresh_absorbs = fresh_leftover >= n;
            if r > 0.0 && r < n {
                let fresh_strand = if fresh_absorbs {
                    let copies = (fresh_leftover / n).floor();
                    let l = fresh_leftover - copies * n;
                    if l > 0.0 { l } else { 0.0 }
                } else { fresh_leftover };
                if fresh_strand + 2.0 < r {
                    penalty -= 8.0 + 6.0 * x;
                } else if r < fresh_strand {
                    penalty += 4.0 + 4.0 * x;
                }
            }
        }
        // Dead-space budget sweep refinement.
        if fitting_bins_count > 0 && next_item_size > 0 && r >= next_item_size as f64 {
            let n = next_item_size.max(1) as f64;
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                let fresh_leftover = c - item_size as f64;
                let fresh_strand = if fresh_leftover >= n {
                    let copies = (fresh_leftover / n).floor();
                    let l = fresh_leftover - copies * n;
                    if l > 0.0 { l } else { 0.0 }
                } else { fresh_leftover };
                if fresh_strand + 4.0 < after {
                    penalty -= 5.0 + 4.0 * x;
                } else if after < fresh_strand {
                    penalty += 3.0 + 3.0 * x;
                }
            }
        }
        // Three-step fresh-bin viability probe.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_leftover = c - item_size as f64;
            if fresh_leftover < n && r >= 2.0 * n && (r % n) == 0.0 {
                penalty += 6.0 + 5.0 * x;
            }
            let fresh_copies = (fresh_leftover / n).floor();
            let open_copies = (r / n).floor();
            if fresh_copies > open_copies && fresh_copies >= 3.0 && r > 0.0 {
                penalty -= 3.0 + 3.0 * x;
            }
        }
        // Late-stream fresh-bin surge pricing.
        if x > 0.7 {
            let fresh_waste = fresh_left / c;
            if fresh_waste > 0.5 {
                penalty += (fresh_waste - 0.5) * 18.0 * (x - 0.7) / 0.3;
            }
        }
        // Fresh-bin dead-space surcharge.
        if next_item_size > 0 && fitting_bins_count > 0 {
            let n = next_item_size.max(1) as f64;
            if fresh_left >= n {
                let after_f = fresh_left - n;
                if after_f > 0.0 && after_f < 20.0 && after_f < n {
                    penalty += (1.0 - after_f / 20.0) * (3.0 + 3.0 * x);
                } else if after_f == 0.0 {
                    penalty -= 4.0 + 3.0 * x;
                }
            }
        }
        // Fresh-bin strand-vs-sprawl trade.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let sprawl_f = (open_bins_count as f64).max(1.0);
            if fresh_left > 0.0 && fresh_left < n {
                penalty += (1.0 - fresh_left / n) * (4.0 + 2.0 * x) * (2.0 / sprawl_f).min(2.0);
            } else if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                let l = fresh_left - copies * n;
                if l > 0.0 && l < n * 0.2 {
                    penalty -= (1.0 - l / (n * 0.2)) * 3.0 * (1.0 + x) * (sprawl_f / (sprawl_f + 3.0));
                }
            }
        }
        // MUTATION (gen 38): fresh-bin total-waste ledger — compare the
        // fresh bin's projected dead space (leftover after absorbing copies
        // of the next item) against the open-bin candidate's projected dead
        // space (post_residual after absorbing copies of the next item).
        // Whichever strands less absolute waste should be favored; the
        // comparison is progress-scaled so late-stream compaction dominates.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_dead = if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                fresh_left - copies * n
            } else { fresh_left };
            let open_dead = if r >= n {
                let copies = (r / n).floor();
                r - copies * n
            } else { r };
            let delta = fresh_dead - open_dead;
            if delta < -1.0 {
                penalty -= (delta.abs() * 0.7).min(9.0) * (0.5 + x);
            } else if delta > 1.0 {
                penalty += (delta * 0.7).min(9.0) * (0.5 + x);
            }
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio pressure.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // Waste-stranding sweep.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        if r < n {
            score += 2.5 * (r / n) * (0.5 + x);
        } else if r < 2.0 * n {
            let after = r - n;
            if after > 0.0 && after < n {
                if after < 5.0 {
                    score += 2.0 * (1.0 - x);
                } else if after >= 5.0 && after < 15.0 {
                    score -= 1.0;
                }
            }
        }
    }

    // Cross-bin tightness gradient.
    if !is_new_bin && fitting_bins_count > 1 {
        let tight = 1.0 - (r / c).min(1.0);
        score -= 1.8 * tight * tight * (1.0 - (2.0 * x - 1.0).abs());
    }

    // Second-level dead-space probe.
    if !is_new_bin && next_item_size > 0 && r >= next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after = r - n;
        if after > 0.0 && after < 15.0 {
            score += (1.0 + x) * (1.0 - after / 15.0) * 2.0;
        } else if after >= 15.0 && after < 30.0 {
            score -= 0.8 * (1.0 - x);
        }
        if after > 0.0 && (after % 10.0) == 0.0 {
            score -= 1.2 + 1.2 * x;
        }
    }

    // Third-level chain probe.
    if !is_new_bin && next_item_size > 0 && r >= 2.0 * next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after2 = r - 2.0 * n;
        if after2 == 0.0 {
            score -= 3.0 + 3.0 * x;
        } else if after2 > 0.0 && after2 < 4.0 {
            score -= 1.5 + 1.5 * x;
        } else if after2 >= n && after2 < n + 4.0 {
            score -= 1.0 * (1.0 - x);
        } else if after2 > 0.0 && after2 < n * 0.4 {
            score += 1.5 * (0.5 + x);
        }
    }

    // Residual-efficiency gradient among fitting bins (gen 38: cap raised
    // on the reward side to discriminate tighter fits more strongly).
    if !is_new_bin && fitting_bins_count > 2 && post_residual > 0 {
        let cohort = mean_residual.max(1.0);
        let rel = (r - cohort) / c;
        let depth = (fitting_bins_count as f64).min(6.0) / 6.0;
        if rel < 0.0 {
            score -= ((rel * -60.0) * (0.6 + 0.6 * depth)).min(4.0) * (0.5 + x);
        } else {
            score += ((rel * 40.0) * (0.6 + 0.6 * depth)).min(2.2) * (0.5 + x);
        }
    }

    // Cohort-relative snugness sweep.
    if !is_new_bin && fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 {
        let n = next_item_size.max(1) as f64;
        let half_n = n * 0.5;
        if r >= half_n {
            let closeness = 1.0 - ((r - half_n) / (c - half_n)).min(1.0);
            score -= 1.6 * closeness * closeness * (0.4 + x);
        } else {
            score += 1.2 * (1.0 - r / half_n) * (0.5 + x);
        }
    }

    // MUTATION (gen 38): multi-copy exact-fill ledger — when the post
    // residual absorbs k >= 2 copies of the next item with zero leftover,
    // reward proportionally to k (guarantees zero dead space for k steps);
    // when the leftover after max absorption is a sliver smaller than 3,
    // penalize mildly since it is nearly unrescuable regardless of size.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 {
        let n = next_item_size.max(1) as f64;
        if r >= n {
            let copies = (r / n).floor();
            let leftover = r - copies * n;
            if leftover == 0.0 && copies >= 2.0 {
                score -= (2.0 + copies.min(5.0)) * (0.6 + 0.6 * x);
            } else if leftover > 0.0 && leftover < 3.0 {
                score += 1.5 + 1.5 * x;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = r / c;
    let placed = (bin_residual - post_residual) as f64;

    // Base: superlinear small-post-residual preference, progress-scaled.
    let mut score = p * p * (1.0 + 2.0 * x) + 0.35 * p;

    // Tightness bonus on what was just placed.
    let tightness = placed / bin_residual.max(1) as f64;
    let fill_ratio = placed / c;
    score -= (8.0 + 4.0 * fill_ratio) * tightness * tightness;

    // Perfect fill: strong reward, escalating late when bins are scarce.
    if post_residual == 0 {
        score -= 55.0 + 10.0 * x;
    } else if post_residual <= 5 {
        score -= 12.0 + 8.0 * x;
    }

    // Early stream: keep bins flexible.
    score += (1.0 - x) * p * (1.0 - p) * 3.0;

    // Dead-space penalty (quadratic in usable-space loss).
    let dead = (p * (1.0 - p * 4.0)).max(0.0);
    score += dead * (2.0 + 3.0 * x) + 2.5 * dead * dead * (1.0 + x);
    if post_residual > 0 {
        let min_live = (next_item_size.max(1) as f64).min(20.0);
        if r > 0.0 && r < min_live {
            score += 3.0 * (1.0 - r / min_live) * (1.0 + x);
        }
    }

    // Tiny unrescuable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + 4.0 * x;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Fragmentation guard.
    if post_residual > 0 && post_residual < bin_capacity / 5 && x < 0.85 {
        score += 4.0;
    }

    // Last-chance bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if x > 0.5 {
            score -= 10.0 * x;
        }
    }

    // Lookahead with snugness, chaining, and two-step chain depth.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r == n {
            score -= 40.0 + 5.0 * x;
        } else if n <= r {
            let snug = 1.0 - (r - n) / c;
            score -= 10.0 * snug;
            if r >= 2.0 * n {
                score -= 4.0;
            }
            let after = r - n;
            if after > 0.0 && after < n * 0.5 {
                score += 5.0;
            } else if after >= n {
                score -= 3.0;
            }
            let chain_count = (r / n).floor();
            if chain_count >= 2.0 {
                score -= 2.0 * chain_count.min(4.0);
            }
            if after > 0.0 && after < n * 0.5 && after < 25.0 {
                score += 4.0 + 3.0 * x;
            }
            if after > 0.0 && after < n * 0.1 {
                score += 3.0 + 3.0 * x;
            }
            // Exact divisibility chain — zero-waste fill guarantee.
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 2 {
                score -= 5.0 + 4.0 * x;
            }
            // Two-step chain viability.
            if after > 0.0 && (after * 2.0) >= n && after < n {
                score -= 2.0 + 2.0 * x;
            }
            // Harmonic chain — residual divisible by next item with room
            // for at least three copies is a compaction goldmine.
            if post_residual % next_item_size == 0 && post_residual >= next_item_size * 3 {
                score -= 3.0 + 3.0 * x;
            }
        } else {
            let waste = (n - r) / n;
            score += 15.0 * waste;
            if post_residual < next_item_size / 2 {
                score += 8.0;
            }
            if r > 0.0 && r < 20.0 {
                score += 3.0 * (1.0 - r / 20.0);
            }
            if r > 0.0 {
                score += 5.0 * waste * (1.0 - x);
            }
            if r > 0.0 {
                let gap = n - r;
                if gap < 8.0 {
                    score += 4.0 * (1.0 - gap / 8.0) * (0.5 + x);
                }
            }
        }
    }

    // Mean-residual coupling.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.08 * dev;
    } else {
        score += 0.05 * (-dev) * (item_size as f64 / c);
    }

    // New-bin candidate handling with adaptive escape valves.
    let is_new_bin = bin_residual == bin_capacity;
    let fresh_left = c - item_size as f64;
    if is_new_bin {
        let mut penalty = 35.0;
        if next_item_size > 0 && r > next_item_size as f64 + 30.0 {
            penalty -= 12.0;
        }
        if item_size as f64 > mean_residual * 0.9 {
            penalty -= 10.0;
        }
        if item_size as f64 >= 0.95 * c {
            penalty -= 15.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        penalty -= 8.0 * x;
        if fitting_bins_count > 0 && open_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n * 0.5 {
                penalty -= 6.0 + 6.0 * (1.0 - r / n);
            }
        }
        if item_size as f64 >= 0.7 * c && x < 0.4 {
            penalty -= 6.0;
        }
        if fitting_bins_count > 0 && post_residual > 0 && post_residual < 12 && open_bins_count > 1 {
            penalty -= 9.0;
        }
        if fitting_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < 0.15 * c && open_bins_count > 2 {
                penalty -= 5.0 + 3.0 * x;
            }
        }
        if open_bins_count > 4 && mean_residual > 0.5 * c {
            penalty -= 4.0;
        }
        if next_item_size > 0 && open_bins_count > 0 {
            let n = next_item_size as f64;
            if r < n && n > 0.6 * c {
                penalty -= 7.0 + 5.0 * x;
            }
        }
        if x > 0.8 && item_size as f64 > 0.5 * c {
            penalty -= 5.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 1 && r > 0.6 * c && mean_residual < 0.35 * c {
            penalty -= 8.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < mean_residual * 0.5 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        penalty += 10.0 * x * x;
        if x > 0.95 && open_bins_count > 1 {
            penalty -= 4.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 {
            let n = next_item_size as f64;
            if r < n && r < 0.2 * c {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        // Compare best achievable post-residual on an open bin against the
        // fresh-bin leftover; prefer the new bin when it strands less waste.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if r > 0.0 && r < n && fresh_left >= n {
                penalty -= 6.0 + 6.0 * x;
            }
            if fresh_left > 0.6 * c && r < 0.1 * c && open_bins_count > 0 {
                penalty -= 5.0;
            }
            // Fresh-bin residual exactly fits the next item: zero-waste follow-up.
            if fresh_left >= n && fresh_left % n.max(1.0) < 1.0 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        // Large item early on — dedicated bin beats carving a partial one.
        if item_size as f64 > 0.55 * c && x < 0.25 && open_bins_count > 2 {
            penalty -= 5.0;
        }
        // Heavy fragmentation: opening fresh and consolidating is preferable.
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 3.0 + 3.0 * x;
        }
        // Only fitting bin would strand less than half the next item — open fresh.
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        // Late stream with large mean residual — squeeze existing bins harder.
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        // Waste-budget lookahead: penalize fresh bins stranding an unfillable
        // sliver; reward snug two-item horizons.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            if fresh_left > 0.0 && fresh_left < n {
                penalty += 8.0 + 6.0 * x;
            }
            if fresh_left >= n && fresh_left < n * 1.5 {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        // Mid-stream sprawl control.
        if x > 0.3 && x < 0.85 && open_bins_count > 6 && mean_residual > 0.3 * c {
            penalty += 3.0 + 3.0 * (open_bins_count as f64 - 6.0).min(6.0);
        }
        // Fresh-bin leftover divisibility — zero-waste chain guaranteed.
        if fitting_bins_count > 0 && next_item_size > 1 {
            let n = next_item_size as f64;
            if fresh_left >= n && (fresh_left as u32) % next_item_size == 0 {
                penalty -= 3.0 + 3.0 * x;
            }
        }
        // Near-perfect fresh fill.
        if fresh_left <= 5.0 {
            penalty -= 10.0;
        } else if fresh_left < 0.08 * c {
            penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
        }
        // Scale fresh-bin cost by best open-bin fit usage.
        if fitting_bins_count > 0 {
            let best_use = 1.0 - (r / c).min(1.0);
            penalty += 14.0 * best_use * (0.4 + x);
        }
        // MUTATION (gen 38): fresh-bin total-waste ledger — compare projected
        // dead space of the fresh bin (leftover after absorbing copies of the
        // next item) against the open-bin candidate's projected dead space.
        // Whichever strands less absolute waste is favored, progress-scaled.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_dead = if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                fresh_left - copies * n
            } else { fresh_left };
            let open_dead = if r >= n {
                let copies = (r / n).floor();
                r - copies * n
            } else { r };
            let delta = fresh_dead - open_dead;
            if delta < -1.0 {
                penalty -= (delta.abs() * 0.7).min(9.0) * (0.5 + x);
            } else if delta > 1.0 {
                penalty += (delta * 0.7).min(9.0) * (0.5 + x);
            }
        }
        // MUTATION (gen 38): late-stream fresh-waste surge — as the stream
        // nears its end, opening a bin whose leftover can never be filled
        // wastes capacity permanently; price that waste sharply.
        if x > 0.7 && fresh_left > 0.5 * c {
            penalty += (fresh_left / c - 0.5) * 20.0 * (x - 0.7) / 0.3;
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — mildly reward filling the fullest bin.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio pressure.
    if !is_new_bin && post_residual > 0 {
        let dp = (r / c).min(1.0);
        let awkward = (dp - (dp * 2.0).round() * 0.5).abs();
        score += 2.0 * awkward * (1.0 - (2.0 * x - 1.0).abs().max(0.0));
    }

    // Residual-absorbability term.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let after = r - n;
            if after == 0.0 {
                score -= 2.0 + 2.0 * x;
            } else if after >= n * 0.5 {
                score -= 1.5 * (1.0 - after / c) * (1.0 + 0.5 * x);
            }
        }
    }

    // Waste-stranding sweep.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        if r < n {
            score += 2.5 * (r / n) * (0.5 + x);
        } else if r < 2.0 * n {
            let after = r - n;
            if after > 0.0 && after < n {
                if after < 5.0 {
                    score += 2.0 * (1.0 - x);
                } else if after < 15.0 {
                    score -= 1.0;
                }
            }
        }
    }

    // Cross-bin tightness gradient.
    if !is_new_bin && fitting_bins_count > 1 {
        let tight = 1.0 - (r / c).min(1.0);
        score -= 1.8 * tight * tight * (1.0 - (2.0 * x - 1.0).abs());
    }

    // Second-level dead-space probe.
    if !is_new_bin && next_item_size > 0 && r >= next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after = r - n;
        if after > 0.0 && after < 15.0 {
            score += (1.0 + x) * (1.0 - after / 15.0) * 2.0;
        } else if after >= 15.0 && after < 30.0 {
            score -= 0.8 * (1.0 - x);
        }
        if after > 0.0 && (after % 10.0) == 0.0 {
            score -= 1.2 + 1.2 * x;
        }
    }

    // Third-level chain probe.
    if !is_new_bin && next_item_size > 0 && r >= 2.0 * next_item_size as f64 {
        let n = next_item_size.max(1) as f64;
        let after2 = r - 2.0 * n;
        if after2 == 0.0 {
            score -= 3.0 + 3.0 * x;
        } else if after2 > 0.0 && after2 < 4.0 {
            score -= 1.5 + 1.5 * x;
        } else if after2 >= n && after2 < n + 4.0 {
            score -= 1.0 * (1.0 - x);
        } else if after2 > 0.0 && after2 < n * 0.4 {
            score += 1.5 * (0.5 + x);
        }
    }

    // Residual-efficiency gradient among fitting bins.
    if !is_new_bin && fitting_bins_count > 2 && post_residual > 0 {
        let cohort = mean_residual.max(1.0);
        let rel = (r - cohort) / c;
        let depth = (fitting_bins_count as f64).min(6.0) / 6.0;
        if rel < 0.0 {
            score -= ((rel * -60.0) * (0.6 + 0.6 * depth)).min(4.0) * (0.5 + x);
        } else {
            score += ((rel * 40.0) * (0.6 + 0.6 * depth)).min(2.2) * (0.5 + x);
        }
    }

    // Cohort-relative snugness sweep.
    if !is_new_bin && fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 {
        let n = next_item_size.max(1) as f64;
        let half_n = n * 0.5;
        if r >= half_n {
            let closeness = 1.0 - ((r - half_n) / (c - half_n)).min(1.0);
            score -= 1.6 * closeness * closeness * (0.4 + x);
        } else {
            score += 1.2 * (1.0 - r / half_n) * (0.5 + x);
        }
    }

    // Multi-copy exact-fill ledger — reward k >= 2 zero-leftover absorption
    // horizons; penalize near-unrescuable slivers under 3 units.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 {
        let n = next_item_size.max(1) as f64;
        if r >= n {
            let copies = (r / n).floor();
            let leftover = r - copies * n;
            if leftover == 0.0 && copies >= 2.0 {
                score -= (2.0 + copies.min(5.0)) * (0.6 + 0.6 * x);
            } else if leftover > 0.0 && leftover < 3.0 {
                score += 1.5 + 1.5 * x;
            }
        }
    }

    // MUTATION (gen 38): live-residual yield — reward placements whose
    // post-residual can still hold the next item with room for a second
    // copy (viable two-step horizon), scaled by stream progress.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 {
        let n = next_item_size.max(1) as f64;
        if r >= 2.0 * n {
            score -= (1.5 + 2.5 * x) * (r / c);
        } else if r >= n {
            score -= 0.5 + 1.0 * x;
        }
    }

    score
}

