    // Global compaction pressure — reward filling the fullest bin.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio shaping — penalize residuals below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n {
            let dead_frac = (n - r) / n;
            score += dead_frac * dead_frac * (3.0 + 4.0 * x);
        }
    }

    // Live-space preservation among several fitting bins.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
        let n = next_item_size as f64;
        if r < n && r < 15.0 {
            score += 4.0 + 3.0 * x;
        }
    }

    // Among multiple fitting bins, discriminate on closeness of post-residual
    // to the next item size.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 1 {
        let n = next_item_size as f64;
        if r >= n {
            let snug = 1.0 - (r - n) / n;
            score -= 2.5 * snug * (0.5 + x);
        } else {
            let frac = r / n;
            score += 2.0 * frac * (1.0 + x);
        }
    }

    // MUTATION (gen 39): multi-copy exact-fill ledger — when the post
    // residual absorbs k >= 2 copies of the next item with zero leftover,
    // reward proportionally to k; nearly unrescuable slivers below 3 are
    // penalized mildly.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 {
        let n = next_item_size.max(1) as f64;
        if r >= n {
            let copies = (r / n).floor();
            let leftover = r - copies * n;
            if leftover == 0.0 && copies >= 2.0 {
                score -= (2.0 + copies.min(5.0)) * (0.6 + 0.6 * x);
            } else if leftover > 0.0 && leftover < 3.0 {
                score += 1.5 + 1.5 * x;
            }
        }
    }

    // MUTATION (gen 39): residual-efficiency gradient among fitting bins —
    // reward bins whose post-residual is tighter than the cohort mean and
    // penalize looser ones, scaled by fitting cohort depth and progress.
    if !is_new_bin && fitting_bins_count > 2 && post_residual > 0 {
        let cohort = mean_residual.max(1.0);
        let rel = (r - cohort) / c;
        let depth = (fitting_bins_count as f64).min(6.0) / 6.0;
        if rel < 0.0 {
            score -= ((rel * -60.0) * (0.6 + 0.6 * depth)).min(4.0) * (0.5 + x);
        } else {
            score += ((rel * 40.0) * (0.6 + 0.6 * depth)).min(2.2) * (0.5 + x);
        }
    }

