        // Mid-stream sprawl control.
        if x > 0.3 && x < 0.85 && open_bins_count > 6 && mean_residual > 0.3 * c {
            penalty += 3.0 + 3.0 * (open_bins_count as f64 - 6.0).min(6.0);
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    score -= 6.0 * x * (1.0 - p);

    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio shaping.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n {
            let dead_frac = (n - r) / n;
            score += dead_frac * dead_frac * (3.0 + 4.0 * x);
        }
    }

    // Live-residual yield.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= 2.0 * n {
            score -= (1.5 + 2.5 * x) * (r / c);
        } else if r >= n {
            score -= 0.5 + 1.0 * x;
        }
    }

    // Multi-copy exact-fill ledger: post residual absorbs k >= 2 copies of
    // the next item with zero leftover — reward proportional to k; a sliver
    // leftover smaller than 3 is nearly unrescuable — penalize.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 {
        let n = next_item_size.max(1) as f64;
        if r >= n {
            let copies = (r / n).floor();
            let leftover = r - copies * n;
            if leftover == 0.0 && copies >= 2.0 {
                score -= (2.0 + copies.min(5.0)) * (0.6 + 0.6 * x);
            } else if leftover > 0.0 && leftover < 3.0 {
                score += 1.5 + 1.5 * x;
            }
        }
    }

    // Residual-efficiency gradient among fitting bins.
    if !is_new_bin && fitting_bins_count > 2 && post_residual > 0 {
        let cohort = mean_residual.max(1.0);
        let rel = (r - cohort) / c;
        let depth = (fitting_bins_count as f64).min(6.0) / 6.0;
        if rel < 0.0 {
            score -= ((rel * -60.0) * (0.6 + 0.6 * depth)).min(4.0) * (0.5 + x);
        } else {
            score += ((rel * 40.0) * (0.6 + 0.6 * depth)).min(2.2) * (0.5 + x);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let r = post_residual as f64;
    let x = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = r / c;
