    }

    // MUTATION (gen 41): sliver-stranding guard — when the only fitting bins
    // would leave a residual that no realistic item (>= 1..=100) can pair
    // with the next item to consume, apply a late-stream penalty so the
    // placement shifts toward bins whose leftover stays usable.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 && fitting_bins_count <= 2 && x > 0.4 {
        let n = next_item_size as f64;
        if r < n && (r + n) < 0.15 * c {
            score += 2.0 * (1.0 - (r + n) / (0.15 * c)) * x;
        }
    }

    score
}

