        let n = next_item_size.max(1) as f64;
        if r >= n {
            let copies = (r / n).floor();
            let leftover = r - copies * n;
            if leftover == 0.0 && copies >= 2.0 {
                score -= (2.0 + copies.min(5.0)) * (0.6 + 0.6 * x);
