        }
        // Fresh-bin copy-count advantage — reward when the fresh bin can
        // absorb strictly more copies of the next item than the best open bin.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_copies = (fresh_left / n).floor();
            let open_copies = (r / n).floor();
            if fresh_copies > open_copies && fresh_copies >= 2.0 {
                penalty -= (2.0 + (fresh_copies - open_copies).min(3.0) * 1.5) * (0.5 + x);
