        // guarantees two more zero-waste placements but the open candidate
        // cannot even do one, opening fresh is clearly correct; reverse
        // strands capacity.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let after_f = fresh_left - n;
            let open_after = r - n;
            if after_f >= n && open_after < 0.0 {
