            }
        }
        if open_bins_count > 4 && mean_residual > 0.5 * c {
            penalty -= 4.0;
        }
        if next_item_size > 0 && open_bins_count > 0 {
            let n = next_item_size as f64;
            if r < n && n > 0.6 * c {
                penalty -= 7.0 + 5.0 * x;
            }
        }
        if x > 0.8 && item_size as f64 > 0.5 * c {
            penalty -= 5.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 1 && r > 0.6 * c && mean_residual < 0.35 * c {
            penalty -= 8.0;
        }
        if fitting_bins_count > 0 && open_bins_count > 0 {
            let slack = (bin_capacity - item_size) as f64;
            if slack < mean_residual * 0.5 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        penalty += 10.0 * x * x;
        if x > 0.95 && open_bins_count > 1 {
            penalty -= 4.0;
        }
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual > 0 {
            let n = next_item_size as f64;
            if r < n && r < 0.2 * c {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        // Compare best achievable post-residual on an open bin against the
        // fresh-bin leftover; prefer the new bin when it strands less waste.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            let fresh_left = c - item_size as f64;
            if r > 0.0 && r < n && fresh_left >= n {
                penalty -= 6.0 + 6.0 * x;
            }
            if fresh_left > 0.6 * c && r < 0.1 * c && open_bins_count > 0 {
                penalty -= 5.0;
            }
            if fresh_left >= n && fresh_left % n.max(1.0) < 1.0 {
                penalty -= 5.0 + 4.0 * x;
            }
        }
        if item_size as f64 > 0.55 * c && x < 0.25 && open_bins_count > 2 {
            penalty -= 5.0;
        }
        if open_bins_count > 5 && mean_residual < 0.25 * c {
            penalty -= 3.0 + 3.0 * x;
        }
        // Opening fresh is cheap when the only fitting bins strand less than
        // half the next item.
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual > 0
            && (post_residual as f64) < next_item_size as f64 * 0.5 {
            penalty -= 7.0 + 5.0 * x;
        }
        // Late stream with large mean residual — squeeze existing bins harder.
        if x > 0.6 && mean_residual > 0.45 * c {
            penalty += 4.0 + 4.0 * x;
        }
        // Waste-budget lookahead on fresh leftover.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size as f64;
            let fresh_left = c - item_size as f64;
            if fresh_left > 0.0 && fresh_left < n {
                penalty += 8.0 + 6.0 * x;
            }
            if fresh_left >= n && fresh_left < n * 1.5 {
                penalty -= 4.0 + 4.0 * x;
            }
        }
        // Mid-stream sprawl control.
        if x > 0.3 && x < 0.85 && open_bins_count > 6 && mean_residual > 0.3 * c {
            penalty += 3.0 + 3.0 * (open_bins_count as f64 - 6.0).min(6.0);
        }
        // Fresh-bin leftover divisibility — zero-waste chain guaranteed.
        if fitting_bins_count > 0 && next_item_size > 1 {
            let n = next_item_size as f64;
            let fresh_left = c - item_size as f64;
            if fresh_left >= n && (fresh_left as u32) % next_item_size == 0 {
                penalty -= 3.0 + 3.0 * x;
            }
        }
        // Total-waste ledger: fresh dead space vs open dead space.
        if fitting_bins_count > 0 && next_item_size > 0 {
            let n = next_item_size.max(1) as f64;
            let fresh_left = c - item_size as f64;
            let fresh_dead = if fresh_left >= n {
                let copies = (fresh_left / n).floor();
                fresh_left - copies * n
            } else { fresh_left };
            let open_dead = if r >= n {
                let copies = (r / n).floor();
                r - copies * n
            } else { r };
            let delta = fresh_dead - open_dead;
            if delta < -1.0 {
                penalty -= (delta.abs() * 0.7).min(9.0) * (0.5 + x);
            } else if delta > 1.0 {
                penalty += (delta * 0.7).min(9.0) * (0.5 + x);
            }
        }
        // Near-perfect fresh fill.
        {
            let fresh_left = c - item_size as f64;
            if fresh_left <= 5.0 {
                penalty -= 10.0;
            } else if fresh_left < 0.08 * c {
                penalty -= 6.0 * (1.0 - fresh_left / (0.08 * c));
            }
        }
        score += penalty;
    } else {
        score -= 0.05 * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
    }

    // Consolidation among many open bins.
    if open_bins_count > 3 {
        score += 0.03 * r * (open_bins_count as f64).ln();
    }

    // Late-stream consolidation.
    score -= 6.0 * x * (1.0 - p);

    // Mid-size residual flexibility preference.
    if post_residual > 0 {
        let half = 0.5 * c;
        if (r - half).abs() < 0.1 * c {
            score += 3.0 * (1.0 - x);
        }
    }

    // Gap-zone penalty for unsplittable residual bands.
    if post_residual > 0 {
        let gap_low = 25.0;
        let gap_high = 55.0;
        if r > gap_low && r < gap_high {
            let depth = 1.0 - ((r - gap_low) / (gap_high - gap_low) - 0.5).abs() * 2.0;
            score += depth * (2.5 + 2.5 * x);
        }
        if r >= 60.0 && r <= 100.0 {
            score -= 1.5 * (1.0 - x);
        }
    }

    // Reward residuals that are multiples of small common item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 2.0;
        } else if post_residual % 5 == 0 {
            score -= 1.0;
        }
    }

    // Dead-space shaping below the next item size.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n && r > n * 0.5 {
            let frac = 1.0 - r / n;
            score += (1.0 + 2.0 * x) * frac;
            if frac > 0.35 {
                score += 2.0 * x;
            }
        }
        if r > 0.0 && (r * 2.0 - n).abs() < 1.0 {
            score -= 2.0 * (1.0 - x);
        }
        if (r + n) % 10 == 0 && r + n <= c {
            score -= 1.5 + 1.5 * x;
        }
    }

    // Global compaction pressure — reward filling the fullest bin.
    if !is_new_bin {
        score -= 0.04 * (bin_residual as f64 / c) * (open_bins_count as f64).min(10.0).ln().max(0.0);
    }

    // Dead-space ratio shaping — penalize residuals below the smallest
    // plausible future item.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r < n {
            let dead_frac = (n - r) / n;
            score += dead_frac * dead_frac * (3.0 + 4.0 * x);
        }
    }

    // Live-residual yield — reward placements whose post-residual can still
    // hold the next item with room for a second copy.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= 2.0 * n {
            score -= (1.5 + 2.5 * x) * (r / c);
        } else if r >= n {
            score -= 0.5 + 1.0 * x;
        }
    }

    // MUTATION (gen 45): residual-harvest alignment — among fitting bins,
    // prefer the one whose post-residual is closest to a whole multiple of
    // the next item size, aligning leftovers with anticipated demand and
    // directly targeting the diagnosed dead-space weakness.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 0 {
        let n = next_item_size.max(1) as f64;
        let k = (r / n).round().max(1.0);
        let target = k * n;
        let miss = (r - target).abs();
        if miss < 0.5 * n {
            score -= (1.0 - miss / (0.5 * n)) * (1.8 + 1.8 * x);
        }
    }

    // MUTATION (gen 45): multi-copy exact-fill ledger.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 {
        let n = next_item_size.max(1) as f64;
        if r >= n {
            let copies = (r / n).floor();
            let leftover = r - copies * n;
            if leftover == 0.0 && copies >= 2.0 {
                score -= (2.0 + copies.min(5.0)) * (0.6 + 0.6 * x);
            } else if leftover > 0.0 && leftover < 3.0 {
                score += 1.5 + 1.5 * x;
            }
        }
    }

    // MUTATION (gen 45): cohort-relative snugness sweep.
    if !is_new_bin && fitting_bins_count > 1 && next_item_size > 0 && post_residual > 0 {
        let n = next_item_size.max(1) as f64;
        let half_n = n * 0.5;
        if r >= half_n {
            let closeness = 1.0 - ((r - half_n) / (c - half_n)).min(1.0);
            score -= 1.6 * closeness * closeness * (0.4 + x);
        } else {
            score += 1.2 * (1.0 - r / half_n) * (0.5 + x);
        }
