            score += dead_frac * dead_frac * (3.0 + 4.0 * x);
        }
    }

    // Live-residual yield — reward placements leaving a two-copy horizon.
    if post_residual > 0 && next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= 2.0 * n {
            score -= (1.5 + 2.5 * x) * (r / c);
        } else if r >= n {
            score -= 0.5 + 1.0 * x;
        }
    }

    // Residual-harvest pressure — prefer post-residuals near a small multiple
    // of the next item size, aligning leftovers with anticipated demand.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 && fitting_bins_count > 0 {
        let n = next_item_size.max(1) as f64;
        let k = (r / n).round().max(1.0);
        let target = k * n;
        let miss = (r - target).abs();
        if miss < 0.5 * n {
            score -= (1.0 - miss / (0.5 * n)) * (1.5 + 1.5 * x);
        }
    }

    // Multi-copy exact-fill ledger.
    if !is_new_bin && next_item_size > 0 && post_residual > 0 {
        let n = next_item_size.max(1) as f64;
        if r >= n {
            let copies = (r / n).floor();
            let leftover = r - copies * n;
            if leftover == 0.0 && copies >= 2.0 {
                score -= (2.0 + copies.min(5.0)) * (0.6 + 0.6 * x);
            } else if leftover > 0.0 && leftover < 3.0 {
                score += 1.5 + 1.5 * x;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
